/* ===================== core/ds_common.h ===================== */
/*
 * PURPOSE: Common status codes, error reporting, and checked memory allocation.
 * WHY THIS NAME: ds_common defines shared primitives across the core C library.
 * CONNECTS TO: All core/ data structure modules.
 * COMPLEXITY: O(1) for memory wrappers.
 */




typedef enum {
    DS_OK = 0,
    DS_ERR_NOMEM,
    DS_ERR_ARG,
    DS_ERR_EMPTY,
    DS_ERR_NOTFOUND,
    DS_ERR_EXISTS,
    DS_ERR_FULL
} ds_status;

const char *ds_status_str(ds_status s);

void *ds_xmalloc(size_t size);
void *ds_xcalloc(size_t nmemb, size_t size);
void *ds_xrealloc(void *ptr, size_t size);

/* ===================== core/ds_bitset.h ===================== */
/*
 * PURPOSE: Word-level bitset (uint64_t words) with popcount, run search, and hex serialization.
 * WHY THIS NAME: ds_bitset manages compact seat availability and bitmask operations.
 * CONNECTS TO: Seat layout tracking (row 3), group seat booking search, save files.
 * COMPLEXITY:
 *   - set/clear/test/flip: O(1)
 *   - count (popcount): O(n/64)
 *   - find_clear_run: O(to - from)
 * INVARIANTS: bits beyond nbits in the last word are always kept zero.
 */




typedef struct ds_bitset ds_bitset;

ds_bitset *ds_bitset_create(size_t nbits);
ds_status ds_bitset_set(ds_bitset *bs, size_t i);
ds_status ds_bitset_clear(ds_bitset *bs, size_t i);
int ds_bitset_test(const ds_bitset *bs, size_t i);
ds_status ds_bitset_flip(ds_bitset *bs, size_t i);
size_t ds_bitset_count(const ds_bitset *bs);
long ds_bitset_find_clear_run(const ds_bitset *bs, size_t from, size_t to, size_t k);
ds_status ds_bitset_to_hex(const ds_bitset *bs, char *buf, size_t cap);
ds_status ds_bitset_from_hex(ds_bitset *bs, const char *hex);
ds_bitset *ds_bitset_copy(const ds_bitset *bs);
void ds_bitset_destroy(ds_bitset *bs);

/* ===================== core/ds_fenwick.h ===================== */
/*
 * PURPOSE: Fenwick (Binary Indexed) tree: point update + prefix/range sums on int64.
 * WHY THIS NAME: named after Peter Fenwick, who described it.
 * CONNECTS TO: app/vendor (revenue per day over a 90-day horizon).
 * COMPLEXITY: add/prefix/range O(log n); space O(n).
 * INVARIANTS: tree[i] (1-based) holds the sum of the lowest_set_bit(i) elements ending at i.
 */
typedef struct ds_fenwick ds_fenwick;
ds_fenwick *ds_fenwick_create(size_t n);
void ds_fenwick_add(ds_fenwick *f, size_t i, int64_t delta);   /* 0-based index */
int64_t ds_fenwick_prefix(const ds_fenwick *f, size_t i);      /* sum of [0..i] */
int64_t ds_fenwick_range(const ds_fenwick *f, size_t l, size_t r); /* sum of [l..r] */
void ds_fenwick_destroy(ds_fenwick *f);

/* ===================== core/ds_graph.h ===================== */
/*
 * PURPOSE: Weighted directed graph (adjacency lists) with Dijkstra and BFS.
 * WHY THIS NAME: cities are vertices, bus routes are directed edges.
 * CONNECTS TO: app/search (journey planner), ds_heap (priority queue for Dijkstra).
 * COMPLEXITY: Dijkstra O((V+E) log V); BFS O(V+E); path rebuild O(path length).
 * INVARIANTS: every edge has u,v in [0,n); weights >= 0 (needed for Dijkstra).
 */
typedef struct ds_graph ds_graph;
#define DS_INF INT64_C(0x3fffffffffffffff)
ds_graph *ds_graph_create(size_t n_vertices);
ds_status ds_graph_add_edge(ds_graph *g, int u, int v, int64_t w_minutes, int64_t w_paise, int edge_id);
/* dist[], prev_vertex[], prev_edge[] must each hold n_vertices entries.
 * use_paise=0: weight = minutes; 1: weight = paise.
 * layover is added for every leg that starts at a vertex other than src. */
ds_status ds_graph_dijkstra(const ds_graph *g, int src, int use_paise, int64_t layover,
                            int64_t *dist, int *prev_vertex, int *prev_edge);
ds_status ds_graph_bfs_fewest_legs(const ds_graph *g, int src, int *legs,
                                   int *prev_vertex, int *prev_edge);
/* Writes src..dst into out_path; returns length or 0 when unreachable. */
size_t ds_graph_path(const int *prev_vertex, int src, int dst, int *out_path, size_t cap);
size_t ds_graph_size(const ds_graph *g);
void ds_graph_destroy(ds_graph *g);

/* ===================== core/ds_hash.h ===================== */
/*
 * PURPOSE: Hash table using separate chaining, FNV-1a hashing, and dynamic resizing.
 * WHY THIS NAME: ds_hash provides O(1) key-value dictionary and set operations.
 * CONNECTS TO: PNR lookups, user email index, coupon verification, alert deduplication.
 * COMPLEXITY:
 *   - get/put/remove: average O(1), worst O(n)
 * INVARIANTS: load factor <= 0.75; all entries in bucket b have hash(key) % num_buckets == b.
 */




typedef struct ds_hash ds_hash;

ds_hash *ds_hash_create_str(size_t value_size, void (*free_value)(void *));
ds_hash *ds_hash_create(size_t key_size, size_t value_size,
                        uint64_t (*hash)(const void *),
                        int (*eq)(const void *, const void *),
                        void (*free_value)(void *));

ds_status ds_hash_put(ds_hash *h, const void *key, const void *value);
void *ds_hash_get(const ds_hash *h, const void *key);
int ds_hash_contains(const ds_hash *h, const void *key);
ds_status ds_hash_remove(ds_hash *h, const void *key);
size_t ds_hash_size(const ds_hash *h);
void ds_hash_foreach(const ds_hash *h, void (*fn)(const void *key, void *value, void *ctx), void *ctx);
void ds_hash_destroy(ds_hash *h);

/* ===================== core/ds_heap.h ===================== */
/*
 * PURPOSE: Binary min-heap keyed by int64_t priority with O(log n) decrease-key / remove by id.
 * WHY THIS NAME: ds_heap provides priority queue operations with id tracking.
 * CONNECTS TO: Seat-hold expiry (row 4), simulator event queue, and Dijkstra algorithm (row 9).
 * COMPLEXITY:
 *   - peek_min: O(1)
 *   - push/pop/update/remove: O(log n)
 * INVARIANTS:
 *   - heap[i].priority <= heap[2*i + 1].priority and heap[2*i + 2].priority.
 *   - pos_map maintains exact index of each active id in the heap array.
 */




typedef struct ds_heap ds_heap;

ds_heap *ds_heap_create(void);
ds_status ds_heap_push(ds_heap *h, int64_t priority, uint64_t id);
ds_status ds_heap_peek_min(const ds_heap *h, int64_t *priority, uint64_t *id);
ds_status ds_heap_pop_min(ds_heap *h, int64_t *priority, uint64_t *id);
ds_status ds_heap_update(ds_heap *h, uint64_t id, int64_t new_priority);
ds_status ds_heap_remove(ds_heap *h, uint64_t id);
size_t ds_heap_size(const ds_heap *h);
void ds_heap_destroy(ds_heap *h);

/* ===================== core/ds_list.h ===================== */
/*
 * PURPOSE: Doubly linked list supporting O(1) splice, insert, and remove.
 * WHY THIS NAME: ds_list provides standard linked list semantics in pure C.
 * CONNECTS TO: Route stop sequence (section 6 row 7) and LRU recency list.
 * COMPLEXITY:
 *   - push/insert/remove given node: O(1)
 *   - traversal: O(n)
 * INVARIANTS: head->prev == NULL; tail->next == NULL; size equals count of nodes.
 */




typedef struct ds_list ds_list;
typedef struct ds_list_node ds_list_node;

ds_list *ds_list_create(size_t elem_size, void (*free_elem)(void *));
ds_list_node *ds_list_push_back(ds_list *list, const void *elem);
ds_list_node *ds_list_push_front(ds_list *list, const void *elem);
ds_list_node *ds_list_insert_after(ds_list *list, ds_list_node *node, const void *elem);
ds_list_node *ds_list_insert_before(ds_list *list, ds_list_node *node, const void *elem);
ds_status ds_list_remove(ds_list *list, ds_list_node *node);

ds_list_node *ds_list_front(const ds_list *list);
ds_list_node *ds_list_back(const ds_list *list);
ds_list_node *ds_list_next(const ds_list_node *node);
ds_list_node *ds_list_prev(const ds_list_node *node);
void *ds_list_data(ds_list_node *node);
size_t ds_list_size(const ds_list *list);
void ds_list_destroy(ds_list *list);

/* ===================== core/ds_lru.h ===================== */
/*
 * PURPOSE: LRU cache: hash table (key -> node) + doubly linked list (recency order).
 * WHY THIS NAME: "Least Recently Used" entries are evicted first.
 * CONNECTS TO: app/tracking (memoised ETA / geometry), ds_hash, ds_list.
 * COMPLEXITY: get/put O(1) average.
 * INVARIANTS: list front = most recent; size <= capacity; every list node has one hash entry.
 * Keys are C strings up to 63 chars. Values are copied (value_size bytes).
 */
typedef struct ds_lru ds_lru;
ds_lru *ds_lru_create(size_t capacity, size_t value_size, void (*free_value)(void *));
void *ds_lru_get(ds_lru *c, const char *key);                 /* marks as most recent */
ds_status ds_lru_put(ds_lru *c, const char *key, const void *value);
size_t ds_lru_size(const ds_lru *c);
void ds_lru_destroy(ds_lru *c);

/* ===================== core/ds_queue.h ===================== */
/*
 * PURPOSE: Circular array FIFO queue that grows by doubling.
 * WHY THIS NAME: ds_queue provides FIFO waitlist and notification outbox semantics.
 * CONNECTS TO: Waitlist per sold-out trip (row 5) and notification dispatch queue.
 * COMPLEXITY:
 *   - enqueue: amortised O(1)
 *   - dequeue/peek: O(1)
 * INVARIANTS: head and tail wrap around capacity modulo; size <= capacity.
 */




typedef struct ds_queue ds_queue;

ds_queue *ds_queue_create(size_t elem_size, void (*free_elem)(void *));
ds_status ds_queue_enqueue(ds_queue *q, const void *elem);
ds_status ds_queue_dequeue(ds_queue *q, void *out);
void *ds_queue_peek(const ds_queue *q);
size_t ds_queue_size(const ds_queue *q);
void ds_queue_destroy(ds_queue *q);

/* ===================== core/ds_ring.h ===================== */
/*
 * PURPOSE: Fixed-capacity ring buffer of timestamped values with running sum for rolling averages.
 * WHY THIS NAME: ds_ring provides circular sliding-window telemetry buffers.
 * CONNECTS TO: Average speed of last 10 minutes of GPS fixes (row 14).
 * COMPLEXITY:
 *   - push: O(1)
 *   - evict_before: amortised O(1)
 *   - mean/count: O(1)
 * INVARIANTS: running_sum equals sum of all active values currently in the window.
 */




typedef struct ds_ring ds_ring;

ds_ring *ds_ring_create(size_t capacity);
void ds_ring_push(ds_ring *r, int64_t t_ms, double value);
void ds_ring_evict_before(ds_ring *r, int64_t t_ms);
size_t ds_ring_count(const ds_ring *r);
double ds_ring_mean(const ds_ring *r);
void ds_ring_destroy(ds_ring *r);

/* ===================== core/ds_search.h ===================== */
/*
 * PURPOSE: Binary search (lower/upper bound) and KMP substring search.
 * WHY THIS NAME: ds_search groups the searching algorithms.
 * CONNECTS TO: app/search (time-window filters), app/tracking (stop lookup), operator-name search.
 * COMPLEXITY: bounds O(log n); KMP O(n + m).
 * INVARIANTS: arrays given to the bound functions must already be sorted by the same cmp.
 */
/* first index whose element is >= key (n if none) */
size_t ds_lower_bound(const void *base, size_t n, size_t size, const void *key,
                      int (*cmp)(const void *, const void *));
/* first index whose element is > key (n if none) */
size_t ds_upper_bound(const void *base, size_t n, size_t size, const void *key,
                      int (*cmp)(const void *, const void *));
long ds_binary_search(const void *base, size_t n, size_t size, const void *key,
                      int (*cmp)(const void *, const void *));          /* index or -1 */
/* Failure table: fail must hold strlen(pattern) ints. */
void ds_kmp_failure(const char *pattern, int *fail);
long ds_kmp_find(const char *text, const char *pattern);                /* first index or -1 */
size_t ds_kmp_find_all(const char *text, const char *pattern, size_t *out, size_t cap);
/* Case-insensitive contains (uses KMP on lower-cased copies). */
int ds_kmp_contains_nocase(const char *text, const char *pattern);

/* ===================== core/ds_sort.h ===================== */
/*
 * PURPOSE: Hand-written generic sorts: stable merge sort, quicksort, heapsort.
 * WHY THIS NAME: ds_sort groups the O(n log n) sorting algorithms.
 * CONNECTS TO: app/search (result sorting), app/vendor (trips by start time), bench.
 * COMPLEXITY: merge O(n log n) always + O(n) extra space, stable;
 *             quick O(n log n) average, O(n^2) worst (median-of-three makes it rare);
 *             heap O(n log n) always, O(1) extra space, not stable.
 * INVARIANTS: cmp returns <0, 0, >0 like strcmp.
 */
typedef int (*ds_cmp_fn)(const void *, const void *);
ds_status ds_merge_sort(void *base, size_t n, size_t size, ds_cmp_fn cmp);
void ds_quick_sort(void *base, size_t n, size_t size, ds_cmp_fn cmp);
void ds_heap_sort(void *base, size_t n, size_t size, ds_cmp_fn cmp);
int ds_is_sorted(const void *base, size_t n, size_t size, ds_cmp_fn cmp);

/* ===================== core/ds_stack.h ===================== */
/*
 * PURPOSE: Array-based LIFO stack for undo operations and state navigation.
 * WHY THIS NAME: ds_stack provides classic LIFO stack primitives in pure C.
 * CONNECTS TO: Vendor undo history (row 6) and screen back navigation.
 * COMPLEXITY:
 *   - push/pop/top: O(1) amortised
 * INVARIANTS: top element is at index size - 1.
 */




typedef struct ds_stack ds_stack;

ds_stack *ds_stack_create(size_t elem_size, void (*free_elem)(void *));
ds_status ds_stack_push(ds_stack *s, const void *elem);
ds_status ds_stack_pop(ds_stack *s, void *out);
void *ds_stack_top(const ds_stack *s);
size_t ds_stack_size(const ds_stack *s);
void ds_stack_destroy(ds_stack *s);

/* ===================== core/ds_trie.h ===================== */
/*
 * PURPOSE: Prefix tree (trie) for city autosuggest: "Del" -> Delhi.
 * WHY THIS NAME: a "trie" (from re-TRIE-val) stores words letter by letter.
 * CONNECTS TO: app/catalog (city names), app/cli (search prompts).
 * COMPLEXITY: insert/find O(L), suggest O(L + k) (L = word length, k = output size).
 * INVARIANTS: children[c] is NULL or a node whose path spells the prefix;
 *             suggestions are produced by depth-first walk in slot order = alphabetical.
 * Alphabet (32 slots): a-z, space, hyphen, apostrophe, dot. Case-insensitive.
 */
typedef struct ds_trie ds_trie;
ds_trie *ds_trie_create(void);
ds_status ds_trie_insert(ds_trie *t, const char *word, int value);
int ds_trie_find(const ds_trie *t, const char *word, int *value);          /* 1 found, 0 not */
size_t ds_trie_suggest(const ds_trie *t, const char *prefix, size_t max,
                       char out[][64], int values[]);
void ds_trie_destroy(ds_trie *t);

/* ===================== core/ds_unionfind.h ===================== */
/*
 * PURPOSE: Union-Find (disjoint sets) with path compression and union by rank.
 * WHY THIS NAME: two operations: find a set's leader, union two sets.
 * CONNECTS TO: app/catalog ("is there any route A->B?", count of bus networks).
 * COMPLEXITY: near O(1) amortised (inverse Ackermann).
 * INVARIANTS: parent[root] == root; rank only grows at roots.
 */
typedef struct ds_unionfind ds_unionfind;
ds_unionfind *ds_uf_create(size_t n);
int ds_uf_find(ds_unionfind *u, int x);
int ds_uf_unite(ds_unionfind *u, int a, int b);       /* 1 if merged, 0 if already joined */
int ds_uf_connected(ds_unionfind *u, int a, int b);
size_t ds_uf_count(const ds_unionfind *u);            /* number of separate sets */
void ds_uf_destroy(ds_unionfind *u);

/* ===================== core/ds_vector.h ===================== */
/*
 * PURPOSE: Generic dynamic array container that grows exponentially.
 * WHY THIS NAME: ds_vector mirrors standard vector semantics in pure C.
 * CONNECTS TO: search results, stop buffers, sort benchmarks.
 * COMPLEXITY:
 *   - push/pop: amortised O(1)
 *   - at: O(1)
 *   - insert/remove: O(n)
 * INVARIANTS: capacity >= size; data buffer holds size * elem_size bytes.
 */




typedef struct ds_vector ds_vector;

ds_vector *ds_vector_create(size_t elem_size, void (*free_elem)(void *));
ds_status ds_vector_push(ds_vector *v, const void *elem);
void *ds_vector_at(const ds_vector *v, size_t i);
ds_status ds_vector_pop(ds_vector *v, void *out);
ds_status ds_vector_insert(ds_vector *v, size_t i, const void *elem);
