/* ===================== app/clock.cpp ===================== */
/*
 * PURPOSE: IST calendar arithmetic (no DST) using the days-from-civil algorithm.
 * WHY THIS NAME: implements clock.hpp.
 * CONNECTS TO: clock.hpp
 * COMPLEXITY: O(1).
 */

namespace sr {

/* Days since 1970-01-01 for a civil date (proleptic Gregorian). */
static int64_t days_from_civil(int y, int m, int d) {
    y -= m <= 2;
    int64_t era = (y >= 0 ? y : y - 399) / 400;
    int64_t yoe = y - era * 400;
    int64_t doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    int64_t doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

static void civil_from_days(int64_t z, int *y, int *m, int *d) {
    z += 719468;
    int64_t era = (z >= 0 ? z : z - 146096) / 146097;
    int64_t doe = z - era * 146097;
    int64_t yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    int64_t yy = yoe + era * 400;
    int64_t doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    int64_t mp = (5 * doy + 2) / 153;
    *d = (int)(doy - (153 * mp + 2) / 5 + 1);
    *m = (int)(mp < 10 ? mp + 3 : mp - 9);
    *y = (int)(yy + (*m <= 2));
}

static int64_t floor_div(int64_t a, int64_t b) { return a >= 0 ? a / b : -((-a + b - 1) / b); }

int64_t day_number(int64_t utc_ms) { return floor_div(utc_ms + IST_OFFSET_MS, MS_DAY); }

Civil to_ist(int64_t utc_ms) {
    int64_t local = utc_ms + IST_OFFSET_MS;
    int64_t days = floor_div(local, MS_DAY);
    int64_t rem = local - days * MS_DAY;
    Civil c{};
    civil_from_days(days, &c.year, &c.month, &c.day);
    c.hour = (int)(rem / MS_HOUR);
    c.minute = (int)((rem % MS_HOUR) / MS_MIN);
    c.second = (int)((rem % MS_MIN) / 1000);
    c.weekday = (int)(((days % 7) + 11) % 7);       /* 1970-01-01 was a Thursday (4) */
    return c;
}

int64_t from_ist(int y, int m, int d, int hh, int mm) {
    return days_from_civil(y, m, d) * MS_DAY + hh * MS_HOUR + mm * MS_MIN - IST_OFFSET_MS;
}

static const char *WEEKDAY[7] = {"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"};
static const char *MONTH[12] = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};

std::string fmt_date(int64_t ms) {
    Civil c = to_ist(ms);
    char buf[48];
    std::snprintf(buf, sizeof buf, "%s %02d %s %d", WEEKDAY[c.weekday], c.day, MONTH[c.month - 1], c.year);
    return buf;
}

std::string fmt_hm(int64_t ms) {
    Civil c = to_ist(ms);
    char buf[16];
    std::snprintf(buf, sizeof buf, "%02d:%02d", c.hour, c.minute);
    return buf;
}

std::string fmt_datetime(int64_t ms) { return fmt_date(ms) + ", " + fmt_hm(ms) + " IST"; }

std::string fmt_hm_plus(int64_t ms, int64_t ref) {
    int64_t diff = day_number(ms) - day_number(ref);
    std::string s = fmt_hm(ms);
    if (diff > 0) s += " +" + std::to_string(diff);
    return s;
}

std::string fmt_duration(int minutes) {
    char buf[24];
    std::snprintf(buf, sizeof buf, "%dh%02dm", minutes / 60, minutes % 60);
    return buf;
}

bool parse_ist_date(const char *t, int *y, int *m, int *d) {
    int n = 0;
    if (std::sscanf(t, "%4d-%2d-%2d%n", y, m, d, &n) != 3 || t[n] != '\0') return false;
    if (*m < 1 || *m > 12 || *d < 1 || *d > 31 || *y < 1970 || *y > 2200) return false;
    Civil c = to_ist(from_ist(*y, *m, *d, 12, 0));      /* reject 31 Feb etc. by round-trip */
    return c.year == *y && c.month == *m && c.day == *d;
}

bool parse_ist_datetime(const char *t, int64_t *out) {
    int y, m, d, hh, mm, n = 0;
    if (std::sscanf(t, "%4d-%2d-%2d %2d:%2d%n", &y, &m, &d, &hh, &mm, &n) != 5 || t[n] != '\0') return false;
    char datebuf[16];
    std::snprintf(datebuf, sizeof datebuf, "%04d-%02d-%02d", y, m, d);
    int yy, mo, dd;
    if (!parse_ist_date(datebuf, &yy, &mo, &dd) || hh < 0 || hh > 23 || mm < 0 || mm > 59) return false;
    *out = from_ist(y, m, d, hh, mm);
    return true;
}

int date_key(int64_t ms) {
    Civil c = to_ist(ms);
    return c.year * 10000 + c.month * 100 + c.day;
}

int64_t ist_midnight(int64_t ms) { return day_number(ms) * MS_DAY - IST_OFFSET_MS; }

}  // namespace sr

/* ===================== app/coupons.cpp ===================== */
/*
 * PURPOSE: Coupon validation and discount calculation (one coupon per booking).
 * WHY THIS NAME: "coupons" = promo codes.
 * CONNECTS TO: idx_coupon (hash lookup by code, row 2), money.hpp, booking.cpp.
 * COMPLEXITY: O(1) lookup + O(uses) to count a user's earlier redemptions.
 */

namespace sr {

static std::string upper(std::string s) {
    for (char &c : s) c = (char)std::toupper((unsigned char)c);
    return s;
}

/* True when `code` appears in the ';'-separated allowed list (or the list is ALL). */
static bool type_allowed(const char *allowed, const char *code) {
    if (std::strcmp(allowed, "ALL") == 0) return true;
    for (const std::string &item : split_fields(allowed, ';')) if (item == code) return true;
    return false;
}

Result<int64_t> App::coupon_discount(const char *code, int64_t base, const BusType &bt, int user_id) const {
    int *ci = idx_coupon.get(upper(code));
    if (!ci) return Result<int64_t>::fail(Err::VALIDATION, "Unknown coupon code");
    const Coupon &c = coupons[(size_t)*ci];
    if (!c.active) return Result<int64_t>::fail(Err::VALIDATION, "This coupon is not active");
    if (clock.now() > (base_day + c.valid_days) * MS_DAY) return Result<int64_t>::fail(Err::VALIDATION, "This coupon has expired");
    if (base < c.min_base) return Result<int64_t>::fail(Err::VALIDATION, "Coupon needs a minimum fare of " + fmt_rs(c.min_base));
    if (!type_allowed(c.allowed, bt.code)) return Result<int64_t>::fail(Err::VALIDATION, "Coupon is not valid for this bus type");
    int total_uses = 0, user_uses = 0;
    for (size_t i = 0; i < coupon_uses.size(); i++) {
        if (coupon_uses[i].coupon_idx != *ci) continue;
        total_uses++;
        if (coupon_uses[i].user_id == user_id) user_uses++;
    }
    if (total_uses >= c.max_uses) return Result<int64_t>::fail(Err::VALIDATION, "This coupon is fully redeemed");
    if (user_uses >= c.per_user_limit) return Result<int64_t>::fail(Err::VALIDATION, "You have already used this coupon the maximum number of times");
    int64_t discount = c.is_percent ? percent_round(base, c.value) : c.value;
    if (c.is_percent && c.max_discount > 0) discount = std::min(discount, c.max_discount);
    return Result<int64_t>::success(std::min(discount, base));        /* never more than the base fare */
}

}  // namespace sr

/* ===================== app/csv.cpp ===================== */
/*
 * PURPOSE: CSV reader implementation.
 * WHY THIS NAME: implements csv.hpp.
 * CONNECTS TO: csv.hpp
 * COMPLEXITY: O(file size).
 */

namespace sr {

std::vector<std::string> split_fields(const std::string &text, char sep) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : text) {
        if (c == sep) { out.push_back(cur); cur.clear(); }
        else cur += c;
    }
    out.push_back(cur);
    return out;
}

/* Splits one CSV line honouring "double quotes" (a doubled "" inside quotes is one quote). */
static bool parse_line(const std::string &line, std::vector<std::string> *fields) {
    std::string cur;
    bool quoted = false;
    for (size_t i = 0; i < line.size(); i++) {
        char c = line[i];
        if (quoted) {
            if (c == '"' && i + 1 < line.size() && line[i + 1] == '"') { cur += '"'; i++; }
            else if (c == '"') quoted = false;
            else cur += c;
        } else if (c == '"') quoted = true;
        else if (c == ',') { fields->push_back(cur); cur.clear(); }
        else if (c != '\r') cur += c;
    }
    fields->push_back(cur);
    return !quoted;                                  /* false = unterminated quote */
}

bool csv_read(const std::string &path, size_t columns, std::vector<CsvRow> *rows, std::string *error) {
    std::ifstream in(path);
    if (!in) { *error = path + ": cannot open file"; return false; }
    std::string line;
    int line_no = 0;
    bool header_seen = false;
    while (std::getline(in, line)) {
        line_no++;
        if (line.empty() || line[0] == '#' || line == "\r") continue;
        CsvRow row{line_no, {}};
        if (!parse_line(line, &row.fields)) { *error = path + ":" + std::to_string(line_no) + ": unterminated quote"; return false; }
        if (row.fields.size() != columns) {
            *error = path + ":" + std::to_string(line_no) + ": expected " + std::to_string(columns) +
                     " columns but found " + std::to_string(row.fields.size());
            return false;
        }
        if (!header_seen) { header_seen = true; continue; }
        rows->push_back(row);
    }
    return true;
}

}  // namespace sr

/* ===================== app/money.cpp ===================== */
/*
 * PURPOSE: Implements the fare and refund formulas (see money.hpp).
 * WHY THIS NAME: implements money.hpp.
 * CONNECTS TO: clock.hpp (MS_HOUR).
 * COMPLEXITY: O(1).
 */

namespace sr {

/* Indian digit grouping: 1,23,456. */
static std::string group_indian(int64_t rupees) {
    std::string s = std::to_string(rupees);
    if (s.size() <= 3) return s;
    std::string last3 = s.substr(s.size() - 3), rest = s.substr(0, s.size() - 3), out;
    while (rest.size() > 2) { out = "," + rest.substr(rest.size() - 2) + out; rest.resize(rest.size() - 2); }
    return rest + out + "," + last3;
}

std::string fmt_rs(int64_t paise) {
    bool neg = paise < 0;
    int64_t a = neg ? -paise : paise;
    char frac[8];
    std::snprintf(frac, sizeof frac, ".%02d", (int)(a % 100));
    return std::string(neg ? "-" : "") + "Rs " + group_indian(a / 100) + frac;
}

int64_t seat_fare_paise(int km, int rate, bool lower_berth) {
    int64_t units = ((int64_t)km * rate + 500) / 1000;            /* round(km*rate/1000) */
    int64_t rupees = units * 10;                                  /* rounded to nearest Rs 10 */
    if (lower_berth) rupees = (rupees * 110 + 50) / 100;          /* lower berth x1.10 */
    return rupees * 100;
}

int64_t percent_round(int64_t amount, int64_t pct) { return (amount * pct + 50) / 100; }
int64_t tax_paise(int64_t taxable) { return percent_round(taxable, 5); }
int64_t deposit_paise(int64_t total) { return percent_round(total, 20); }

int refund_percent(int64_t ms) {
    if (ms >= 72 * MS_HOUR) return 100;
    if (ms >= 24 * MS_HOUR) return 80;
    if (ms >= 6 * MS_HOUR) return 50;
    return 0;
}

int64_t refund_paise(int64_t paid, int64_t total, int64_t insurance, int64_t already, int pct) {
    int64_t refundable = std::min(paid, total - insurance);        /* insurance is never refunded */
    if (refundable < 0) refundable = 0;
    int64_t amount = refundable * pct / 100 - already;
    return amount < 0 ? 0 : amount;
}

int planned_drive_minutes(int km, int avg) { return (km * 60 + avg / 2) / avg; }

}  // namespace sr

/* ===================== app/notifications.cpp ===================== */
/*
 * PURPOSE: The notification outbox (queue) and the single "bell" list with unread counts and preferences.
 * WHY THIS NAME: "notifications" = alerts shown to a user.
 * CONNECTS TO: core/ds_queue (outbox, row 5), core/ds_hash (dedupe set, row 19), storage (log file).
 * COMPLEXITY: notify O(1) average; flush O(k) for k queued alerts.
 */

namespace sr {

void App::notify(int user_id, int kind, const std::string &title, const std::string &body, const std::string &dedupe_key) {
    if (!dedupe_key.empty()) {
        if (alert_seen.has(dedupe_key)) return;           /* already sent once: drop duplicate */
        alert_seen.put(dedupe_key, 1);
    }
    Notification n;
    std::memset(&n, 0, sizeof n);
    n.user_id = user_id;
    n.kind = kind;
    std::snprintf(n.title, sizeof n.title, "%s", title.c_str());
    std::snprintf(n.body, sizeof n.body, "%s", body.c_str());
    std::snprintf(n.dedupe, sizeof n.dedupe, "%s", dedupe_key.c_str());
    n.created_ms = alert_time_ms ? alert_time_ms : clock.now();
    outbox.push(n);
}

void App::flush_outbox() {
    Notification n;
    std::ofstream log;
    if (!save_dir.empty()) log.open(save_dir + "/notifications.log", std::ios::app);
    while (outbox.pop(&n)) {
        const User *u = user_by_id(n.user_id);
        if (!u || !(u->prefs & (1 << n.kind))) continue;         /* user muted this category */
        n.id = (int)notes.size() + 1;
        notes.push(n);
        if (log) log << "[" << fmt_datetime(n.created_ms) << "] user " << n.user_id << " | " << n.title << " | " << n.body << "\n";
    }
}

int App::unread_count(int user_id) const {
    int c = 0;
    for (size_t i = 0; i < notes.size(); i++) if (notes[i].user_id == user_id && !notes[i].read) c++;
    return c;
}

void App::mark_all_read(int user_id) {
    for (size_t i = 0; i < notes.size(); i++) if (notes[i].user_id == user_id) notes[i].read = 1;
}

std::vector<const Notification *> App::notifications_for(int user_id) const {
    std::vector<const Notification *> out;
    for (size_t i = notes.size(); i-- > 0;) if (notes[i].user_id == user_id) out.push_back(notes.at(i));   /* newest first */
    return out;
}

void App::set_prefs(int user_id, int mask) {
    if (user_id >= 1 && (size_t)user_id <= users.size()) users[(size_t)user_id - 1].prefs = mask;
}

}  // namespace sr

/* ===================== app/ops.cpp ===================== */
/*
 * PURPOSE: The operations side of SmartRoute: driver console (duty list, start/end, GPS fixes, delay reports,
 *          boarding check-in), per-trip crew with overlap checks, staff off-duty rules, platform-admin figures
 *          (revenue by corridor, coupon controls, DEMO traffic scan) and shareable tracking links.
 * WHY THIS NAME: "ops" = operations; the original project kept these in opsRoutes.ts.
 * CONNECTS TO: app.hpp, core/geo (nearest point on the route), core/ds_sort (trips by departure), core/ds_hash (indexes).
 * COMPLEXITY: crew overlap check O(trips); revenue by corridor O(bookings); scans O(trips).
 * RULES: D13 (another company's data looks absent); a driver sees only trips whose crew includes them.
 */

extern "C" {
}

namespace sr {

static int cmp_trip_depart(const void *a, const void *b) {
    int64_t x = (*static_cast<Trip *const *>(a))->depart_ms, y = (*static_cast<Trip *const *>(b))->depart_ms;
    return (x > y) - (x < y);
}

static void sort_trips(std::vector<Trip *> &v) {
    if (v.size() > 1) ds_merge_sort(v.data(), v.size(), sizeof(Trip *), cmp_trip_depart);    /* stable merge sort by departure */
}

static std::string upper_trim(const std::string &s) {
    size_t a = 0, b = s.size();
    while (a < b && std::isspace((unsigned char)s[a])) a++;
    while (b > a && std::isspace((unsigned char)s[b - 1])) b--;
    std::string o = s.substr(a, b - a);
    for (char &c : o) c = (char)std::toupper((unsigned char)c);
    return o;
}

/* ---------- who is on a trip ---------- */

int App::trip_driver(const Trip &t) const {
    if (t.auto_driver > 0) return t.auto_driver;                  /* a per-trip assignment beats the bus default */
    return buses[(size_t)t.bus_idx].driver_id > 0 ? buses[(size_t)t.bus_idx].driver_id : 0;
}

int App::trip_conductor(const Trip &t) const {
    if (t.auto_conductor > 0) return t.auto_conductor;
    return buses[(size_t)t.bus_idx].conductor_id > 0 ? buses[(size_t)t.bus_idx].conductor_id : 0;
}

bool App::driver_can_access(const User &u, const Trip &t) const {
    if (u.role == ROLE_ADMIN) return true;
    return u.role == ROLE_DRIVER && u.staff_id > 0 && trip_driver(t) == u.staff_id;
}

std::vector<Trip *> App::trips_on_date(int dk, int company_id) {
    std::vector<Trip *> out;
    for (size_t si = 0; si < schedules.size(); si++) {
        if (company_id && buses[(size_t)schedules[si].bus_idx].company_id != company_id) continue;
        if (Trip *t = get_or_create_trip((int)si, dk)) out.push_back(t);
    }
    sort_trips(out);
    return out;
}

std::vector<Trip *> App::driver_trips(const User &u) {
    std::vector<Trip *> out;
    int company = u.role == ROLE_ADMIN ? 0 : u.company_id;
    for (int d = 0; d < 2; d++)                                     /* today and tomorrow */
        for (Trip *t : trips_on_date(date_key(clock.now() + d * MS_DAY), company))
            if (driver_can_access(u, *t)) out.push_back(t);
    for (size_t i = 0; i < trips.size(); i++) {                     /* a trip still on the road from an earlier day */
        Trip *t = *trips.at(i);
        if (t->status == TRIP_RUNNING && driver_can_access(u, *t) && std::find(out.begin(), out.end(), t) == out.end()) out.push_back(t);
    }
    sort_trips(out);
    return out;
}

Result<Unit> App::driver_start(const User &u, int trip_id) {
    Trip *t = trip_by_id(trip_id);
    if (!t || !driver_can_access(u, *t)) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    return start_trip(buses[(size_t)t->bus_idx].company_id, trip_id);
}

Result<Unit> App::driver_end(const User &u, int trip_id) {
    Trip *t = trip_by_id(trip_id);
    if (!t || !driver_can_access(u, *t)) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    return complete_trip(buses[(size_t)t->bus_idx].company_id, trip_id);
}

/* A GPS fix is range-checked, snapped to the nearest point of the route, stored, and fed to the same alert engine the simulator uses. */
Result<Unit> App::driver_position(const User &u, int trip_id, double lat, double lng, double speed, double heading, double accuracy) {
    Trip *t = trip_by_id(trip_id);
    if (!t || !driver_can_access(u, *t)) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    if (!(lat >= -90 && lat <= 90) || !(lng >= -180 && lng <= 180)) return Result<Unit>::fail(Err::VALIDATION, "Latitude must be -90 to 90 and longitude -180 to 180");
    if (!(speed >= 0 && speed <= 160)) return Result<Unit>::fail(Err::VALIDATION, "Speed must be 0 to 160 km/h");
    if (!(accuracy >= 0 && accuracy <= 5000)) return Result<Unit>::fail(Err::VALIDATION, "Accuracy must be 0 to 5000 metres");
    if (!(heading >= 0 && heading < 360)) return Result<Unit>::fail(Err::VALIDATION, "Heading must be 0 to under 360 degrees");
    if (t->status != TRIP_RUNNING) return Result<Unit>::fail(Err::BAD_STATE, "Start the trip before sending positions");
    const Route &r = routes[(size_t)t->route_id];
    double along = 0;
    double off = geo_nearest_km(r.pts, r.cum_km, (size_t)r.n_stops, geo_point{lat, lng}, &along);
    if (off > 25.0) return Result<Unit>::fail(Err::VALIDATION, "That position is " + std::to_string((int)off) + " km from the route");
    double prev = t->km;
    t->km = std::max(prev, std::min(along, (double)r.km_nominal));  /* the bus never moves backwards on the tracker */
    t->sim_started = 1;
    t->sim_sec = std::max(0.0, (double)(clock.now() - t->depart_ms) / 1000.0);
    ds_ring_push(t->gps, clock.now(), speed);
    ds_ring_evict_before(t->gps, clock.now() - 10 * MS_MIN);
    GpsFix f{(int)gps_fixes.size() + 1, t->id, clock.now(), lat, lng, speed, heading, accuracy};
    gps_fixes.push(f);
    fire_alerts(*t, prev, t->km);
    flush_outbox();
    return okay("Position recorded");
}

Result<Unit> App::driver_delay(const User &u, int trip_id, const std::string &reason, int minutes, const std::string &note) {
    Trip *t = trip_by_id(trip_id);
    if (!t || !driver_can_access(u, *t)) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    static const char *REASONS[5] = {"TRAFFIC", "WEATHER", "BREAKDOWN", "ROADWORK", "OTHER"};
    bool known = false;
    for (const char *s : REASONS) known |= reason == s;
    if (!known) return Result<Unit>::fail(Err::VALIDATION, "Reason must be TRAFFIC, WEATHER, BREAKDOWN, ROADWORK or OTHER");
    if (minutes < 1 || minutes > 600) return Result<Unit>::fail(Err::VALIDATION, "Delay must be 1 to 600 minutes");
    if (note.size() > 240) return Result<Unit>::fail(Err::VALIDATION, "Note must be at most 240 characters");
    apply_delay(*t, reason, minutes, note.substr(0, 120), u.role == ROLE_ADMIN ? "admin" : "driver");
    return okay("Delay reported");
}

/* ---------- boarding check-in ---------- */

Booking *App::booking_by_pnr_any(const std::string &pnr) const {
    int *i = idx_pnr.get(upper_trim(pnr));
    return i ? bookings.at((size_t)*i) : nullptr;
}

std::string App::boarding_state(const Booking &b) const {
    if (b.status == BK_CANCELLED || b.status == BK_EXPIRED) return "CANCELLED";
    int full = (1 << b.n_pax) - 1;
    if ((b.boarded_mask & full) == 0) return "VALID";
    return (b.boarded_mask & full) == full ? "BOARDED" : "PART-BOARDED";
}

std::string App::qr_payload(const Booking &b) const {
    /* The text inside the QR changes once seats are boarded, so a used pass no longer shows its old code. */
    return "SR|" + std::string(b.pnr) + "|" + std::to_string(b.trip_id) + "|" + std::to_string(b.boarded_mask);
}

Result<int> App::driver_scan(const User &u, const std::string &code, bool *already) {
    *already = false;
    if (code.size() < 6 || code.size() > 80) return Result<int>::fail(Err::VALIDATION, "Enter the ticket code or the booking reference");
    std::string ref = code;
    size_t bar = code.find('|');
    if (bar != std::string::npos) {                                 /* "SR|PNR|trip|mask": the reference is field 2 */
        size_t bar2 = code.find('|', bar + 1);
        ref = code.substr(bar + 1, bar2 == std::string::npos ? std::string::npos : bar2 - bar - 1);
    }
    Booking *b = booking_by_pnr_any(ref);
    if (!b) return Result<int>::fail(Err::NOT_FOUND, "Ticket not found on this network.");
    Trip *t = trip_by_id(b->trip_id);
    if (!t || !driver_can_access(u, *t)) return Result<int>::fail(Err::NOT_FOUND, "This ticket is not for one of your trips.");
    if (b->status != BK_CONFIRMED) {
        std::string why = b->status == BK_PREBOOKED ? "Ticket is PREBOOKED: the balance is not paid yet." : std::string("Ticket is ") + (b->status == BK_COMPLETED ? "COMPLETED" : b->status == BK_CANCELLED ? "CANCELLED" : b->status == BK_EXPIRED ? "EXPIRED" : "not paid") + ".";
        return Result<int>::fail(Err::BAD_STATE, why);
    }
    int full = (1 << b->n_pax) - 1;
    *already = (b->boarded_mask & full) == full;
    if (!*already) {
        b->boarded_mask = full;
        b->boarded_ms = clock.now();
        std::string seats;
        for (int i = 0; i < b->n_pax; i++) seats += (i ? ", " : "") + std::string(b->pax[i].seat);
        notify(b->user_id, NK_JOURNEY, "Boarding confirmed", "Seat " + seats + " checked in at " + fmt_hm(clock.now()) + ". Your pass now shows as boarded.", "boarded:" + std::to_string(b->id));
        flush_outbox();
    }
    return Result<int>::success(b->id);
}

/* ---------- per-trip crew (vendor) ---------- */

Result<Unit> App::assign_trip_crew(int company_id, int trip_id, int driver_id, int conductor_id) {
    Trip *t = trip_by_id(trip_id);
    if (!t || buses[(size_t)t->bus_idx].company_id != company_id) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    if (t->status == TRIP_COMPLETED || t->status == TRIP_CANCELLED) return Result<Unit>::fail(Err::BAD_STATE, "That trip is already over");
    const int ids[2] = {driver_id, conductor_id};
    for (int k = 0; k < 2; k++) {
        int sid = ids[k];
        if (sid <= 0) continue;                                      /* -1 leave alone, 0 handled below */
        if ((size_t)sid > staff.size() || staff[(size_t)sid - 1].company_id != company_id) return Result<Unit>::fail(Err::NOT_FOUND, "Staff member not found");
        const Staff &s = staff[(size_t)sid - 1];
        if (s.role != (k == 0 ? STAFF_DRIVER : STAFF_CONDUCTOR)) return Result<Unit>::fail(Err::VALIDATION, std::string(s.name) + (k == 0 ? " is a conductor, not a driver" : " is a driver, not a conductor"));
        if (s.off_duty) return Result<Unit>::fail(Err::CONFLICT, std::string(s.name) + " is off duty and cannot be assigned");
        for (size_t i = 0; i < trips.size(); i++) {                  /* interval overlap against every other live trip */
            const Trip &o = *trips[i];
            if (o.id == t->id || o.status == TRIP_COMPLETED || o.status == TRIP_CANCELLED) continue;
            int other = k == 0 ? trip_driver(o) : trip_conductor(o);
            if (other == sid && o.depart_ms < t->arrive_ms && t->depart_ms < o.arrive_ms)
                return Result<Unit>::fail(Err::CONFLICT, std::string(s.name) + " is already on trip " + std::to_string(o.id) + " (" + fmt_hm(o.depart_ms) + " to " + fmt_hm(o.arrive_ms) + ") which overlaps this one");
        }
    }
    if (driver_id != -1) t->auto_driver = driver_id > 0 ? driver_id : -1;
    if (conductor_id != -1) t->auto_conductor = conductor_id > 0 ? conductor_id : -1;
    return okay("Crew updated");
}

Result<Unit> App::set_staff_off_duty(int company_id, int staff_id, bool off) {
    if (staff_id < 1 || (size_t)staff_id > staff.size() || staff[(size_t)staff_id - 1].company_id != company_id) return Result<Unit>::fail(Err::NOT_FOUND, "Staff member not found");
    Staff &s = staff[(size_t)staff_id - 1];
    if (off) {
        int today = date_key(clock.now());
        for (size_t i = 0; i < trips.size(); i++) {
            const Trip &t = *trips[i];
            if (t.date_key == today && t.status != TRIP_COMPLETED && t.status != TRIP_CANCELLED && (trip_driver(t) == staff_id || trip_conductor(t) == staff_id))
                return Result<Unit>::fail(Err::CONFLICT, std::string(s.name) + " is booked on a run today (trip " + std::to_string(t.id) + ") and cannot go off duty");
        }
    }
    s.off_duty = off ? 1 : 0;
    return okay(std::string(s.name) + (off ? " is now off duty" : " is back on duty"));
}

/* ---------- platform admin ---------- */

std::vector<CorridorRevenue> App::revenue_by_corridor() const {
    std::vector<CorridorRevenue> out;
    for (size_t i = 0; i < routes.size(); i += 2) out.push_back(CorridorRevenue{(int)i, 0, 0});   /* forward routes are the even ids */
    for (size_t i = 0; i < bookings.size(); i++) {
        const Booking &b = bookings[i];
        if (b.status != BK_CONFIRMED && b.status != BK_COMPLETED) continue;
        const Trip *t = trip_by_id(b.trip_id);
        if (!t) continue;
        CorridorRevenue &c = out[(size_t)t->route_id / 2];
        c.passes += b.n_pax;
        c.paise += b.paid - b.refunded;
    }
    return out;
}

Result<Unit> App::add_coupon(const std::string &raw, bool percent, int64_t value, int64_t cap, int64_t min_base) {
    std::string code = upper_trim(raw);
    if (code.size() < 3 || code.size() > 20) return Result<Unit>::fail(Err::VALIDATION, "Code must be 3 to 20 letters or digits");
    for (char c : code) if (!std::isalnum((unsigned char)c)) return Result<Unit>::fail(Err::VALIDATION, "Code may contain only letters and digits");
    if (value <= 0) return Result<Unit>::fail(Err::VALIDATION, "Discount must be more than zero");
    if (percent && value > 100) return Result<Unit>::fail(Err::VALIDATION, "A percentage cannot be more than 100");
    if (cap < 0 || min_base < 0) return Result<Unit>::fail(Err::VALIDATION, "Cap and minimum cannot be negative");
    if (idx_coupon.has(code)) return Result<Unit>::fail(Err::CONFLICT, "That coupon code already exists");
    Coupon c;
    std::memset(&c, 0, sizeof c);
    std::snprintf(c.code, sizeof c.code, "%s", code.c_str());
    c.is_percent = percent ? 1 : 0; c.value = value; c.max_discount = cap; c.min_base = min_base;
    c.per_user_limit = 1; c.max_uses = 1000; c.valid_days = 365; c.active = 1;
    std::snprintf(c.allowed, sizeof c.allowed, "ALL");
    coupons.push(c);
    idx_coupon.put(c.code, (int)coupons.size() - 1);
    return okay("Coupon " + code + " issued");
}

Result<Unit> App::set_coupon_active(const std::string &raw, bool active) {
    int *ci = idx_coupon.get(upper_trim(raw));
    if (!ci) return Result<Unit>::fail(Err::NOT_FOUND, "Coupon not found");
    coupons[(size_t)*ci].active = active ? 1 : 0;
    return okay(active ? "Coupon enabled" : "Coupon disabled");
}

int App::coupon_use_count(int coupon_idx) const {
    int n = 0;
    for (size_t i = 0; i < coupon_uses.size(); i++) n += coupon_uses[i].coupon_idx == coupon_idx;
    return n;
}

/* DEMO TRAFFIC: a fixed time-of-day pattern (not real traffic). Peak hours add a delay to trips on the road or leaving soon. */
int App::scan_traffic_delays(std::string *report) {
    Civil c = to_ist(clock.now());
    bool peak = (c.hour >= 8 && c.hour < 11) || (c.hour >= 17 && c.hour < 21);
    int changed = 0;
    report->clear();
    for (size_t i = 0; i < trips.size(); i++) {
        Trip &t = *trips[i];
        bool on_road = t.status == TRIP_RUNNING, soon = t.status == TRIP_SCHEDULED && t.depart_ms >= clock.now() && t.depart_ms - clock.now() <= 3 * MS_HOUR;
        if (!on_road && !soon) continue;
        int minutes = peak ? 8 + (t.id * 7) % 13 : 0;
        if (minutes <= t.delay_min) continue;
        apply_delay(t, "TRAFFIC", minutes, "DEMO TRAFFIC scan", "traffic-scan (DEMO)");
        *report += "  trip " + std::to_string(t.id) + " " + route_name(routes[(size_t)t.route_id]) + ": +" + std::to_string(minutes) + " min\n";
        changed++;
    }
    *report = std::string("DEMO TRAFFIC scan at ") + fmt_hm(clock.now()) + (peak ? " (peak hour)" : " (off-peak: no delays)") + "; trips updated: " + std::to_string(changed) + "\n" + *report;
    return changed;
}

/* ---------- share links ---------- */

static std::string make_token(App &app) {
    static const char ALPHABET[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-";
    std::string t;
    for (int i = 0; i < 12; i++) t += ALPHABET[app.next_random() % 64];
    return t;
}

std::string App::share_token_of(int booking_id) const {
    for (size_t i = shares.size(); i-- > 0;) if (shares[i].active && shares[i].booking_id == booking_id) return shares[i].token;
    return "";
}

Result<std::string> App::share_create(int user_id, int booking_id, bool rotate) {
    Booking *b = booking_by_id(booking_id);
    if (!b || b->user_id != user_id) return Result<std::string>::fail(Err::NOT_FOUND, "Booking not found");
    if (b->status == BK_CANCELLED || b->status == BK_EXPIRED) return Result<std::string>::fail(Err::BAD_STATE, "A cancelled or expired booking cannot be shared");
    std::string existing = share_token_of(booking_id);
    if (!existing.empty() && !rotate) return Result<std::string>::success(existing);
    for (size_t i = 0; i < shares.size(); i++) if (shares[i].active && shares[i].booking_id == booking_id) shares[i].active = 0;   /* rotating kills the old link */
    ShareLink s;
    std::memset(&s, 0, sizeof s);
    std::snprintf(s.token, sizeof s.token, "%s", make_token(*this).c_str());
    s.booking_id = booking_id; s.at_ms = clock.now(); s.active = 1;
    shares.push(s);
    idx_share.put(s.token, (int)shares.size() - 1);
    return Result<std::string>::success(s.token);
}

Result<Unit> App::share_revoke(int user_id, int booking_id) {
    Booking *b = booking_by_id(booking_id);
    if (!b || b->user_id != user_id) return Result<Unit>::fail(Err::NOT_FOUND, "Booking not found");
    for (size_t i = 0; i < shares.size(); i++) if (shares[i].active && shares[i].booking_id == booking_id) shares[i].active = 0;
    return okay("Sharing link revoked");
}

Booking *App::share_lookup(const std::string &token) const {
    int *i = idx_share.get(token);
    if (!i || !shares[(size_t)*i].active) return nullptr;
    Booking *b = booking_by_id(shares[(size_t)*i].booking_id);
    if (!b || b->status == BK_CANCELLED || b->status == BK_EXPIRED) return nullptr;
    return b;
}

}  // namespace sr

/* ===================== app/payment.cpp ===================== */
/*
 * PURPOSE: SIMULATED payment gateway: success / declined / timeout, with idempotency keys.
 * WHY THIS NAME: "payment" = taking money for a booking (here: pretend money, DEMO only).
 * CONNECTS TO: booking.cpp (status machine), seats.cpp (holds), idx_pay hash (row 2, idempotency).
 * COMPLEXITY: O(seats + holds).
 * NOTE: no card numbers are ever asked for or stored.
 */

namespace sr {

static constexpr int64_t PAY_EXTEND_MS = 5 * MS_MIN;

/* Holds are converted to sold seats on the first successful payment. */
static void convert_holds_to_sold(App &app, Booking &b) {
    Trip *t = app.trip_by_id(b.trip_id);
    const BusType &bt = app.types[app.buses[t->bus_idx].type_idx];
    app.release_user_holds(b.trip_id, b.user_id);
    for (int i = 0; i < b.n_pax; i++) {
        int idx = app.seat_index(bt, b.pax[i].seat);
        if (idx >= 0) t->booked.set((size_t)idx);
    }
}

/* Give the user at least 5 more minutes once payment starts (never shortens a hold). */
static void extend_holds(App &app, int trip_id, int user_id) {
    int64_t target = app.clock.now() + PAY_EXTEND_MS;
    for (size_t i = 0; i < app.holds.size(); i++) {
        Hold &h = app.holds[i];
        if (!h.active || h.trip_id != trip_id || h.user_id != user_id || h.expires_ms >= target) continue;
        h.expires_ms = target;
        app.events.update(((uint64_t)1 << 56) | (uint64_t)h.id, target);
    }
}

Result<Unit> App::pay_booking(int booking_id, int user_id, int kind, int outcome) {
    Booking *b = booking_by_id(booking_id);
    if (!b || b->user_id != user_id) return Result<Unit>::fail(Err::NOT_FOUND, "Booking not found");
    std::string key = "b" + std::to_string(b->id) + ":k" + std::to_string(kind) + ":a" + std::to_string(b->attempt_no);
    if (idx_pay.has(key)) return Result<Unit>::fail(Err::CONFLICT, "This payment was already processed (duplicate submit ignored)");
    Trip *t = trip_by_id(b->trip_id);
    if (!t) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    int64_t amount = 0;
    if (b->status == BK_PENDING_PAYMENT) {
        if ((b->mode == MODE_FULL && kind != PAYK_FULL) || (b->mode == MODE_DEPOSIT && kind != PAYK_DEPOSIT))
            return Result<Unit>::fail(Err::VALIDATION, "Wrong payment type for this booking");
        if (!sales_open(*t)) return Result<Unit>::fail(Err::BAD_STATE, "Sales for this trip are closed");
        if (active_holds(b->trip_id, b->user_id) < b->n_pax) return Result<Unit>::fail(Err::HOLD_EXPIRED, "Your seat hold expired. Please select seats again.");
        amount = kind == PAYK_FULL ? b->total : deposit_paise(b->total);
    } else if (b->status == BK_PREBOOKED && kind == PAYK_BALANCE) {
        if (clock.now() >= b->balance_due_ms) return Result<Unit>::fail(Err::BAD_STATE, "The balance deadline has passed");
        amount = b->total - b->paid;
    } else {
        return Result<Unit>::fail(Err::BAD_STATE, "This booking cannot accept a payment now");
    }
    if (b->status == BK_PENDING_PAYMENT) extend_holds(*this, b->trip_id, b->user_id);
    Payment p;
    std::memset(&p, 0, sizeof p);
    p.id = (int)payments.size() + 1; p.booking_id = b->id; p.kind = kind; p.amount = amount; p.outcome = outcome; p.at_ms = clock.now();
    std::snprintf(p.key, sizeof p.key, "%s", key.c_str());
    payments.push(p);
    idx_pay.put(key, p.id);
    if (outcome != OUT_SUCCESS) {
        b->attempt_no++;                                           /* a retry gets a fresh idempotency key */
        return Result<Unit>::fail(Err::PAYMENT_DECLINED, outcome == OUT_DECLINED ? "Payment declined by the demo gateway. You can retry." : "Payment timed out (demo). You can retry.");
    }
    bool first_payment = b->paid == 0;
    b->paid += amount;
    if (first_payment) {
        convert_holds_to_sold(*this, *b);
        if (b->coupon[0] && !b->coupon_recorded) {
            if (int *ci = idx_coupon.get(b->coupon)) coupon_uses.push(CouponUse{b->user_id, *ci, b->id});
            b->coupon_recorded = 1;
        }
    }
    record_revenue(buses[t->bus_idx].company_id, amount);
    int old_status = b->status;
    int next = (b->paid >= b->total) ? BK_CONFIRMED : BK_PREBOOKED;
    if (legal_transition(old_status, next)) b->status = next;
    b->pay_status = b->paid >= b->total ? PAY_PAID : PAY_PARTIAL;
    if (b->status == BK_PREBOOKED) schedule_booking_events(*b);
    if (b->status == BK_CONFIRMED) drop_booking_events(b->id);
    notify(b->user_id, NK_BOOKING, b->status == BK_CONFIRMED ? "Booking confirmed" : "Pre-booking confirmed",
           std::string(b->pnr) + " - " + route_name(routes[(size_t)t->route_id]) + ", " + fmt_datetime(t->depart_ms) + ". DEMO PAYMENT - no money was charged.",
           "bk:" + std::to_string(b->id) + ":" + std::to_string(kind));
    flush_outbox();
    return okay("Payment successful (DEMO PAYMENT - no money was charged)");
}

}  // namespace sr

/* ===================== app/search.cpp ===================== */
/*
 * PURPOSE: Bus search (filters, binary-search time windows, stable sorts, KMP name search) and the
 *          multi-leg journey planner (graph + Dijkstra + BFS).
 * WHY THIS NAME: "search" = finding buses and journeys.
 * CONNECTS TO: core/ds_sort (row 11), ds_search (rows 12, 18), ds_graph (row 9), seats.cpp (trips).
 * COMPLEXITY: search O(n log n) for n schedules on the route; planner O((V+E) log V).
 */

extern "C" {
}

namespace sr {

static int cmp_depart(const void *a, const void *b) {
    int64_t x = static_cast<const SearchRow *>(a)->depart_ms, y = static_cast<const SearchRow *>(b)->depart_ms;
    return (x > y) - (x < y);
}
static int cmp_depart_desc(const void *a, const void *b) { return cmp_depart(b, a); }
static int cmp_fare(const void *a, const void *b) {
    int64_t x = static_cast<const SearchRow *>(a)->fare_min, y = static_cast<const SearchRow *>(b)->fare_min;
    return (x > y) - (x < y);
}
static int cmp_duration(const void *a, const void *b) {
    return static_cast<const SearchRow *>(a)->duration_min - static_cast<const SearchRow *>(b)->duration_min;
}
static int cmp_seats_desc(const void *a, const void *b) {
    return static_cast<const SearchRow *>(b)->seats_left - static_cast<const SearchRow *>(a)->seats_left;
}

int64_t App::route_lowest_fare(int route_id) const {
    int64_t best = 0;
    const Route &r = routes[(size_t)route_id];
    for (size_t i = 0; i < schedules.size(); i++) {
        if (schedules[i].route_id != route_id || buses[(size_t)schedules[i].bus_idx].status == BUS_MAINTENANCE) continue;
        int64_t f = seat_fare_paise(r.km_nominal, types[(size_t)buses[(size_t)schedules[i].bus_idx].type_idx].rate_paise_per_km, false);
        if (best == 0 || f < best) best = f;
    }
    return best;
}

/* The dearest seat any bus on this route sells - the web page uses it as the max-fare slider ceiling. */
int64_t App::route_highest_fare(int route_id) const {
    int64_t best = 0;
    const Route &r = routes[(size_t)route_id];
    for (size_t i = 0; i < schedules.size(); i++) {
        if (schedules[i].route_id != route_id || buses[(size_t)schedules[i].bus_idx].status == BUS_MAINTENANCE) continue;
        const BusType &bt = types[(size_t)buses[(size_t)schedules[i].bus_idx].type_idx];
        int64_t f = seat_fare_paise(r.km_nominal, bt.rate_paise_per_km, bt.layout == LAYOUT_SLEEPER);   /* upper berth is the top price */
        if (f > best) best = f;
    }
    return best;
}

/* Keep rows i..j-1 of a depart-sorted array: removes everything outside via a compacting copy. */
static void keep_slice(Vec<SearchRow> &rows, size_t from, size_t to) {
    Vec<SearchRow> tmp;
    for (size_t i = from; i < to; i++) tmp.push(rows[i]);
    rows.clear();
    for (size_t i = 0; i < tmp.size(); i++) rows.push(tmp[i]);
}

void App::search(int from, int to, int date_key, const SearchFilters &f, SortKey sort, Vec<SearchRow> &out) {
    out.clear();
    int ri = find_route(from, to);
    if (ri < 0) return;
    const Route &r = routes[(size_t)ri];
    for (size_t si = 0; si < schedules.size(); si++) {
        const Schedule &s = schedules[si];
        if (s.route_id != ri || buses[(size_t)s.bus_idx].status == BUS_MAINTENANCE) continue;   /* maintenance hides the bus */
        Trip *t = get_or_create_trip((int)si, date_key);
        if (!t || t->status == TRIP_CANCELLED || clock.now() > t->depart_ms - 15 * MS_MIN) continue;
        const BusType &bt = types[(size_t)buses[(size_t)s.bus_idx].type_idx];
        SearchRow row;
        row.trip_id = t->id; row.bus_idx = s.bus_idx; row.route_id = ri; row.depart_ms = t->depart_ms; row.arrive_ms = t->arrive_ms;
        row.duration_min = r.duration_min;
        row.fare_min = seat_fare_paise(r.km_nominal, bt.rate_paise_per_km, false);
        row.fare_max = bt.layout == LAYOUT_SLEEPER ? seat_fare_paise(r.km_nominal, bt.rate_paise_per_km, true) : row.fare_min;
        row.seats_left = bt.capacity - (int)(t->booked.count() + t->held.count());
        out.push(row);
    }
    ds_merge_sort(out.data(), out.size(), sizeof(SearchRow), cmp_depart);          /* pre-sort by departure */
    if (f.dep_window >= 0 && out.size() > 0) {                                     /* binary search the window */
        int64_t midnight = ist_midnight(out[0].depart_ms);
        SearchRow lo_key, hi_key;
        std::memset(&lo_key, 0, sizeof lo_key); std::memset(&hi_key, 0, sizeof hi_key);
        lo_key.depart_ms = midnight + f.dep_window * 6 * MS_HOUR;
        hi_key.depart_ms = lo_key.depart_ms + 6 * MS_HOUR;
        size_t i = ds_lower_bound(out.data(), out.size(), sizeof(SearchRow), &lo_key, cmp_depart);
        size_t j = ds_lower_bound(out.data(), out.size(), sizeof(SearchRow), &hi_key, cmp_depart);
        keep_slice(out, i, j);
    }
    if (f.max_fare > 0 && out.size() > 0) {                                        /* fare range: sort by fare + upper_bound */
        ds_merge_sort(out.data(), out.size(), sizeof(SearchRow), cmp_fare);
        SearchRow key;
        std::memset(&key, 0, sizeof key);
        key.fare_min = f.max_fare;
        keep_slice(out, 0, ds_upper_bound(out.data(), out.size(), sizeof(SearchRow), &key, cmp_fare));
        ds_merge_sort(out.data(), out.size(), sizeof(SearchRow), cmp_depart);
    }
    Vec<SearchRow> kept;                                                           /* remaining linear filters */
    for (size_t i = 0; i < out.size(); i++) {
        const SearchRow &row = out[i];
        const Bus &bus = buses[(size_t)row.bus_idx];
        if (f.type_mask && !(f.type_mask & (1u << bus.type_idx))) continue;
        if (f.arr_window >= 0) {
            int64_t m = (row.arrive_ms - ist_midnight(row.arrive_ms)) / MS_HOUR;
            if (m / 6 != f.arr_window) continue;
        }
        if (f.need_seats && row.seats_left < 1) continue;
        if (f.dep_after >= 0 || f.dep_before >= 0) {                    /* time-of-day window: "after 7 am", "before 9pm" */
            int64_t mins = (row.depart_ms - ist_midnight(row.depart_ms)) / MS_MIN;
            if (f.dep_after >= 0 && mins < f.dep_after) continue;
            if (f.dep_before >= 0 && mins > f.dep_before) continue;
        }
        if (f.operator_substr[0] && !ds_kmp_contains_nocase(companies[(size_t)bus.company_id - 1].name, f.operator_substr)) continue;
        if (f.amenity[0] && !ds_kmp_contains_nocase(types[(size_t)bus.type_idx].amenities, f.amenity)) continue;
        kept.push(row);
    }
    out.clear();
    for (size_t i = 0; i < kept.size(); i++) out.push(kept[i]);
    int (*cmp)(const void *, const void *) = cmp_depart;
    if (sort == SORT_LATEST) cmp = cmp_depart_desc;
    else if (sort == SORT_CHEAPEST) cmp = cmp_fare;
    else if (sort == SORT_FASTEST) cmp = cmp_duration;
    else if (sort == SORT_MOST_SEATS) cmp = cmp_seats_desc;
    ds_merge_sort(out.data(), out.size(), sizeof(SearchRow), cmp);                 /* stable: ties keep departure order */
}

/* ---------- journey planner ---------- */

Result<Unit> App::plan_journey(int from, int to, PlanMode mode, Vec<PlanLeg> &legs, int64_t *total_min, int64_t *total_paise) {
    legs.clear();
    *total_min = *total_paise = 0;
    if (from < 0 || to < 0 || (size_t)from >= cities.size() || (size_t)to >= cities.size()) return Result<Unit>::fail(Err::VALIDATION, "Unknown city");
    if (from == to) return Result<Unit>::fail(Err::VALIDATION, "Choose two different cities");
    ds_graph_destroy(graph);                                   /* rebuild: bus status may have changed */
    graph = ds_graph_create(cities.size());
    for (size_t i = 0; i < routes.size(); i++) {
        int64_t fare = route_lowest_fare((int)i);
        if (fare == 0) continue;                                /* no bus on offer: not a usable edge */
        ds_graph_add_edge(graph, routes[i].from_city, routes[i].to_city, routes[i].duration_min, fare, (int)i);
    }
    size_t n = cities.size();
    int64_t dist[64]; int pv[64], pe[64], legs_cnt[64], path[64];
    if (n > 64) return Result<Unit>::fail(Err::VALIDATION, "Too many cities for planner buffers");
    if (mode == PLAN_FEWEST) ds_graph_bfs_fewest_legs(graph, from, legs_cnt, pv, pe);
    else ds_graph_dijkstra(graph, from, mode == PLAN_CHEAPEST, mode == PLAN_CHEAPEST ? 0 : 60, dist, pv, pe);
    size_t len = ds_graph_path(pv, from, to, path, 64);
    if (len < 2) return Result<Unit>::fail(Err::NOT_FOUND, "No route");
    for (size_t i = 1; i < len; i++) {
        int rid = pe[path[i]];
        PlanLeg leg{rid, path[i - 1], path[i], routes[(size_t)rid].duration_min, route_lowest_fare(rid)};
        legs.push(leg);
        *total_min += leg.minutes;
        *total_paise += leg.paise;
    }
    *total_min += 60 * (int64_t)(legs.size() - 1);              /* 60-minute layover between legs */
    return okay();
}

}  // namespace sr

/* ===================== app/seats.cpp ===================== */
/*
 * PURPOSE: Trips, seat layouts, seat bitsets, 10-minute holds (heap-driven expiry), waitlist queue.
 * WHY THIS NAME: "seats" = everything about which seat is free, held, or sold.
 * CONNECTS TO: core/ds_bitset (rows 3), ds_heap (row 4), ds_queue (row 5), ds_hash (trip index).
 * COMPLEXITY: seat test/set O(1); seats left O(n/64); hold expiry O(log n) per event.
 */

namespace sr {

static constexpr int64_t HOLD_MS = 10 * MS_MIN;
static constexpr int64_t SALES_CLOSE_MS = 15 * MS_MIN;
enum EventKind { EV_HOLD_EXPIRY = 1, EV_BALANCE_DEADLINE = 2, EV_REMINDER = 3 };

static uint64_t ev_id(int kind, uint64_t payload) { return ((uint64_t)kind << 56) | payload; }

/* ---------- layouts ---------- */

static int columns_of(const BusType &bt) { return bt.layout == LAYOUT_2P2 ? 4 : 3; }

void App::seat_label(const BusType &bt, int i, char out[6]) const {
    if (bt.layout == LAYOUT_SLEEPER) {
        std::snprintf(out, 6, "%c%d", i < 15 ? 'L' : 'U', (i % 15) + 1);
        return;
    }
    int cols = columns_of(bt);
    int row = (i / cols) % 100 + 1;                          /* rows are small; clamp keeps the label short */
    std::snprintf(out, 6, "%d%c", row, "ABCD"[i % cols]);
}

int App::seat_index(const BusType &bt, const char *label) const {
    char buf[6];
    for (int i = 0; i < bt.capacity; i++) {
        seat_label(bt, i, buf);
        if (std::strcmp(buf, label) == 0) return i;
    }
    return -1;
}

int App::seat_row(const BusType &bt, int i) const {
    if (bt.layout == LAYOUT_SLEEPER) return (i / 15) * 5 + (i % 15) / 3;   /* decks never share a row */
    return i / columns_of(bt);
}

/* ---------- trips ---------- */

Trip *App::trip_by_id(int id) const {
    return (id >= 1 && (size_t)id <= trips.size()) ? *trips.at((size_t)id - 1) : nullptr;
}

size_t App::seat_count(const Trip &t) const { return (size_t)types[buses[t.bus_idx].type_idx].capacity; }

Trip *App::get_or_create_trip(int schedule_idx, int date_key) {
    if (schedule_idx < 0 || (size_t)schedule_idx >= schedules.size()) return nullptr;
    std::string key = std::to_string(schedule_idx) + ":" + std::to_string(date_key);
    if (int *id = idx_trip.get(key)) return trip_by_id(*id);
    const Schedule &s = schedules[(size_t)schedule_idx];
    const Route &r = routes[(size_t)s.route_id];
    int cap = types[buses[s.bus_idx].type_idx].capacity;
    Trip *t = new Trip(cap);
    t->id = (int)trips.size() + 1;
    t->schedule_idx = schedule_idx; t->route_id = s.route_id; t->bus_idx = s.bus_idx; t->date_key = date_key;
    t->depart_ms = from_ist(date_key / 10000, (date_key / 100) % 100, date_key % 100, 0, 0) + (int64_t)s.depart_min_of_day * MS_MIN;
    t->arrive_ms = t->depart_ms + (int64_t)r.duration_min * MS_MIN;
    if (!trips.push(t)) { delete t; return nullptr; }
    idx_trip.put(key, t->id);
    return t;
}

bool App::sales_open(const Trip &t) const {
    return t.status == TRIP_SCHEDULED && clock.now() <= t.depart_ms - SALES_CLOSE_MS;
}

int64_t App::trip_hours_left(const Trip &t) const { return (t.depart_ms - clock.now()) / MS_HOUR; }

/* ---------- seat map ---------- */

std::vector<SeatCell> App::seat_map(const Trip &t, int viewer) const {
    std::vector<SeatCell> cells;
    const BusType &bt = types[buses[t.bus_idx].type_idx];
    for (int i = 0; i < bt.capacity; i++) {
        SeatCell c;
        std::memset(&c, 0, sizeof c);
        seat_label(bt, i, c.label);
        c.index = i;
        if (t.booked.test((size_t)i)) c.state = 1;
        else if (t.held.test((size_t)i)) {
            c.state = 2;
            for (size_t h = holds.size(); h-- > 0;)
                if (holds[h].active && holds[h].trip_id == t.id && holds[h].seat == i) { c.state = holds[h].user_id == viewer ? 3 : 2; break; }
        }
        cells.push_back(c);
    }
    return cells;
}

long App::find_adjacent(const Trip &t, int n) const {
    const BusType &bt = types[buses[t.bus_idx].type_idx];
    if (n < 1) return -1;
    Bits unavailable(MAX_SEATS);                               /* booked OR held */
    for (int i = 0; i < bt.capacity; i++) if (t.booked.test((size_t)i) || t.held.test((size_t)i)) unavailable.set((size_t)i);
    int row_start = 0;
    for (int i = 1; i <= bt.capacity; i++) {
        if (i == bt.capacity || seat_row(bt, i) != seat_row(bt, row_start)) {   /* row [row_start, i) ends */
            long at = unavailable.find_clear_run((size_t)row_start, (size_t)i, (size_t)n);
            if (at >= 0) return at;
            row_start = i;
        }
    }
    return -1;
}

/* ---------- holds ---------- */

int App::active_holds(int trip_id, int user_id) const {
    int c = 0;
    for (size_t i = 0; i < holds.size(); i++) if (holds[i].active && holds[i].trip_id == trip_id && holds[i].user_id == user_id) c++;
    return c;
}

int64_t App::hold_expiry(int trip_id, int user_id) const {
    int64_t best = 0;
    for (size_t i = 0; i < holds.size(); i++)
        if (holds[i].active && holds[i].trip_id == trip_id && holds[i].user_id == user_id && (best == 0 || holds[i].expires_ms < best)) best = holds[i].expires_ms;
    return best;
}

void App::release_user_holds(int trip_id, int user_id) {
    Trip *t = trip_by_id(trip_id);
    for (size_t i = 0; i < holds.size(); i++) {
        Hold &h = holds[i];
        if (!h.active || h.trip_id != trip_id || h.user_id != user_id) continue;
        h.active = 0;
        if (t) t->held.clear((size_t)h.seat);
        events.remove(ev_id(EV_HOLD_EXPIRY, (uint64_t)h.id));
    }
}

static Hold make_hold(int id, int trip, int seat, int user, int64_t expires) { return Hold{id, trip, seat, user, expires, 1}; }

Result<Unit> App::hold_seats(int user_id, int trip_id, const char *const *labels, int n) {
    Trip *t = trip_by_id(trip_id);
    if (!user_by_id(user_id)) return Result<Unit>::fail(Err::UNAUTHENTICATED, "Please log in first");
    if (!t) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    if (!sales_open(*t)) return Result<Unit>::fail(Err::BAD_STATE, "Sales for this trip are closed");
    if (n < 1 || n > MAX_PAX) return Result<Unit>::fail(Err::VALIDATION, "Choose 1 to 6 seats");
    const BusType &bt = types[buses[t->bus_idx].type_idx];
    int idx[MAX_PAX];
    for (int i = 0; i < n; i++) {
        idx[i] = seat_index(bt, labels[i]);
        if (idx[i] < 0) return Result<Unit>::fail(Err::VALIDATION, std::string("No such seat: ") + labels[i]);
        for (int j = 0; j < i; j++) if (idx[j] == idx[i]) return Result<Unit>::fail(Err::VALIDATION, "Duplicate seat in selection");
    }
    release_user_holds(trip_id, user_id);                      /* re-holding replaces earlier holds */
    for (int i = 0; i < n; i++)
        if (t->booked.test((size_t)idx[i]) || t->held.test((size_t)idx[i]))
            return Result<Unit>::fail(Err::SEAT_TAKEN, std::string("Seat ") + labels[i] + " was just taken. Pick another.");
    int64_t expires = clock.now() + HOLD_MS;
    for (int i = 0; i < n; i++) {
        int hid = (int)holds.size() + 1;
        holds.push(make_hold(hid, trip_id, idx[i], user_id, expires));
        t->held.set((size_t)idx[i]);
        events.push(expires, ev_id(EV_HOLD_EXPIRY, (uint64_t)hid));
    }
    return okay("Seats held for 10 minutes");
}

/* ---------- waitlist ---------- */

Result<Unit> App::join_waitlist(int user_id, int trip_id, int seats) {
    Trip *t = trip_by_id(trip_id);
    if (!t) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    size_t cap = seat_count(*t);
    if (t->booked.count() + t->held.count() < cap) return Result<Unit>::fail(Err::BAD_STATE, "Seats are still available; no waitlist needed");
    if (seats < 1 || seats > MAX_PAX) return Result<Unit>::fail(Err::VALIDATION, "Waitlist for 1 to 6 seats");
    t->waitlist.push(WaitEntry{user_id, seats});
    return okay("You are on the waitlist (position " + std::to_string(t->waitlist.size()) + ")");
}

/* When seats become free, offer them to the head of the waitlist with a 10-minute claim window. */
void App::on_seats_freed(int trip_id) {
    Trip *t = trip_by_id(trip_id);
    if (!t) return;
    const BusType &bt = types[buses[t->bus_idx].type_idx];
    WaitEntry w;
    for (;;) {
        int free_seat[MAX_SEATS], nfree = 0;
        for (int i = 0; i < bt.capacity; i++) if (!t->booked.test((size_t)i) && !t->held.test((size_t)i)) free_seat[nfree++] = i;
        if (nfree == 0 || !t->waitlist.pop(&w)) return;
        int take = w.seats_wanted < nfree ? w.seats_wanted : nfree;
        int64_t expires = clock.now() + HOLD_MS;
        for (int i = 0; i < take; i++) {
            int hid = (int)holds.size() + 1;
            holds.push(make_hold(hid, trip_id, free_seat[i], w.user_id, expires));
            t->held.set((size_t)free_seat[i]);
            events.push(expires, ev_id(EV_HOLD_EXPIRY, (uint64_t)hid));
        }
        notify(w.user_id, NK_BOOKING, "Waitlist: seats available",
               std::to_string(take) + " seat(s) held for you for 10 minutes on " + route_name(routes[(size_t)t->route_id]) +
               " (" + fmt_datetime(t->depart_ms) + ")", "");
    }
}

/* ---------- time-driven events ---------- */

void App::expire_booking_if_unheld(int trip_id, int user_id) {
    if (active_holds(trip_id, user_id) > 0) return;
    for (size_t i = 0; i < bookings.size(); i++) {
        Booking &b = bookings[i];
        if (b.trip_id == trip_id && b.user_id == user_id && b.status == BK_PENDING_PAYMENT) {
            b.status = BK_EXPIRED;
            notify(user_id, NK_BOOKING, "Seat hold expired", "Booking " + std::string(b.pnr) + " expired because payment was not completed in time.", "");
        }
    }
}

void App::expire_hold(int hold_id) {
    Hold &h = holds[(size_t)hold_id - 1];
    if (!h.active) return;
    h.active = 0;
    Trip *t = trip_by_id(h.trip_id);
    if (t) t->held.clear((size_t)h.seat);
    notify(h.user_id, NK_REMINDERS, "Hold expired", "Your 10-minute seat hold ended.", "hold:" + std::to_string(hold_id));
    expire_booking_if_unheld(h.trip_id, h.user_id);
    on_seats_freed(h.trip_id);
}

void App::process_events() {
    int64_t prio;
    uint64_t id;
    while (events.peek(&prio, &id) && prio <= clock.now()) {
        events.pop(&prio, &id);
        int kind = (int)(id >> 56);
        uint64_t payload = id & 0x00FFFFFFFFFFFFFFULL;
        if (kind == EV_HOLD_EXPIRY) expire_hold((int)payload);
        else if (kind == EV_BALANCE_DEADLINE) {
            Booking *b = booking_by_id((int)payload);
            if (b && b->status == BK_PREBOOKED) {
                finalize_end_state(*b, BK_EXPIRED);
                notify(b->user_id, NK_BOOKING, "Pre-booking expired", "Balance for " + std::string(b->pnr) + " was not paid by the deadline. Seats released; refund per policy applied.", "");
            }
        } else if (kind == EV_REMINDER) {
            Booking *b = booking_by_id((int)(payload >> 4));
            static const char *WHEN[3] = {"7 days", "24 hours", "6 hours"};
            int k = (int)(payload & 15);
            if (b && b->status == BK_PREBOOKED && k < 3)
                notify(b->user_id, NK_REMINDERS, "Balance reminder",
                       "Pay the balance of " + fmt_rs(b->total - b->paid) + " for " + b->pnr + " (due " + fmt_datetime(b->balance_due_ms) + ", " + WHEN[k] + " reminder).",
                       "rem:" + std::to_string(b->id) + ":" + std::to_string(k));
        }
    }
    flush_outbox();
}

void App::advance_clock(int64_t ms) {
    clock.advance(ms);
    process_events();
}

/* The web server calls this once per loop tick with the virtual time that corresponds to real time
   right now (the virtual time at server start + steady-clock seconds since - a laptop waking from
   sleep does not jump the clock forward). Without it the server's virtual time froze at startup,
   hold-expiry events never fired, and a seat held by a visitor who closed the tab stayed blocked
   forever. Like advance_clock it only moves forward, so the "+1 hour" demo buttons still stick. */
void App::sync_wall_clock(int64_t wall_ms) {
    if (wall_ms > clock.now()) advance_clock(wall_ms - clock.now());
}

}  // namespace sr

/* ===================== app/storage.cpp ===================== */
/*
 * PURPOSE: Save/load of runtime state (users, bookings, holds, trips, payments, notifications, fleet, meta)
 *          as versioned, checksummed text files, written atomically (temp file, then rename).
 * WHY THIS NAME: "storage" = persistence layer (replaces the original SQLite database).
 * CONNECTS TO: app.hpp, core/ds_hash (FNV-1a style checksum is hand-written here), ds_bitset (hex).
 * COMPLEXITY: O(total records).
 * FORMAT: first line "#SMARTROUTE v1 <section> <count> <fnv1a64 hex of body>"; body = one record per line,
 *         fields separated by '|' (escaped: \p = '|', \\ = '\', \n = newline).
 */

namespace sr {

/* ---------- low-level helpers ---------- */

static uint64_t fnv1a(const std::string &s) {
    uint64_t h = 1469598103934665603ULL;
    for (unsigned char c : s) { h ^= c; h *= 1099511628211ULL; }
    return h;
}

static std::string esc(const std::string &s) {
    std::string o;
    for (char c : s) {
        if (c == '\\') o += "\\\\";
        else if (c == '|') o += "\\p";
        else if (c == '\n') o += "\\n";
        else if (c == '\r') o += ' ';
        else o += c;
    }
    return o;
}

static std::string unesc(const std::string &s) {
    std::string o;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            char n = s[++i];
            o += n == 'p' ? '|' : (n == 'n' ? '\n' : n);
        } else o += s[i];
    }
    return o;
}

/* Builds one record line. */
class Line {
    std::string s_;
public:
    Line &add(const std::string &v) { if (!s_.empty() || started_) s_ += '|'; s_ += esc(v); started_ = true; return *this; }
    Line &num(long long v) { return add(std::to_string(v)); }
    Line &dbl(double v) { char b[40]; std::snprintf(b, sizeof b, "%.9g", v); return add(b); }
    const std::string &str() const { return s_; }
private:
    bool started_ = false;
};

/* Parses one record line. */
class Fields {
    std::vector<std::string> f_;
public:
    explicit Fields(const std::string &line) { for (const std::string &p : split_fields(line, '|')) f_.push_back(unesc(p)); }
    size_t size() const { return f_.size(); }
    std::string s(size_t i) const { return i < f_.size() ? f_[i] : ""; }
    long long n(size_t i) const { return i < f_.size() ? std::strtoll(f_[i].c_str(), nullptr, 10) : 0; }
    double d(size_t i) const { return i < f_.size() ? std::strtod(f_[i].c_str(), nullptr) : 0.0; }
};

static bool read_file(const std::string &path, std::string *out) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return false;
    std::ostringstream ss;
    ss << in.rdbuf();
    *out = ss.str();
    return true;
}

/* Verify header + checksum. Returns the record lines, or false when the file is damaged. */
static bool parse_section(const std::string &text, const std::string &name, std::vector<std::string> *lines, std::string *why) {
    size_t nl = text.find('\n');
    if (nl == std::string::npos) { *why = "empty file"; return false; }
    char section[32] = {0}, hex[32] = {0};
    unsigned long count = 0;
    if (std::sscanf(text.substr(0, nl).c_str(), "#SMARTROUTE v1 %31s %lu %31s", section, &count, hex) != 3) { *why = "bad header or unsupported version"; return false; }
    if (name != section) { *why = "wrong section"; return false; }
    std::string body = text.substr(nl + 1);
    char want[32];
    std::snprintf(want, sizeof want, "%016llx", (unsigned long long)fnv1a(body));
    if (std::strcmp(want, hex) != 0) { *why = "checksum mismatch (file damaged)"; return false; }
    std::istringstream in(body);
    std::string l;
    while (std::getline(in, l)) if (!l.empty()) lines->push_back(l);
    if (lines->size() != count) { *why = "record count mismatch"; return false; }
    return true;
}

static bool write_section(const std::string &dir, const std::string &name, const std::vector<std::string> &lines, std::string *err) {
    std::string body;
    for (const std::string &l : lines) body += l + "\n";
    char head[96];
    std::snprintf(head, sizeof head, "#SMARTROUTE v1 %s %zu %016llx\n", name.c_str(), lines.size(), (unsigned long long)fnv1a(body));
    std::string path = dir + "/" + name + ".sav", tmp = path + ".tmp", bak = path + ".bak";
    {
        std::ofstream out(tmp, std::ios::binary | std::ios::trunc);
        if (!out) { *err = "cannot write " + tmp; return false; }
        out << head << body;
        out.flush();
        if (!out) { *err = "write failed for " + tmp; return false; }
    }
    std::remove(bak.c_str());
    std::rename(path.c_str(), bak.c_str());                 /* keep the previous good copy */
    std::remove(path.c_str());                              /* Windows cannot rename over an existing file */
    if (std::rename(tmp.c_str(), path.c_str()) != 0) { *err = "cannot replace " + path; return false; }
    return true;
}

/* Load a section; fall back to .bak when the main file is damaged. Returns 0 missing, 1 loaded, -1 unusable. */
static int load_section(const std::string &dir, const std::string &name, std::vector<std::string> *lines, std::string *messages) {
    std::string path = dir + "/" + name + ".sav", text, why;
    bool have = read_file(path, &text);
    if (!have) return 0;
    lines->clear();
    if (parse_section(text, name, lines, &why)) return 1;
    *messages += name + ".sav: " + why + ". ";
    lines->clear();
    if (read_file(path + ".bak", &text) && parse_section(text, name, lines, &why)) { *messages += "Recovered from " + name + ".sav.bak. "; return 1; }
    *messages += "No usable backup; " + name + " starts empty. ";
    return -1;
}

static std::string clean_name(const char *s) {
    std::string o = s;
    for (char &c : o) if (c == '~' || c == ';' || c == '|' || c == '\\' || c == '\n') c = ' ';
    return o;
}

/* ---------- save ---------- */

bool App::save_all(std::string *error) {
    if (save_dir.empty()) return true;
    std::vector<std::string> L;
    L.push_back(Line().num(clock.now()).num((long long)rng_state).num(base_day).num((long long)session_user).str());
    for (int c = 1; c <= (int)companies.size(); c++)
        for (int d = 0; d < 120; d++) {
            int64_t v = ds_fenwick_range(revenue_co[c], (size_t)d, (size_t)d);
            if (v != 0) L.push_back(Line().add("rev").num(c).num(d).num(v).str());
        }
    if (!write_section(save_dir, "meta", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < users.size(); i++) {
        const User &u = users[i];
        L.push_back(Line().num(u.id).add(u.name).add(u.email).add(u.phone).num(u.role).num(u.company_id).add(u.salt).add(u.hash).num(u.prefs).num(u.failed_logins).num(u.staff_id).str());
    }
    if (!write_section(save_dir, "users", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < buses.size(); i++) L.push_back(Line().add(buses[i].reg).num(buses[i].status).num(buses[i].driver_id).num(buses[i].conductor_id).str());
    if (!write_section(save_dir, "fleet", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < trips.size(); i++) {
        Trip &t = *trips[i];
        std::string wl;
        for (size_t k = t.waitlist.size(); k > 0; k--) {         /* rotate the queue once to read it */
            WaitEntry w;
            t.waitlist.pop(&w);
            wl += std::to_string(w.user_id) + ":" + std::to_string(w.seats_wanted) + ",";
            t.waitlist.push(w);
        }
        L.push_back(Line().num(t.id).num(t.schedule_idx).num(t.date_key).num(t.status).num(t.delay_min).add(t.delay_reason).add(t.delay_note)
                        .dbl(t.km).dbl(t.jam_left_km).num(t.break_left_sec).num(t.breaks_done).dbl(t.sim_sec).num(t.sim_started)
                        .num(t.jam_alerted_level).num(t.auto_driver).num(t.auto_conductor).add(t.booked.hex()).add(t.held.hex()).add(wl).str());
    }
    if (!write_section(save_dir, "trips", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < holds.size(); i++) {
        const Hold &h = holds[i];
        L.push_back(Line().num(h.id).num(h.trip_id).num(h.seat).num(h.user_id).num(h.expires_ms).num(h.active).str());
    }
    if (!write_section(save_dir, "holds", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < bookings.size(); i++) {
        const Booking &b = bookings[i];
        std::string px;
        for (int k = 0; k < b.n_pax; k++)
            px += std::string(b.pax[k].seat) + "~" + clean_name(b.pax[k].name) + "~" + std::to_string(b.pax[k].age) + "~" + b.pax[k].gender + "~" + std::to_string(b.pax[k].price) + ";";
        L.push_back(Line().num(b.id).add(b.pnr).num(b.user_id).num(b.trip_id).num(b.status).num(b.pay_status).num(b.mode)
                        .num(b.base).num(b.discount).num(b.tax).num(b.insurance).num(b.total).num(b.paid).num(b.refunded)
                        .add(b.coupon).num(b.boarding_stop).num(b.dropping_stop).add(px).add(b.contact).num(b.balance_due_ms)
                        .num(b.created_ms).num(b.demo_payment).num(b.attempt_no).num(b.coupon_recorded).num(b.boarded_mask).num(b.boarded_ms).str());
    }
    if (!write_section(save_dir, "bookings", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < payments.size(); i++) {
        const Payment &p = payments[i];
        L.push_back(Line().num(p.id).num(p.booking_id).num(p.kind).num(p.amount).num(p.outcome).add(p.key).num(p.at_ms).str());
    }
    if (!write_section(save_dir, "payments", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < notes.size(); i++) {
        const Notification &n = notes[i];
        L.push_back(Line().num(n.id).num(n.user_id).num(n.kind).add(n.title).add(n.body).add(n.dedupe).num(n.created_ms).num(n.read).str());
    }
    if (!write_section(save_dir, "notes", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < coupons.size(); i++) {
        const Coupon &c = coupons[i];
        L.push_back(Line().add(c.code).num(c.is_percent).num(c.value).num(c.max_discount).num(c.min_base).num(c.per_user_limit).num(c.max_uses).add(c.allowed).num(c.valid_days).num(c.active).str());
    }
    if (!write_section(save_dir, "coupons", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < shares.size(); i++) L.push_back(Line().add(shares[i].token).num(shares[i].booking_id).num(shares[i].at_ms).num(shares[i].active).str());
    if (!write_section(save_dir, "shares", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < delay_log.size(); i++) { const DelayLog &d = delay_log[i]; L.push_back(Line().num(d.id).num(d.trip_id).num(d.at_ms).add(d.cause).num(d.minutes).add(d.source).str()); }
    if (!write_section(save_dir, "delays", L, error)) return false;
    L.clear();
    for (size_t i = gps_fixes.size() > 300 ? gps_fixes.size() - 300 : 0; i < gps_fixes.size(); i++) {   /* keep the latest 300 fixes */
        const GpsFix &g = gps_fixes[i];
        L.push_back(Line().num(g.id).num(g.trip_id).num(g.at_ms).dbl(g.lat).dbl(g.lng).dbl(g.speed).dbl(g.heading).dbl(g.accuracy).str());
    }
    if (!write_section(save_dir, "gps", L, error)) return false;
    L.clear();
    for (size_t i = 0; i < staff.size(); i++) if (staff[i].off_duty) L.push_back(Line().num(staff[i].id).num(staff[i].off_duty).str());
    return write_section(save_dir, "crew", L, error);
}

/* ---------- load ---------- */

static void copy_to(char *dst, size_t cap, const std::string &s) { std::snprintf(dst, cap, "%s", s.c_str()); }

bool App::load_saved(std::string *messages) {
    if (save_dir.empty()) return false;
    std::vector<std::string> L;
    bool any = false;
    if (load_section(save_dir, "meta", &L, messages) == 1 && !L.empty()) {
        any = true;
        Fields f(L[0]);
        clock.set(f.n(0)); rng_state = (uint64_t)f.n(1); base_day = f.n(2);   /* sessions are never restored */
        for (size_t i = 1; i < L.size(); i++) {
            Fields r(L[i]);
            if (r.s(0) == "rev" && r.n(1) >= 1 && r.n(1) < 32) ds_fenwick_add(revenue_co[r.n(1)], (size_t)r.n(2), r.n(3));
        }
    }
    if (load_section(save_dir, "users", &L, messages) == 1) {
        any = true;
        std::vector<User> seeds;                                   /* accounts loaded from users_seed.csv at startup */
        for (size_t i = 0; i < users.size(); i++) seeds.push_back(users[i]);
        users.clear(); idx_email.clear();
        for (const std::string &l : L) {
            Fields f(l);
            User u; std::memset(&u, 0, sizeof u);
            u.id = (int)f.n(0); copy_to(u.name, sizeof u.name, f.s(1)); copy_to(u.email, sizeof u.email, f.s(2)); copy_to(u.phone, sizeof u.phone, f.s(3));
            u.role = (int)f.n(4); u.company_id = (int)f.n(5); copy_to(u.salt, sizeof u.salt, f.s(6)); copy_to(u.hash, sizeof u.hash, f.s(7));
            u.prefs = (int)f.n(8); u.failed_logins = (int)f.n(9); u.staff_id = (int)f.n(10);
            users.push(u);
            idx_email.put(u.email, (int)users.size() - 1);
        }
        for (const User &seed : seeds) {                           /* an older save file lacks newer demo accounts (driver, admin, ...): add them */
            if (int *at = idx_email.get(seed.email)) {
                User &have = users[(size_t)*at];
                if (have.staff_id == 0 && seed.staff_id > 0) have.staff_id = seed.staff_id;
                continue;
            }
            User add = seed;
            add.id = (int)users.size() + 1;
            users.push(add);
            idx_email.put(add.email, (int)users.size() - 1);
        }
    }
    if (load_section(save_dir, "fleet", &L, messages) == 1) {
        any = true;
        for (size_t i = 0; i < staff.size(); i++) staff[i].bus_idx = -1;
        for (const std::string &l : L) {
            Fields f(l);
            int bi = find_bus(f.s(0).c_str());
            if (bi < 0) continue;
            Bus &b = buses[(size_t)bi];
            b.status = (int)f.n(1); b.driver_id = (int)f.n(2); b.conductor_id = (int)f.n(3);
        }
        for (size_t i = 0; i < buses.size(); i++) {
            if (buses[i].driver_id > 0) staff[(size_t)buses[i].driver_id - 1].bus_idx = (int)i;
            if (buses[i].conductor_id > 0) staff[(size_t)buses[i].conductor_id - 1].bus_idx = (int)i;
        }
    }
    int trip_state = load_section(save_dir, "trips", &L, messages);
    if (trip_state == 1) {
        any = true;
        free_all_trips(); idx_trip.clear();
        for (const std::string &l : L) {
            Fields f(l);
            Trip *t = get_or_create_trip((int)f.n(1), (int)f.n(2));
            if (!t || t->id != (int)f.n(0)) { *messages += "trips.sav: id sequence broken. "; break; }
            t->status = (int)f.n(3); t->delay_min = (int)f.n(4); copy_to(t->delay_reason, sizeof t->delay_reason, f.s(5)); copy_to(t->delay_note, sizeof t->delay_note, f.s(6));
            t->km = f.d(7); t->jam_left_km = f.d(8); t->break_left_sec = (int)f.n(9); t->breaks_done = (int)f.n(10); t->sim_sec = f.d(11);
            t->sim_started = (int)f.n(12); t->jam_alerted_level = (int)f.n(13); t->auto_driver = (int)f.n(14); t->auto_conductor = (int)f.n(15);
            t->booked.from_hex(f.s(16).c_str()); t->held.from_hex(f.s(17).c_str());
            for (const std::string &e : split_fields(f.s(18), ',')) {
                int u = 0, n = 0;
                if (std::sscanf(e.c_str(), "%d:%d", &u, &n) == 2) t->waitlist.push(WaitEntry{u, n});
            }
        }
    }
    if (load_section(save_dir, "holds", &L, messages) == 1 && trip_state != -1) {
        any = true;
        holds.clear();
        for (const std::string &l : L) {
            Fields f(l);
            holds.push(Hold{(int)f.n(0), (int)f.n(1), (int)f.n(2), (int)f.n(3), f.n(4), (int)f.n(5)});
        }
    }
    if (load_section(save_dir, "coupons", &L, messages) == 1 && !L.empty()) {
        any = true;
        coupons.clear(); idx_coupon.clear();
        for (const std::string &l : L) {
            Fields f(l);
            Coupon c; std::memset(&c, 0, sizeof c);
            copy_to(c.code, sizeof c.code, f.s(0)); c.is_percent = (int)f.n(1); c.value = f.n(2); c.max_discount = f.n(3); c.min_base = f.n(4);
            c.per_user_limit = (int)f.n(5); c.max_uses = (int)f.n(6); copy_to(c.allowed, sizeof c.allowed, f.s(7)); c.valid_days = (int)f.n(8); c.active = (int)f.n(9);
            coupons.push(c);
            idx_coupon.put(c.code, (int)coupons.size() - 1);
        }
    }
    if (load_section(save_dir, "bookings", &L, messages) == 1) {
        any = true;
        bookings.clear(); idx_pnr.clear(); coupon_uses.clear();
        for (const std::string &l : L) {
            Fields f(l);
            Booking b; std::memset(&b, 0, sizeof b);
            b.id = (int)f.n(0); copy_to(b.pnr, sizeof b.pnr, f.s(1)); b.user_id = (int)f.n(2); b.trip_id = (int)f.n(3);
            b.status = (int)f.n(4); b.pay_status = (int)f.n(5); b.mode = (int)f.n(6);
            b.base = f.n(7); b.discount = f.n(8); b.tax = f.n(9); b.insurance = f.n(10); b.total = f.n(11); b.paid = f.n(12); b.refunded = f.n(13);
            copy_to(b.coupon, sizeof b.coupon, f.s(14)); b.boarding_stop = (int)f.n(15); b.dropping_stop = (int)f.n(16);
            for (const std::string &p : split_fields(f.s(17), ';')) {
                auto q = split_fields(p, '~');
                if (q.size() != 5 || b.n_pax >= MAX_PAX) continue;
                Passenger &x = b.pax[b.n_pax++];
                copy_to(x.seat, sizeof x.seat, q[0]); copy_to(x.name, sizeof x.name, q[1]);
                x.age = std::atoi(q[2].c_str()); x.gender = q[3].empty() ? 'O' : q[3][0]; x.price = std::strtoll(q[4].c_str(), nullptr, 10);
            }
            copy_to(b.contact, sizeof b.contact, f.s(18)); b.balance_due_ms = f.n(19); b.created_ms = f.n(20);
            b.demo_payment = (int)f.n(21); b.attempt_no = (int)f.n(22); b.coupon_recorded = (int)f.n(23); b.boarded_mask = (int)f.n(24); b.boarded_ms = f.n(25);
            if (b.trip_id < 1 || (size_t)b.trip_id > trips.size()) { *messages += "Dropped booking " + std::string(b.pnr) + " (its trip is missing). "; continue; }
            bookings.push(b);
            idx_pnr.put(b.pnr, (int)bookings.size() - 1);
            if (b.coupon_recorded) if (int *ci = idx_coupon.get(b.coupon)) coupon_uses.push(CouponUse{b.user_id, *ci, b.id});
        }
    }
    if (load_section(save_dir, "payments", &L, messages) == 1) {
        any = true;
        payments.clear(); idx_pay.clear();
        for (const std::string &l : L) {
            Fields f(l);
            Payment p; std::memset(&p, 0, sizeof p);
            p.id = (int)f.n(0); p.booking_id = (int)f.n(1); p.kind = (int)f.n(2); p.amount = f.n(3); p.outcome = (int)f.n(4);
            copy_to(p.key, sizeof p.key, f.s(5)); p.at_ms = f.n(6);
            payments.push(p);
            idx_pay.put(p.key, p.id);
        }
    }
    if (load_section(save_dir, "notes", &L, messages) == 1) {
        any = true;
        notes.clear();
        for (const std::string &l : L) {
            Fields f(l);
            Notification n; std::memset(&n, 0, sizeof n);
            n.id = (int)f.n(0); n.user_id = (int)f.n(1); n.kind = (int)f.n(2);
            copy_to(n.title, sizeof n.title, f.s(3)); copy_to(n.body, sizeof n.body, f.s(4)); copy_to(n.dedupe, sizeof n.dedupe, f.s(5));
            n.created_ms = f.n(6); n.read = (int)f.n(7);
            notes.push(n);
            if (n.dedupe[0]) alert_seen.put(n.dedupe, 1);        /* alerts already sent stay suppressed after restart */
        }
    }
    if (load_section(save_dir, "shares", &L, messages) == 1) {
        any = true;
        shares.clear(); idx_share.clear();
        for (const std::string &l : L) {
            Fields f(l);
            ShareLink sl; std::memset(&sl, 0, sizeof sl);
            copy_to(sl.token, sizeof sl.token, f.s(0)); sl.booking_id = (int)f.n(1); sl.at_ms = f.n(2); sl.active = (int)f.n(3);
            shares.push(sl);
            idx_share.put(sl.token, (int)shares.size() - 1);
        }
    }
    if (load_section(save_dir, "delays", &L, messages) == 1) {
        any = true;
        delay_log.clear();
        for (const std::string &l : L) {
            Fields f(l);
            DelayLog d; std::memset(&d, 0, sizeof d);
            d.id = (int)f.n(0); d.trip_id = (int)f.n(1); d.at_ms = f.n(2); copy_to(d.cause, sizeof d.cause, f.s(3)); d.minutes = (int)f.n(4); copy_to(d.source, sizeof d.source, f.s(5));
            delay_log.push(d);
        }
    }
    if (load_section(save_dir, "gps", &L, messages) == 1) {
        any = true;
        gps_fixes.clear();
        for (const std::string &l : L) { Fields f(l); gps_fixes.push(GpsFix{(int)f.n(0), (int)f.n(1), f.n(2), f.d(3), f.d(4), f.d(5), f.d(6), f.d(7)}); }
    }
    if (load_section(save_dir, "crew", &L, messages) == 1) {
        any = true;
        for (const std::string &l : L) { Fields f(l); long long id = f.n(0); if (id >= 1 && (size_t)id <= staff.size()) staff[(size_t)id - 1].off_duty = (int)f.n(1); }
    }
    /* Rebuild the timer heap from saved state: active holds, pre-booking deadlines and reminders. */
    for (size_t i = 0; i < holds.size(); i++)
        if (holds[i].active) events.push(holds[i].expires_ms, ((uint64_t)1 << 56) | (uint64_t)holds[i].id);
    for (size_t i = 0; i < bookings.size(); i++)
        if (bookings[i].status == BK_PREBOOKED) schedule_booking_events(bookings[i]);
    return any;
}

}  // namespace sr

/* ===================== app/ticket.cpp ===================== */
/*
 * PURPOSE: Ticket rendering.
 * WHY THIS NAME: implements ticket.hpp.
 * CONNECTS TO: asciimap.hpp
 * COMPLEXITY: see header.
 */

namespace sr {

const char *booking_status_name(int s) {
    static const char *N[6] = {"PENDING_PAYMENT", "PREBOOKED", "CONFIRMED", "CANCELLED", "EXPIRED", "COMPLETED"};
    return (s >= 0 && s < 6) ? N[s] : "?";
}
const char *pay_status_name(int s) {
    static const char *N[5] = {"UNPAID", "PARTIAL", "PAID", "PARTIALLY_REFUNDED", "REFUNDED"};
    return (s >= 0 && s < 5) ? N[s] : "?";
}
const char *bus_status_name(int s) {
    static const char *N[3] = {"AVAILABLE", "ON_TRIP", "MAINTENANCE"};
    return (s >= 0 && s < 3) ? N[s] : "?";
}
const char *staff_status_name(int s) {
    static const char *N[4] = {"OFF_DUTY", "ON_TRIP", "ASSIGNED", "AVAILABLE"};
    return (s >= 0 && s < 4) ? N[s] : "?";
}

std::string cancellation_table() {
    return "Cancellation (demo policy, refund of the fare; insurance is non-refundable):\n"
           "  72 h or more before departure : 100%\n"
           "  24 h to 72 h                  :  80%\n"
           "  6 h to 24 h                   :  50%\n"
           "  under 6 h                     :   0%\n";
}

bool driver_phones_visible(const App &app, const Booking &b) {
    const Trip *t = app.trip_by_id(b.trip_id);
    if (!t || (b.status != BK_PREBOOKED && b.status != BK_CONFIRMED)) return false;
    int64_t now = app.clock.now();
    return now >= t->depart_ms - 24 * MS_HOUR && now <= t->arrive_ms + 2 * MS_HOUR;
}

static void box_line(std::string &out, const std::string &text) {
    std::string t = text.size() > 74 ? text.substr(0, 74) : text;
    out += "| " + t + std::string(74 - t.size(), ' ') + " |\n";
}

std::string render_ticket(const App &app, const Booking &b, bool color) {
    const Trip *t = app.trip_by_id(b.trip_id);
    const Route &r = app.routes[(size_t)t->route_id];
    const Bus &bus = app.buses[(size_t)t->bus_idx];
    const BusType &bt = app.types[(size_t)bus.type_idx];
    std::string border = "+" + std::string(76, '=') + "+\n", out = border;
    box_line(out, "SMARTROUTE  |  E-TICKET (DEMO - sample data, no real travel)");
    out += border;
    box_line(out, std::string("PNR: ") + b.pnr + "    Status: " + booking_status_name(b.status) + "    Payment: " + pay_status_name(b.pay_status));
    box_line(out, "Route: " + app.route_name(r) + "    Date: " + fmt_date(t->depart_ms));
    box_line(out, "Departs: " + fmt_hm(t->depart_ms) + " IST    Arrives: " + fmt_hm_plus(t->arrive_ms, t->depart_ms) + " IST    Duration: " + fmt_duration(r.duration_min));
    box_line(out, "Boarding: " + std::string(r.stops[b.boarding_stop].name) + " @ " + fmt_hm(app.planned_stop_time(*t, b.boarding_stop)));
    box_line(out, "Dropping: " + std::string(r.stops[b.dropping_stop].name) + " @ " + fmt_hm_plus(app.planned_stop_time(*t, b.dropping_stop), t->depart_ms));
    box_line(out, "Operator: " + app.bus_label(t->bus_idx) + "  (" + bt.label + ")");
    for (int i = 0; i < b.n_pax; i++)
        box_line(out, "  Seat " + std::string(b.pax[i].seat) + "  " + b.pax[i].name + ", " + std::to_string(b.pax[i].age) + " " + b.pax[i].gender + "  " + fmt_rs(b.pax[i].price));
    box_line(out, "Total " + fmt_rs(b.total) + "   Paid " + fmt_rs(b.paid) + "   Balance " + fmt_rs(b.status == BK_PREBOOKED ? b.total - b.paid : 0) +
                      (b.refunded ? "   Refunded " + fmt_rs(b.refunded) : ""));
    if (b.status == BK_PREBOOKED) box_line(out, "Balance due by: " + fmt_datetime(b.balance_due_ms) + "  (unpaid => booking expires)");
    if (b.demo_payment) box_line(out, "DEMO PAYMENT - no money was charged");
    std::string breaks;
    for (int i = 0; i < r.n_stops; i++)
        if (r.stops[i].type == ST_BREAK) breaks += std::string(r.stops[i].name) + " (" + std::to_string(r.stops[i].break_min) + " min), ";
    box_line(out, "Break stations: " + (breaks.empty() ? std::string("none") : breaks.substr(0, breaks.size() - 2)));
    if (driver_phones_visible(app, b)) {
        const Staff *d = bus.driver_id > 0 ? app.staff.at((size_t)bus.driver_id - 1) : nullptr;
        const Staff *c = bus.conductor_id > 0 ? app.staff.at((size_t)bus.conductor_id - 1) : nullptr;
        if (d) box_line(out, std::string("Driver: ") + d->name + "  " + d->phone + "  (DEMO number)");
        if (c) box_line(out, std::string("Conductor: ") + c->name + "  " + c->phone + "  (DEMO number)");
    } else box_line(out, "Driver/conductor numbers appear 24 h before departure for paid bookings.");
    box_line(out, "Verified by PNR lookup - a code alone is not proof of payment");
    out += border;
    out += cancellation_table();
    out += render_route_map(app, r, -1, color);
    return out;
}

std::string share_summary(const App &app, const Booking &b) {
    const Trip *t = app.trip_by_id(b.trip_id);
    const Route &r = app.routes[(size_t)t->route_id];
    return "SmartRoute trip (demo): " + app.route_name(r) + ", " + fmt_datetime(t->depart_ms) + ", arrives " + fmt_hm_plus(t->arrive_ms, t->depart_ms) +
           " IST, " + app.bus_label(t->bus_idx) + ". Seats: " + std::to_string(b.n_pax) + ". (No personal data included.)";
}

}  // namespace sr

/* ===================== app/tracking.cpp ===================== */
/*
 * PURPOSE: Live-tracking simulator (DEMO), ETA, crossing-based alerts and bus position.
 * WHY THIS NAME: "tracking" = following a bus along its route.
 * CONNECTS TO: core/geo (position, row 13), ds_ring (speed average, row 14), ds_lru (memo, row 8),
 *              ds_list (stops), ds_sort (event order), notifications.cpp (dedupe + bell).
 * COMPLEXITY: advance O(steps + stops); position O(log s); alerts O(events x bookings).
 */

extern "C" {
}

namespace sr {

static constexpr double JAM_SPEED_KMH = 15.0;
static constexpr double JAM_LENGTH_KM = 5.0;
static constexpr double EPS = 1e-9;

/* ---------- position (LRU-memoised) ---------- */

struct CachedPoint { double lat, lng, pad1, pad2; };

geo_point App::bus_position(const Route &r, double km) const {
    char key[64];
    std::snprintf(key, sizeof key, "p%d:%ld", r.id, std::lround(km * 10.0));
    if (void *hit = ds_lru_get(cache, key)) {
        const CachedPoint *c = static_cast<const CachedPoint *>(hit);
        return geo_point{c->lat, c->lng};
    }
    geo_point p{};
    size_t seg = 0;
    geo_point_at_km(r.pts, r.cum_km, (size_t)r.n_stops, km, &p, &seg);   /* binary search + interpolation */
    CachedPoint c{p.lat, p.lng, 0, 0};
    ds_lru_put(cache, key, &c);
    return p;
}

/* ---------- simulator core ---------- */

/* Next break stop not yet started, or nullptr. */
static const Stop *next_break(const Route &r, int breaks_done) {
    int seen = 0;
    for (int i = 0; i < r.n_stops; i++)
        if (r.stops[i].type == ST_BREAK && seen++ == breaks_done) return &r.stops[i];
    return nullptr;
}

static void record_speed(Trip &t, double kmh) {
    int64_t at = t.depart_ms + (int64_t)(t.sim_sec * 1000.0);
    ds_ring_push(t.gps, at, kmh);
    ds_ring_evict_before(t.gps, at - 10 * MS_MIN);               /* keep only the last 10 virtual minutes */
}

/* Move the bus. Either a time budget (seconds) or a distance budget (km) is finite. */
static void sim_core(Trip &t, const Route &r, double seconds, double km_budget, bool stop_at_break) {
    const double total = r.km_nominal, cruise = r.avg_kmh;
    while (t.km < total - EPS && seconds > EPS && km_budget > EPS) {
        if (t.break_left_sec > 0) {
            if (stop_at_break) return;
            double use = std::min(seconds, (double)t.break_left_sec);
            t.break_left_sec -= (int)std::ceil(use - 1e-9);
            if (t.break_left_sec < 0) t.break_left_sec = 0;
            seconds -= use; t.sim_sec += use;
            record_speed(t, 0.0);
            continue;
        }
        bool jam = t.jam_left_km > EPS;
        double speed = jam ? JAM_SPEED_KMH : cruise;
        const Stop *brk = next_break(r, t.breaks_done);
        double step = std::min(speed * seconds / 3600.0, km_budget);
        step = std::min(step, total - t.km);
        if (brk) step = std::min(step, brk->km - t.km);
        if (jam) step = std::min(step, t.jam_left_km);
        if (step < 0) step = 0;
        t.km += step;
        if (jam) { t.jam_left_km -= step; if (t.jam_left_km < EPS) t.jam_left_km = 0; }
        double used = step / speed * 3600.0;
        seconds -= used; km_budget -= step; t.sim_sec += used;
        record_speed(t, speed);
        if (brk && std::fabs(t.km - brk->km) < 1e-6) {           /* arrived at a break stop: wait there */
            t.km = brk->km;
            t.break_left_sec = brk->break_min * 60;
            t.breaks_done++;
        }
        if (step <= EPS && t.break_left_sec == 0) break;          /* safety: no progress possible */
    }
}

static void bookings_of_trip_done(App &app, Trip &t) {
    for (size_t i = 0; i < app.bookings.size(); i++) {
        Booking &b = app.bookings[i];
        if (b.trip_id == t.id && app.legal_transition(b.status, BK_COMPLETED)) b.status = BK_COMPLETED;
    }
}

void App::sim_advance(Trip &t, double seconds) {
    const Route &r = routes[(size_t)t.route_id];
    double prev = t.km;
    if (!t.sim_started && seconds > 0) {                          /* first movement starts the trip */
        t.sim_started = 1;
        if (t.status == TRIP_SCHEDULED) { t.status = TRIP_RUNNING; buses[(size_t)t.bus_idx].status = BUS_ON_TRIP; }
    }
    sim_core(t, r, seconds, 1e18, false);
    fire_alerts(t, prev, t.km);
    maybe_alert_traffic(t);
    if (t.km >= r.km_nominal - EPS) {
        t.km = r.km_nominal;
        if (t.status == TRIP_RUNNING) {
            t.status = TRIP_COMPLETED;
            buses[(size_t)t.bus_idx].status = BUS_AVAILABLE;
            bookings_of_trip_done(*this, t);
        }
    }
    flush_outbox();
}

void App::sim_advance_km(Trip &t, double km) {
    const Route &r = routes[(size_t)t.route_id];
    double prev = t.km;
    if (!t.sim_started) {
        t.sim_started = 1;
        if (t.status == TRIP_SCHEDULED) { t.status = TRIP_RUNNING; buses[(size_t)t.bus_idx].status = BUS_ON_TRIP; }
    }
    if (t.break_left_sec > 0) {                                   /* leaving a break: skip the remaining wait */
        t.sim_sec += t.break_left_sec;
        t.break_left_sec = 0;
    }
    sim_core(t, r, 1e18, km, true);                               /* stops at the next break if one is crossed */
    fire_alerts(t, prev, t.km);
    maybe_alert_traffic(t);
    if (t.km >= r.km_nominal - EPS && t.status == TRIP_RUNNING) {
        t.status = TRIP_COMPLETED;
        buses[(size_t)t.bus_idx].status = BUS_AVAILABLE;
        bookings_of_trip_done(*this, t);
    }
    flush_outbox();
}

void App::sim_jam(Trip &t) {
    t.jam_left_km = JAM_LENGTH_KM;
    maybe_alert_traffic(t);
    flush_outbox();
}

void App::sim_reset(Trip &t) {
    t.km = 0; t.jam_left_km = 0; t.break_left_sec = 0; t.breaks_done = 0; t.sim_sec = 0; t.sim_started = 0; t.jam_alerted_level = 0;
    if (t.status == TRIP_RUNNING) { t.status = TRIP_SCHEDULED; buses[(size_t)t.bus_idx].status = BUS_AVAILABLE; }
    ds_ring_evict_before(t.gps, INT64_MAX);
}

/* ---------- ETA ---------- */

TrackInfo App::track_info(const Trip &t) const {
    const Route &r = routes[(size_t)t.route_id];
    TrackInfo info;
    info.sim_now = t.depart_ms + (int64_t)(t.sim_sec * 1000.0);
    info.sched_arrive = t.arrive_ms;
    double left = std::max(0.0, r.km_nominal - t.km);
    info.km_left = left;
    info.progress_pct = 100.0 * t.km / r.km_nominal;
    double jam_km = std::min(t.jam_left_km, left);
    double minutes = jam_km / JAM_SPEED_KMH * 60.0 + (left - jam_km) / r.avg_kmh * 60.0;   /* drive time */
    int seen = 0;
    for (int i = 0; i < r.n_stops; i++)
        if (r.stops[i].type == ST_BREAK && seen++ >= t.breaks_done) minutes += r.stops[i].break_min;   /* breaks still ahead */
    minutes += t.break_left_sec / 60.0;                                                     /* break in progress */
    if (!t.sim_started && t.jam_left_km <= EPS && t.breaks_done == 0 && t.break_left_sec == 0 && t.delay_min == 0)
        info.est_arrive = info.sched_arrive;   /* nothing has happened yet: the plan exactly, no rounding drift */
    else
        info.est_arrive = info.sim_now + (int64_t)std::llround(minutes * 60000.0);
    int observed = (int)std::llround((double)(info.est_arrive - info.sched_arrive) / 60000.0);
    info.delay_min = std::max(observed, t.delay_min);          /* reported delay never stacks on top of observed */
    info.est_arrive = std::max(info.est_arrive, info.sched_arrive + (int64_t)t.delay_min * MS_MIN);
    info.on_break = t.break_left_sec > 0;
    info.break_min_left = (t.break_left_sec + 59) / 60;
    info.speed_kmh = info.on_break ? 0.0 : (t.jam_left_km > EPS ? JAM_SPEED_KMH : (double)r.avg_kmh);
    if (ds_ring_count(t.gps) > 0 && !info.on_break) info.speed_kmh = ds_ring_mean(t.gps);
    if (t.km >= r.km_nominal - EPS) info.speed_kmh = 0.0;
    return info;
}

/* Per-stop arrival estimate (spec 6.7). For a stop at distance s while the bus is at k:
   jam part of the remaining distance at JAM_SPEED_KMH + the rest at the route average + the
   minutes of meal halts the bus has not waited at yet (that sit before s) + the rest of a break
   in progress. A reported delay is a floor on top of the planned time. Before departure nothing
   has happened, so the answer is the plan exactly (history fix 11: no seconds-level drift).
   At the destination this reproduces track_info's headline ETA. */
int64_t App::eta_at_stop(const Trip &t, int stop_idx) const {
    const Route &r = routes[(size_t)t.route_id];
    if (stop_idx < 0 || stop_idx >= r.n_stops) return 0;
    int64_t planned = planned_stop_time(t, stop_idx);
    if (!t.sim_started && t.jam_left_km <= EPS && t.breaks_done == 0 && t.break_left_sec == 0 && t.delay_min == 0)
        return planned;                       /* nothing has happened yet: the plan exactly */
    /* a pre-departure jam or reported delay still flows through the normal estimate below */
    double s_km = r.stops[(size_t)stop_idx].km;
    double left = std::max(0.0, s_km - t.km);
    if (left <= EPS) return std::max(planned + (int64_t)t.delay_min * MS_MIN, t.depart_ms + (int64_t)(t.sim_sec * 1000.0));
    double jam = std::min(t.jam_left_km, left);
    double minutes = jam / JAM_SPEED_KMH * 60.0 + (left - jam) / r.avg_kmh * 60.0;
    int seen = 0;
    for (int i = 0; i < r.n_stops; i++)
        if (r.stops[i].type == ST_BREAK && r.stops[i].km < s_km - 1e-9 && seen++ >= t.breaks_done) minutes += r.stops[i].break_min;
    minutes += t.break_left_sec / 60.0;                          /* the break in progress lies before every future stop */
    int64_t eta = t.depart_ms + (int64_t)(t.sim_sec * 1000.0) + (int64_t)std::llround(minutes * 60000.0);
    return std::max(eta, planned + (int64_t)t.delay_min * MS_MIN);
}

/* ---------- crossing-based alerts ---------- */

/* Planned clock time at which the bus is at `km` (drive time + breaks already completed before it). */
static int64_t time_at_km(const Route &r, const Trip &t, double km) {
    int64_t drive_ms = (int64_t)std::llround(r.drive_min * (km / r.km_nominal) * 60000.0);
    int break_before = 0;
    for (int i = 0; i < r.n_stops; i++)
        if (r.stops[i].type == ST_BREAK && r.stops[i].km < km - 1e-9) break_before += r.stops[i].break_min;
    return t.depart_ms + drive_ms + (int64_t)break_before * MS_MIN;
}

enum AlertKind { A_DEPARTED, A_BOARD_AHEAD, A_BOARD_REACHED, A_BREAK_AHEAD, A_BREAK_STOPPED, A_BREAK_RESUMED,
                 A_TOLL_AHEAD, A_TOLL_CROSSED, A_DROP_AHEAD, A_DROP_REACHED, A_COMPLETED };

struct AlertEvent { double km; int seq; int kind; int stop; };

static int cmp_alert(const void *a, const void *b) {
    const AlertEvent *x = static_cast<const AlertEvent *>(a), *y = static_cast<const AlertEvent *>(b);
    if (x->km < y->km) return -1;
    if (x->km > y->km) return 1;
    return x->seq - y->seq;
}

static bool own_stop_event(int kind) {
    return kind == A_BOARD_AHEAD || kind == A_BOARD_REACHED || kind == A_DROP_AHEAD || kind == A_DROP_REACHED;
}

struct AlertTime {                                      /* stamps alerts with the simulated trip time while in scope */
    App &app;
    AlertTime(App &a, const Trip &t) : app(a) { a.alert_time_ms = t.sim_started ? t.depart_ms + (int64_t)(t.sim_sec * 1000.0) : 0; }
    ~AlertTime() { app.alert_time_ms = 0; }
};

void App::fire_alerts(Trip &t, double prev, double cur) {
    if (cur <= prev) return;
    const Route &r = routes[(size_t)t.route_id];
    Vec<AlertEvent> ev;
    int seq = 0;
    ev.push(AlertEvent{0.5, seq++, A_DEPARTED, 0});
    for (int i = 0; i < r.n_stops; i++) {
        const Stop &s = r.stops[i];
        if (s.type == ST_BOARDING) {
            ev.push(AlertEvent{std::max(0.01, s.km - 5.0), seq++, A_BOARD_AHEAD, i});
            ev.push(AlertEvent{s.km, seq++, A_BOARD_REACHED, i});
        } else if (s.type == ST_BREAK) {
            ev.push(AlertEvent{s.km - 20.0, seq++, A_BREAK_AHEAD, i});
            ev.push(AlertEvent{s.km, seq++, A_BREAK_STOPPED, i});
            ev.push(AlertEvent{s.km + 0.001, seq++, A_BREAK_RESUMED, i});
        } else if (s.type == ST_TOLL) {
            ev.push(AlertEvent{s.km - r.avg_kmh * 25.0 / 60.0, seq++, A_TOLL_AHEAD, i});   /* about 25 minutes before */
            ev.push(AlertEvent{s.km, seq++, A_TOLL_CROSSED, i});
        } else if (s.type == ST_DROPPING) {
            ev.push(AlertEvent{s.km - 20.0, seq++, A_DROP_AHEAD, i});
            ev.push(AlertEvent{s.km - 0.5, seq++, A_DROP_REACHED, i});
        }
    }
    ev.push(AlertEvent{(double)r.km_nominal, seq++, A_COMPLETED, 0});
    ds_merge_sort(ev.data(), ev.size(), sizeof(AlertEvent), cmp_alert);          /* events fire in km order */
    for (size_t e = 0; e < ev.size(); e++) {
        const AlertEvent &a = ev[e];
        if (!(prev < a.km && a.km <= cur + EPS)) continue;                         /* crossing test */
        alert_time_ms = t.sim_started ? time_at_km(r, t, std::max(0.0, std::min(a.km, (double)r.km_nominal))) : 0;   /* stamp with the time the bus reached this km */
        const Stop &s = r.stops[a.stop];
        std::string place = s.name, title, body;
        int kind = NK_JOURNEY;
        switch (a.kind) {
            case A_DEPARTED: title = "Bus departed"; body = "Your bus left " + std::string(cities[(size_t)r.from_city].name) + "."; break;
            case A_BOARD_AHEAD: title = "Boarding point ahead"; body = "Approaching " + place + "."; break;
            case A_BOARD_REACHED: title = "Boarding point reached"; body = "The bus is at " + place + "."; break;
            case A_BREAK_AHEAD: kind = NK_BREAKS; title = "Break ahead"; body = "Break stop " + place + " in about 20 km (" + std::to_string(s.break_min) + " min)."; break;
            case A_BREAK_STOPPED: kind = NK_BREAKS; title = "Bus stopped"; body = "Bus stopped at " + place + " - about " + std::to_string(s.break_min) + " min, expected departure " + fmt_hm(planned_stop_time(t, a.stop) + (int64_t)s.break_min * MS_MIN) + "."; break;
            case A_BREAK_RESUMED: kind = NK_BREAKS; title = "Bus resumed"; body = "The bus left " + place + "."; break;
            case A_TOLL_AHEAD: kind = NK_TOLLS; title = "Toll ahead"; body = place + " in about 25 minutes (the bus does not stop)."; break;
            case A_TOLL_CROSSED: kind = NK_TOLLS; title = "Toll crossed"; body = "Crossed " + place + "."; break;
            case A_DROP_AHEAD: kind = NK_DROPOFF; title = "Your drop-off is ahead"; body = place + " in about 20 km."; break;
            case A_DROP_REACHED: kind = NK_DROPOFF; title = "Drop-off reached"; body = "Arriving at " + place + "."; break;
            default: title = "Trip completed"; body = "The trip has reached " + std::string(cities[(size_t)r.to_city].name) + "."; break;
        }
        for (size_t bi = 0; bi < bookings.size(); bi++) {
            const Booking &b = bookings[bi];
            if (b.trip_id != t.id || (b.status != BK_PREBOOKED && b.status != BK_CONFIRMED)) continue;
            if (own_stop_event(a.kind)) {
                int own = (a.kind == A_BOARD_AHEAD || a.kind == A_BOARD_REACHED) ? b.boarding_stop : b.dropping_stop;
                if (own != a.stop) continue;                                       /* only the passenger's own stop */
            }
            std::string key = "u" + std::to_string(b.user_id) + ":t" + std::to_string(t.id) + ":s" + std::to_string(a.stop) + ":e" + std::to_string(a.kind);
            notify(b.user_id, kind, "[Demo] " + title, body, key);
        }
    }
    alert_time_ms = 0;
}

/* Traffic delay alert: first time the remaining jam delay reaches 10 min, then every further 10. */
void App::maybe_alert_traffic(Trip &t) {
    AlertTime stamp(*this, t);
    const Route &r = routes[(size_t)t.route_id];
    if (t.jam_left_km <= EPS) { t.jam_alerted_level = 0; return; }
    double extra = t.jam_left_km * (60.0 / JAM_SPEED_KMH - 60.0 / r.avg_kmh);
    int level = (int)(extra / 10.0);
    if (level <= t.jam_alerted_level) return;
    t.jam_alerted_level = level;
    for (size_t bi = 0; bi < bookings.size(); bi++) {
        const Booking &b = bookings[bi];
        if (b.trip_id != t.id || (b.status != BK_PREBOOKED && b.status != BK_CONFIRMED)) continue;
        notify(b.user_id, NK_TRAFFIC, "[Demo] Traffic delay (DEMO TRAFFIC)", "Heavy traffic ahead: about " + std::to_string((int)extra) + " extra minutes.",
               "u" + std::to_string(b.user_id) + ":t" + std::to_string(t.id) + ":jam:" + std::to_string(level));
    }
}

Result<Unit> App::report_delay(int company_id, int trip_id, const std::string &reason, int minutes, const std::string &note) {
    Trip *t = trip_by_id(trip_id);
    if (!t || buses[(size_t)t->bus_idx].company_id != company_id) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");   /* other vendors' trips look absent */
    static const char *REASONS[5] = {"TRAFFIC", "WEATHER", "BREAKDOWN", "ROADWORK", "OTHER"};
    bool known = false;
    for (const char *s : REASONS) known |= reason == s;
    if (!known) return Result<Unit>::fail(Err::VALIDATION, "Reason must be TRAFFIC, WEATHER, BREAKDOWN, ROADWORK or OTHER");
    if (minutes < 1 || minutes > 600) return Result<Unit>::fail(Err::VALIDATION, "Delay must be 1 to 600 minutes");
    if (note.size() > 120) return Result<Unit>::fail(Err::VALIDATION, "Note must be at most 120 characters");
    apply_delay(*t, reason, minutes, note, "vendor");
    return okay("Delay reported");
}

/* Records a delay (replacing any earlier one), tells the booked passengers, and writes the delay log. */
void App::apply_delay(Trip &t, const std::string &reason, int minutes, const std::string &note, const char *source) {
    t.delay_min = minutes;                                      /* a new report replaces the old value; it never stacks */
    std::snprintf(t.delay_reason, sizeof t.delay_reason, "%s", reason.c_str());
    std::snprintf(t.delay_note, sizeof t.delay_note, "%s", note.c_str());
    DelayLog d;
    std::memset(&d, 0, sizeof d);
    d.id = (int)delay_log.size() + 1; d.trip_id = t.id; d.at_ms = clock.now(); d.minutes = minutes;
    std::snprintf(d.cause, sizeof d.cause, "%s", reason.c_str());
    std::snprintf(d.source, sizeof d.source, "%s", source);
    delay_log.push(d);
    TrackInfo ti = track_info(t);
    std::string body = reason + ": about " + std::to_string(minutes) + " min. New ETA " + fmt_hm_plus(ti.est_arrive, t.depart_ms) + ".";
    if (!note.empty()) body += " Driver note: " + note + ".";      /* spec 6.6: the note must reach the passenger */
    for (size_t bi = 0; bi < bookings.size(); bi++) {
        const Booking &b = bookings[bi];
        if (b.trip_id != t.id || (b.status != BK_PREBOOKED && b.status != BK_CONFIRMED)) continue;
        /* a changed note (or minutes) is a new message: the dedupe key carries both */
        notify(b.user_id, NK_TRAFFIC, "Delay reported", body,
               "u" + std::to_string(b.user_id) + ":t" + std::to_string(t.id) + ":delay:" + std::to_string(minutes) + ":" + note);
    }
    flush_outbox();
}

}  // namespace sr

/* ===================== app/vendor.cpp ===================== */
/*
 * PURPOSE: Vendor portal rules: staff status, assignment, bus status with undo, trip start/complete,
 *          greedy staff auto-assignment, phone masking.
 * WHY THIS NAME: "vendor" = bus operator companies.
 * CONNECTS TO: core/ds_stack (undo, row 6), ds_heap + ds_sort (auto-assign, row 16), ds_fenwick (revenue, row 15).
 * COMPLEXITY: auto-assign O(n log n) for n trips; undo O(1) amortised per record.
 * RULE (D13): another company's bus/trip/staff always looks like "Not found".
 */

extern "C" {
}

namespace sr {

static constexpr int64_t REST_AFTER_TRIP_MS = 8 * MS_HOUR;

int App::staff_status(const Staff &s) const {
    if (s.off_duty) return SS_OFF_DUTY;                         /* status is derived, never stored */
    if (s.bus_idx < 0) return SS_AVAILABLE;
    return buses[(size_t)s.bus_idx].status == BUS_ON_TRIP ? SS_ON_TRIP : SS_ASSIGNED;
}

std::string App::mask_phone(const char *phone, bool reveal) const {
    if (reveal) return phone;
    std::string p = phone;
    std::string tail = p.size() >= 4 ? p.substr(p.size() - 4) : p;
    return "XXXXXX" + tail;
}

static bool owns_bus(const App &app, int company_id, int bus_idx) {
    return bus_idx >= 0 && (size_t)bus_idx < app.buses.size() && app.buses[(size_t)bus_idx].company_id == company_id;
}

Result<Unit> App::assign_staff(int company_id, int bus_idx, int staff_id) {
    if (!owns_bus(*this, company_id, bus_idx)) return Result<Unit>::fail(Err::NOT_FOUND, "Bus not found");
    if (staff_id < 1 || (size_t)staff_id > staff.size() || staff[(size_t)staff_id - 1].company_id != company_id)
        return Result<Unit>::fail(Err::NOT_FOUND, "Staff member not found");
    Staff &s = staff[(size_t)staff_id - 1];
    Bus &b = buses[(size_t)bus_idx];
    if (s.off_duty) return Result<Unit>::fail(Err::CONFLICT, std::string(s.name) + " is off duty and cannot be assigned");
    if (s.bus_idx >= 0 && s.bus_idx != bus_idx) return Result<Unit>::fail(Err::CONFLICT, std::string(s.name) + " is already assigned to " + buses[(size_t)s.bus_idx].reg);
    int &slot = s.role == STAFF_DRIVER ? b.driver_id : b.conductor_id;
    if (slot == staff_id) return okay("Already assigned");
    undo.push(UndoRec{s.role == STAFF_DRIVER ? 1 : 2, bus_idx, slot, company_id});   /* remember the previous holder */
    if (slot > 0) staff[(size_t)slot - 1].bus_idx = -1;
    slot = staff_id;
    s.bus_idx = bus_idx;
    return okay(std::string(s.name) + " assigned to " + b.reg);
}

Result<Unit> App::set_bus_status(int company_id, int bus_idx, int status, bool confirmed, int *affected) {
    if (!owns_bus(*this, company_id, bus_idx)) return Result<Unit>::fail(Err::NOT_FOUND, "Bus not found");
    if (status < BUS_AVAILABLE || status > BUS_MAINTENANCE) return Result<Unit>::fail(Err::VALIDATION, "Unknown bus status");
    Bus &b = buses[(size_t)bus_idx];
    int count = 0;
    if (status == BUS_MAINTENANCE) {                            /* who departs within the next 24 hours on this bus? */
        for (size_t i = 0; i < bookings.size(); i++) {
            const Booking &k = bookings[i];
            const Trip *t = trip_by_id(k.trip_id);
            if (t && t->bus_idx == bus_idx && (k.status == BK_PREBOOKED || k.status == BK_CONFIRMED) &&
                t->depart_ms >= clock.now() && t->depart_ms - clock.now() <= 24 * MS_HOUR) count++;
        }
    }
    if (affected) *affected = count;
    if (count > 0 && !confirmed) return Result<Unit>::fail(Err::BAD_STATE, std::to_string(count) + " booking(s) depart within 24 hours. Confirm to continue.");
    undo.push(UndoRec{0, bus_idx, b.status, company_id});
    b.status = status;
    if (count > 0) {
        for (size_t i = 0; i < bookings.size(); i++) {
            const Booking &k = bookings[i];
            const Trip *t = trip_by_id(k.trip_id);
            if (t && t->bus_idx == bus_idx && (k.status == BK_PREBOOKED || k.status == BK_CONFIRMED))
                notify(k.user_id, NK_BOOKING, "Bus unavailable", "Your bus " + std::string(b.reg) + " is in maintenance. The operator will contact you.", "maint:" + std::to_string(k.id));
        }
        flush_outbox();
    }
    return okay("Bus status updated");
}

Result<std::string> App::undo_last(int company_id) {
    Stack<UndoRec> keep;                                        /* park other companies' records, then restore them */
    UndoRec rec;
    bool found = false;
    while (undo.pop(&rec)) {
        if (rec.company_id == company_id) { found = true; break; }
        keep.push(rec);
    }
    UndoRec back;
    Stack<UndoRec> reverse;
    while (keep.pop(&back)) reverse.push(back);
    while (reverse.pop(&back)) undo.push(back);                 /* original order restored */
    if (!found) return Result<std::string>::fail(Err::NOT_FOUND, "Nothing to undo");
    Bus &b = buses[(size_t)rec.bus_idx];
    if (rec.kind == 0) { b.status = rec.old_value; return Result<std::string>::success("Status restored for " + std::string(b.reg)); }
    int &slot = rec.kind == 1 ? b.driver_id : b.conductor_id;
    if (slot > 0) staff[(size_t)slot - 1].bus_idx = -1;
    slot = rec.old_value;
    if (slot > 0) staff[(size_t)slot - 1].bus_idx = rec.bus_idx;
    return Result<std::string>::success("Assignment restored for " + std::string(b.reg));
}

Result<Unit> App::start_trip(int company_id, int trip_id) {
    Trip *t = trip_by_id(trip_id);
    if (!t || buses[(size_t)t->bus_idx].company_id != company_id) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    if (t->status != TRIP_SCHEDULED) return Result<Unit>::fail(Err::BAD_STATE, "Only a scheduled trip can be started");
    t->status = TRIP_RUNNING;
    buses[(size_t)t->bus_idx].status = BUS_ON_TRIP;
    return okay("Trip started");
}

Result<Unit> App::complete_trip(int company_id, int trip_id) {
    Trip *t = trip_by_id(trip_id);
    if (!t || buses[(size_t)t->bus_idx].company_id != company_id) return Result<Unit>::fail(Err::NOT_FOUND, "Trip not found");
    if (t->status != TRIP_RUNNING) return Result<Unit>::fail(Err::BAD_STATE, "Only a running trip can be completed");
    t->status = TRIP_COMPLETED;
    buses[(size_t)t->bus_idx].status = BUS_AVAILABLE;
    for (size_t i = 0; i < bookings.size(); i++)
        if (bookings[i].trip_id == t->id && legal_transition(bookings[i].status, BK_COMPLETED)) bookings[i].status = BK_COMPLETED;
    return okay("Trip completed");
}

/* ---------- greedy auto-assignment ---------- */

struct TripSlot { int64_t depart_ms; int trip_id; };
static int cmp_slot(const void *a, const void *b) {
    int64_t x = static_cast<const TripSlot *>(a)->depart_ms, y = static_cast<const TripSlot *>(b)->depart_ms;
    return (x > y) - (x < y);
}

/* Assign one role: min-heap of "free at" times; a staff member whose free time is after the trip start would overlap. */
static int assign_role(App &app, MinHeap &heap, const Vec<TripSlot> &slots, int role, std::string *report) {
    int assigned = 0;
    for (size_t i = 0; i < slots.size(); i++) {
        Trip *t = app.trip_by_id(slots[i].trip_id);
        int64_t free_at;
        uint64_t sid;
        if (!heap.peek(&free_at, &sid) || free_at > t->depart_ms) {           /* nobody free: would overlap */
            *report += "  trip " + std::to_string(t->id) + " (" + fmt_hm(t->depart_ms) + ") has no free " + (role == STAFF_DRIVER ? "driver" : "conductor") + "\n";
            continue;
        }
        heap.pop(&free_at, &sid);
        (role == STAFF_DRIVER ? t->auto_driver : t->auto_conductor) = (int)sid;
        heap.push(t->arrive_ms + REST_AFTER_TRIP_MS, sid);                      /* busy until the trip ends + 8 h rest */
        assigned++;
    }
    return assigned;
}

int App::auto_assign(int company_id, int date_key, std::string *report) {
    Vec<TripSlot> slots;
    for (size_t si = 0; si < schedules.size(); si++) {
        const Bus &b = buses[(size_t)schedules[si].bus_idx];
        if (b.company_id != company_id || b.status == BUS_MAINTENANCE) continue;
        Trip *t = get_or_create_trip((int)si, date_key);
        if (!t) continue;
        t->auto_driver = t->auto_conductor = -1;
        slots.push(TripSlot{t->depart_ms, t->id});
    }
    ds_merge_sort(slots.data(), slots.size(), sizeof(TripSlot), cmp_slot);      /* by start time */
    MinHeap drivers, conductors;
    for (size_t i = 0; i < staff.size(); i++) {
        const Staff &s = staff[i];
        if (s.company_id != company_id || s.off_duty) continue;                 /* off-duty staff are never used */
        (s.role == STAFF_DRIVER ? drivers : conductors).push(0, (uint64_t)s.id);
    }
    report->clear();
    int d = assign_role(*this, drivers, slots, STAFF_DRIVER, report);
    int c = assign_role(*this, conductors, slots, STAFF_CONDUCTOR, report);
    *report = "Trips on the day: " + std::to_string(slots.size()) + ", drivers assigned: " + std::to_string(d) +
              ", conductors assigned: " + std::to_string(c) + "\n" + *report;
    return d + c;
}

}  // namespace sr

/* ===================== app/assistant.cpp ===================== */
/*
 * PURPOSE: A rule-based trip assistant (the original project's "AI Copilot" idea, without any AI service):
 *          it understands city names (even partial ones), dates, and "cheapest / fastest / morning / sleeper"
 *          in a sentence, then answers from the real search and journey planner.
 * WHY THIS NAME: "assistant" = the chat helper tab.
 * CONNECTS TO: core/ds_trie (partial city names via suggest_cities), core/ds_search (KMP phrase test), search.cpp, clock.hpp.
 * COMPLEXITY: O(words x L) for city matching + the search it triggers.
 * HONESTY: it is not artificial intelligence. It matches words with fixed rules, and says so when it cannot understand.
 */

extern "C" {
}

namespace sr {

static std::vector<std::string> words_of(const std::string &text) {
    std::vector<std::string> w;
    std::string cur;
    for (char ch : text) {
        unsigned char c = (unsigned char)ch;
        if (std::isalnum(c) || ch == '-' || ch == '+') cur += (char)std::tolower(c);
        else if (!cur.empty()) { w.push_back(cur); cur.clear(); }
    }
    if (!cur.empty()) w.push_back(cur);
    for (std::string &s : w) {                                       /* "-" and "+" only matter inside dates like 2026-10-24 or +3 */
        while (!s.empty() && s.back() == '-') s.pop_back();
        while (!s.empty() && s[0] == '-') s.erase(0, 1);
    }
    return w;
}

static bool has(const std::vector<std::string> &w, const char *x) { return std::find(w.begin(), w.end(), x) != w.end(); }

/* ---- clock phrases (spec 6.8): "after 7 am", "before 9pm", "after 19:30", "after 12 am" ---- */

static bool all_digits(const std::string &s) {
    return !s.empty() && std::all_of(s.begin(), s.end(), [](unsigned char c) { return std::isdigit(c) != 0; });
}

static int ampm_of(const std::string &s) { return s == "am" ? 0 : (s == "pm" ? 1 : -1); }

/* Tries to read a time of day starting at w[i] (the number token). On success returns minutes after
   midnight and sets *end to one past the consumed tokens; -1 if it does not look like a clock time. */
static int clock_time(const std::vector<std::string> &w, size_t i, size_t *end) {
    if (i >= w.size() || w[i].empty() || !std::isdigit((unsigned char)w[i][0])) return -1;
    std::string tok = w[i];
    int min = 0, ap = -1;
    size_t k = i + 1;
    size_t tail = tok.find_first_of("pm");                       /* "9pm" / "7am" in one token */
    if (tail != std::string::npos) {
        if (!all_digits(tok.substr(0, tail))) return -1;
        ap = ampm_of(tok.substr(tail));
        if (ap < 0) return -1;
        tok = tok.substr(0, tail);
    }
    if (!all_digits(tok)) return -1;
    int h = std::atoi(tok.c_str());
    if (h > 23) return -1;
    if (ap < 0 && k < w.size()) {
        if (ampm_of(w[k]) >= 0) { ap = ampm_of(w[k]); k++; }
        else if (all_digits(w[k]) && w[k].size() <= 2 && std::atoi(w[k].c_str()) <= 59) {
            int ap2 = (k + 1 < w.size()) ? ampm_of(w[k + 1]) : -1;
            if (ap2 >= 0) { min = std::atoi(w[k].c_str()); ap = ap2; k += 2; }        /* 7:30 am */
            else if (h >= 13) { min = std::atoi(w[k].c_str()); k += 1; }              /* 19:30 */
        }
    }
    if (ap == 0 && h == 12) h = 0;                                /* 12 am = midnight */
    if (ap == 1 && h < 12) h += 12;                               /* 12 pm = noon */
    *end = k;
    return h * 60 + min;
}

AssistantAnswer App::assistant(const std::string &text) {
    AssistantAnswer a;
    std::vector<std::string> w = words_of(text.substr(0, 300));
    static const char *STOP[] = {"the", "for", "and", "bus", "buses", "any", "get", "can", "you", "from", "via", "tom", "day", "now", "show", "find", "book", "need", "want", "ticket", "tickets"};
    struct Hit { size_t pos; int city; };
    std::vector<Hit> hits;
    for (size_t i = 0; i < w.size(); i++) {                          /* city names: exact (hash) or a unique prefix (trie) */
        int city = find_city(w[i]);
        if (city < 0 && w[i].size() >= 3 && !std::any_of(std::begin(STOP), std::end(STOP), [&](const char *s) { return w[i] == s; })) {
            char out[10][64]; int ids[10];
            if (suggest_cities(w[i].c_str(), 10, out, ids) == 1) city = ids[0];
        }
        if (city >= 0) hits.push_back(Hit{i, city});
    }
    int from = -1, to = -1;
    for (size_t h = 0; h < hits.size(); h++) {                       /* "from X" / "to Y" keywords decide direction */
        size_t before = hits[h].pos;
        if (before >= 1 && w[before - 1] == "from") from = hits[h].city;
        if (before >= 1 && (w[before - 1] == "to" || w[before - 1] == "for" || w[before - 1] == "towards")) to = hits[h].city;
    }
    for (size_t h = 0; h < hits.size() && (from < 0 || to < 0); h++) {    /* otherwise: order of mention */
        if (hits[h].city == from || hits[h].city == to) continue;
        if (from < 0 && to != hits[h].city) from = hits[h].city; else if (to < 0) to = hits[h].city;
    }
    if (from < 0 && to >= 0 && hits.size() >= 2) from = to;          /* "Delhi to Delhi": both mentions are the same city */
    if (to < 0 && from >= 0 && hits.size() >= 2) to = from;
    a.from = from; a.to = to;
    if (from < 0 && to >= 0) {
        a.text = "Where are you leaving from? Try: \"bus from Jaipur to " + std::string(cities[(size_t)to].name) + " tomorrow\".";
        return a;
    }
    if (from < 0) {
        a.text = "I can help you find a bus. Try: \"cheapest bus from Delhi to Jaipur tomorrow\" or \"fastest way from Mysuru to Madurai\". I understand city names, dates (today, tomorrow, +3, 2026-10-24) and words like cheapest, fastest, morning or sleeper. I am a rule-based helper, not an AI.";
        return a;
    }
    if (to < 0) {
        std::string list;
        for (size_t i = 0; i < routes.size(); i++) if (routes[i].from_city == from) list += (list.empty() ? "" : ", ") + std::string(cities[(size_t)routes[i].to_city].name);
        a.text = std::string(cities[(size_t)from].name) + " has direct buses to: " + (list.empty() ? "no city" : list) + ". Tell me where you want to go.";
        return a;
    }
    if (from == to) { a.text = "Please name two different cities."; return a; }
    int offset = 1;                                                  /* date: default tomorrow */
    bool assumed = true;
    int y, m, d;
    if (has(w, "today") || has(w, "now")) { offset = 0; assumed = false; }
    else if (has(w, "tomorrow") || has(w, "tmrw")) { offset = ds_kmp_contains_nocase(text.c_str(), "day after tomorrow") ? 2 : 1; assumed = false; }
    else if (has(w, "overmorrow")) { offset = 2; assumed = false; }
    for (size_t i = 0; i < w.size(); i++) {
        if (w[i][0] == '+' && w[i].size() > 1) { offset = std::atoi(w[i].c_str() + 1); assumed = false; }
        else if (w[i] == "in" && i + 2 < w.size() && std::isdigit((unsigned char)w[i + 1][0]) && w[i + 2].rfind("day", 0) == 0) { offset = std::atoi(w[i + 1].c_str()); assumed = false; }
        else if (parse_ist_date(w[i].c_str(), &y, &m, &d)) { offset = (int)(day_number(from_ist(y, m, d, 12, 0)) - day_number(clock.now())); assumed = false; }
    }
    if (offset < 0 || offset > 90) { a.text = "I can only look from today up to 90 days ahead."; return a; }
    a.date_key = date_key(clock.now() + (int64_t)offset * MS_DAY);
    SearchFilters f;
    SortKey sort = SORT_EARLIEST;
    std::string wants;
    if (has(w, "cheapest") || has(w, "cheap") || has(w, "budget") || has(w, "lowest") || has(w, "affordable")) { sort = SORT_CHEAPEST; wants = "cheapest first"; }
    else if (has(w, "fastest") || has(w, "quick") || has(w, "quickest") || has(w, "shortest")) { sort = SORT_FASTEST; wants = "fastest first"; }
    if (has(w, "morning")) f.dep_window = 1; else if (has(w, "afternoon")) f.dep_window = 2; else if (has(w, "evening") || has(w, "night") || has(w, "overnight")) f.dep_window = 3;
    if (has(w, "sleeper")) for (size_t i = 0; i < types.size(); i++) if (types[i].layout == LAYOUT_SLEEPER) f.type_mask |= 1u << i;
    if (has(w, "seater")) {
        for (size_t i = 0; i < types.size(); i++) if (types[i].layout != LAYOUT_SLEEPER) f.type_mask |= 1u << i;
        wants += (wants.empty() ? "seater coaches" : ", seater coaches");
    }
    /* coach makes live in the coach-type label ("Volvo-style Premium"): KMP, case-insensitive (structure 18) */
    static const char *MAKES[] = {"volvo", "scania", "mercedes", "electric"};
    for (const char *mk : MAKES) {
        if (!has(w, mk)) continue;
        for (size_t i = 0; i < types.size(); i++) {
            if (!ds_kmp_contains_nocase(types[i].label, mk)) continue;
            f.type_mask |= 1u << i;
            std::string nice(mk);
            nice[0] = (char)std::toupper((unsigned char)nice[0]);
            wants += (wants.empty() ? "" : ", ") + nice + (nice == "Electric" ? "-coach" : "-style");
        }
    }
    /* "after 7 am" / "before 9pm": departure time-of-day, minutes after midnight */
    for (size_t i = 0; i + 1 < w.size(); i++) {
        if (w[i] != "after" && w[i] != "before") continue;
        size_t end = i + 1;
        int mins = clock_time(w, i + 1, &end);
        if (mins < 0) continue;
        if (w[i] == "after") f.dep_after = mins; else f.dep_before = mins;
        char hhmm[16];
        std::snprintf(hhmm, sizeof hhmm, "%02d:%02d", mins / 60 % 24, mins % 60);
        wants += (wants.empty() ? "" : ", ") + std::string("leaving ") + w[i] + " " + hhmm;
        i = end - 1;
    }
    /* amenities: honour them when the catalogue has them, say so honestly when it has not (spec 6.8) */
    struct Ami { const char *word; const char *label; const char *needle; };
    static const Ami AMIS[] = {{"ac", "AC", "AC"}, {"air", "air conditioning", "AC"}, {"charging", "charging points", "Charging point"},
                               {"blanket", "blankets", "Blanket"}, {"snack", "snack box", "Snack box"}, {"cctv", "CCTV", "CCTV"},
                               {"wifi", "Wi-Fi", "Wi-Fi"}, {"wi-fi", "Wi-Fi", "Wi-Fi"}};
    for (const Ami &am : AMIS) {
        if (!has(w, am.word)) continue;
        bool in_catalogue = false;
        for (size_t i = 0; i < types.size(); i++) if (ds_kmp_contains_nocase(types[i].amenities, am.needle)) in_catalogue = true;
        if (!in_catalogue) {
            a.ignored.push_back(am.label);
            continue;
        }
        if (!f.amenity[0]) std::snprintf(f.amenity, sizeof f.amenity, "%s", am.needle);
    }
    a.sort_mode = sort; a.dep_window = f.dep_window; a.dep_after = f.dep_after; a.dep_before = f.dep_before;
    a.type_mask = f.type_mask; a.amenity = f.amenity;
    std::string ignore_note;
    for (size_t i = 0; i < a.ignored.size(); i++) ignore_note += (i ? ", " : "") + a.ignored[i];
    std::string route_txt = std::string(cities[(size_t)from].name) + " to " + cities[(size_t)to].name;
    std::string when = fmt_date(clock.now() + (int64_t)offset * MS_DAY) + (assumed ? " (I assumed tomorrow)" : "");
    if (find_route(from, to) < 0) {
        if (!same_network(from, to)) { a.text = "There is no bus route between " + route_txt + ": the two cities are in different bus networks."; return a; }
        Vec<PlanLeg> legs;
        int64_t mins = 0, paise = 0;
        Result<Unit> r = plan_journey(from, to, sort == SORT_CHEAPEST ? PLAN_CHEAPEST : PLAN_FASTEST, legs, &mins, &paise);
        if (!r.ok) { a.text = "No route found: " + r.message; return a; }
        std::string path = cities[(size_t)legs[0].from_city].name;
        for (size_t i = 0; i < legs.size(); i++) path += std::string(" -> ") + cities[(size_t)legs[i].to_city].name;
        a.text = "There is no direct bus " + route_txt + ", but you can connect: " + path + ", about " + fmt_duration((int)mins) + " in total including 60 minute layovers, lowest fares " + fmt_rs(paise) + " per seat. Use the Journey Planner tab for each leg.";
        return a;
    }
    Vec<SearchRow> rows;
    search(from, to, a.date_key, f, sort, rows);
    a.opened_search = rows.size() > 0;
    if (rows.size() == 0) {
        a.text = "No buses match for " + route_txt + " on " + when + ". Try another day or fewer filters.";
        if (!ignore_note.empty()) a.text += " (I ignored: " + ignore_note + " - not in the demo catalogue.)";
        return a;
    }
    a.text = std::to_string(rows.size()) + (rows.size() == 1 ? " bus" : " buses") + " for " + route_txt + " on " + when + (wants.empty() ? "" : ", " + wants) + ":\n";
    for (size_t i = 0; i < rows.size() && i < 3; i++) {
        const SearchRow &r = rows[i];
        a.text += "  " + std::to_string(i + 1) + ") " + bus_label(r.bus_idx) + ", " + types[(size_t)buses[(size_t)r.bus_idx].type_idx].label + ", " + fmt_hm(r.depart_ms) + " to " + fmt_hm_plus(r.arrive_ms, r.depart_ms) + ", from " + fmt_rs(r.fare_min) + ", " + std::to_string(r.seats_left) + " seats left\n";
    }
    a.text += "Press \"Open in Search\" to choose seats.";
    if (!ignore_note.empty()) a.text += " (Not in the demo catalogue, so I ignored: " + ignore_note + ".)";
    return a;
}

}  // namespace sr

/* ===================== app/http_server.cpp ===================== */
/*
 * PURPOSE: Tier 2 web layer: a small single-threaded HTTP server (raw sockets, no library) that serves
 *          web/index.html and a JSON API. It only calls the same App services as the CLI (no duplicated logic).
 * WHY THIS NAME: "http_server" = answers browser requests.
 * CONNECTS TO: app.hpp, asciimap.hpp, ticket.hpp. Windows uses Winsock (link with -lws2_32).
 * COMPLEXITY: O(request) + engine cost. One connection at a time (D10: single-threaded).
 * SECURITY NOTE: demo server for localhost. No TLS; tokens are random but sessions live in memory only.
 */

#ifdef _WIN32
#include <winsock2.h>
#include <ws2tcpip.h>
typedef SOCKET sock_t;
static void close_sock(sock_t s) { closesocket(s); }
static const sock_t BAD_SOCK = INVALID_SOCKET;
#else
#include <netinet/in.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>
typedef int sock_t;
static void close_sock(sock_t s) { close(s); }
static const sock_t BAD_SOCK = -1;
#endif

/* The page is compiled into the program (generated from web/index.html by the Makefile), so the server works from any folder. */
extern const unsigned char sr_page_data[];
extern const unsigned long sr_page_len;

namespace sr {

static std::string run_json(App &app, const Trip &t);        // defined below; used by the vendor, driver and admin handlers

static const char *role_name(int r) { return r == ROLE_VENDOR ? "vendor" : (r == ROLE_DRIVER ? "driver" : (r == ROLE_ADMIN ? "admin" : "passenger")); }

/* ---------- tiny JSON writer ---------- */

static std::string jq(const std::string &s) {
    std::string o = "\"";
    for (unsigned char c : s) {
        if (c == '"') o += "\\\"";
        else if (c == '\\') o += "\\\\";
        else if (c == '\n') o += "\\n";
        else if (c < 0x20) o += ' ';
        else o += (char)c;
    }
    return o + "\"";
}

class JObj {
    std::string s_ = "{";
    bool first_ = true;
    void key(const char *k) { if (!first_) s_ += ","; first_ = false; s_ += jq(k) + ":"; }
public:
    JObj &str(const char *k, const std::string &v) { key(k); s_ += jq(v); return *this; }
    JObj &num(const char *k, long long v) { key(k); s_ += std::to_string(v); return *this; }
    JObj &dbl(const char *k, double v) { key(k); char b[40]; std::snprintf(b, sizeof b, "%.4f", v); s_ += b; return *this; }
    JObj &boolean(const char *k, bool v) { key(k); s_ += v ? "true" : "false"; return *this; }
    JObj &raw(const char *k, const std::string &v) { key(k); s_ += v; return *this; }
    std::string done() const { return s_ + "}"; }
};

class JArr {
    std::string s_ = "[";
    bool first_ = true;
public:
    JArr &add(const std::string &raw) { if (!first_) s_ += ","; first_ = false; s_ += raw; return *this; }
    std::string done() const { return s_ + "]"; }
};

/* ---------- request / response ---------- */

struct Req {
    std::string method, path, body, origin;
    std::vector<std::pair<std::string, std::string>> params;   /* query string + form body */
    std::string token;
    std::string get(const char *k, const std::string &def = "") const {
        for (const auto &p : params) if (p.first == k) return p.second;
        return def;
    }
    long long num(const char *k, long long def = 0) const {
        std::string v = get(k);
        return v.empty() ? def : std::strtoll(v.c_str(), nullptr, 10);
    }
};

struct Resp { int status = 200; std::string type = "application/json"; std::string body; };

static std::string url_decode(const std::string &s) {
    std::string o;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '+') o += ' ';
        else if (s[i] == '%' && i + 2 < s.size() && std::isxdigit((unsigned char)s[i + 1]) && std::isxdigit((unsigned char)s[i + 2])) {
            o += (char)std::strtol(s.substr(i + 1, 2).c_str(), nullptr, 16);
            i += 2;
        } else o += s[i];
    }
    return o;
}

static void parse_pairs(const std::string &text, std::vector<std::pair<std::string, std::string>> *out) {
    for (const std::string &part : split_fields(text, '&')) {
        size_t eq = part.find('=');
        if (part.empty()) continue;
        out->push_back({url_decode(part.substr(0, eq)), eq == std::string::npos ? "" : url_decode(part.substr(eq + 1))});
    }
}

static Resp ok(const std::string &json) { Resp r; r.body = json; return r; }
static Resp err(int status, const std::string &msg) { Resp r; r.status = status; r.body = JObj().boolean("ok", false).str("error", msg).done(); return r; }
static int http_status_for(Err e) {
    switch (e) {
        case Err::NOT_FOUND: return 404;
        case Err::UNAUTHENTICATED: return 401;
        case Err::FORBIDDEN_ROLE: return 401;
        case Err::CONFLICT: case Err::SEAT_TAKEN: case Err::BAD_STATE: case Err::HOLD_EXPIRED: return 409;
        case Err::PAYMENT_DECLINED: return 402;
        default: return 400;
    }
}
template <class T> static Resp fail_of(const Result<T> &r) { return err(http_status_for(r.code), r.message); }

/* ---------- server state ---------- */

struct Server {
    App &app;
    Map<int> sessions;            /* token -> user id */
    bool autosave;
    std::string web_dir;
    int64_t lookup_minute = -1;   /* public lookup is throttled: 20 per wall-clock minute (spec 7) */
    int lookup_count = 0;
    std::chrono::steady_clock::time_point anchor = std::chrono::steady_clock::now();   /* real-time start: see App::sync_wall_clock */
    int64_t virt_anchor_ms = 0;                                    /* the virtual time when the server started */
    std::string basemap_cache;                    /* /basemap.json body: read once from disk or generated (see h_basemap) */
    Server(App &a, bool save, const std::string &dir) : app(a), autosave(save), web_dir(dir) {}
};

static const size_t MAX_ACCOUNTS = 2000;      /* abuse limits found by probing (spec 7) */
static const int MAX_GUESTS = 300;
static const size_t MAX_SESSIONS = 5000;
static const int MAX_LOOKUPS_PER_MINUTE = 20;

static int user_of(Server &sv, const Req &rq) {
    int *u = sv.sessions.get(rq.token);
    return u ? *u : 0;
}

static std::string new_token(App &app) {
    char b[40];
    std::snprintf(b, sizeof b, "%016llx%016llx", (unsigned long long)app.next_random(), (unsigned long long)app.next_random());
    return b;
}

/* ---------- JSON builders for engine objects ---------- */

static std::string row_json(App &app, const SearchRow &r) {
    const Bus &b = app.buses[(size_t)r.bus_idx];
    const BusType &bt = app.types[(size_t)b.type_idx];
    const Route &rt = app.routes[(size_t)r.route_id];
    JArr st;
    for (int i = 0; i < rt.n_stops; i++) st.add(JObj().dbl("km", rt.stops[i].km).num("type", rt.stops[i].type).str("name", rt.stops[i].name).num("break_min", rt.stops[i].break_min).done());
    return JObj().str("from", app.cities[(size_t)rt.from_city].name).str("to", app.cities[(size_t)rt.to_city].name).dbl("total_km", rt.km_nominal).raw("stops", st.done()).num("trip", app.trip_by_id(r.trip_id)->id).str("operator", app.companies[(size_t)b.company_id - 1].name).str("reg", b.reg).str("type", bt.label)
        .str("amenities", bt.amenities).str("dep", fmt_hm(r.depart_ms)).str("arr", fmt_hm_plus(r.arrive_ms, r.depart_ms)).num("duration", r.duration_min)
        .str("duration_text", fmt_duration(r.duration_min)).num("fare_min", r.fare_min).num("fare_max", r.fare_max).num("seats", r.seats_left)
        .str("bar", journey_bar(app.routes[(size_t)r.route_id], -1)).done();
}

static std::string trip_json(App &app, const Trip &t, int user) {
    const Route &r = app.routes[(size_t)t.route_id];
    const BusType &bt = app.types[(size_t)app.buses[(size_t)t.bus_idx].type_idx];
    JArr stops, seats;
    for (int i = 0; i < r.n_stops; i++)
        stops.add(JObj().num("idx", i).str("name", r.stops[i].name).num("type", r.stops[i].type).dbl("km", r.stops[i].km).num("break_min", r.stops[i].break_min)
                      .str("time", fmt_hm_plus(app.planned_stop_time(t, i), t.depart_ms)).done());
    for (const SeatCell &c : app.seat_map(t, user))
        seats.add(JObj().str("label", c.label).num("state", c.state).num("row", app.seat_row(bt, c.index)).num("idx", c.index)
                      .num("price", seat_fare_paise(r.km_nominal, bt.rate_paise_per_km, bt.layout == LAYOUT_SLEEPER && c.label[0] == 'L')).done());
    int64_t exp = user ? app.hold_expiry(t.id, user) : 0;
    return JObj().num("id", t.id).str("route", app.route_name(r)).str("operator", app.bus_label(t.bus_idx)).str("type", bt.label).num("layout", bt.layout)
        .str("depart", fmt_datetime(t.depart_ms)).str("arrive", fmt_hm_plus(t.arrive_ms, t.depart_ms)).num("km", r.km_nominal).num("rate", bt.rate_paise_per_km)
        .boolean("sales_open", app.sales_open(t)).num("hold_seconds", exp ? (exp - app.clock.now()) / 1000 : 0).raw("stops", stops.done()).raw("seats", seats.done()).done();
}

static std::string booking_json(App &app, const Booking &b) {
    const Trip *t = app.trip_by_id(b.trip_id);
    JArr pax;
    for (int i = 0; i < b.n_pax; i++) pax.add(JObj().str("seat", b.pax[i].seat).str("name", b.pax[i].name).num("age", b.pax[i].age).str("gender", std::string(1, b.pax[i].gender)).num("price", b.pax[i].price).boolean("boarded", (b.boarded_mask >> i) & 1).done());
    RefundPreview p = app.cancel_preview(b);
    return JObj().num("id", b.id).str("pnr", b.pnr).num("trip", b.trip_id).str("route", app.route_name(app.routes[(size_t)t->route_id])).str("depart", fmt_datetime(t->depart_ms))
        .str("status", booking_status_name(b.status)).str("pay_status", pay_status_name(b.pay_status)).num("mode", b.mode).num("total", b.total).num("paid", b.paid).num("refunded", b.refunded)
        .num("base", b.base).num("discount", b.discount).num("tax", b.tax).num("insurance", b.insurance)
        .num("boarding", b.boarding_stop).num("dropping", b.dropping_stop).str("balance_due", b.status == BK_PREBOOKED ? fmt_datetime(b.balance_due_ms) : "").num("refund_pct", p.pct).num("refund_now", p.refund)
        .boolean("demo_payment", b.demo_payment != 0).raw("passengers", pax.done()).done();
}

static std::string track_json(App &app, const Trip &t, int drop, bool owner, const Booking *bk = nullptr) {
    const Route &r = app.routes[(size_t)t.route_id];
    TrackInfo ti = app.track_info(t);
    JArr stops;
    for (int i = 0; i < r.n_stops; i++) {
        const Stop &s = r.stops[i];
        int64_t planned = app.planned_stop_time(t, i);
        int64_t eta = app.eta_at_stop(t, i);
        long long late = (long long)std::llround((double)(eta - planned) / 60000.0);
        stops.add(JObj().str("name", s.name).num("type", s.type).dbl("km", s.km).num("break_min", s.break_min).str("time", fmt_hm_plus(planned, t.depart_ms))
                      .num("planned_ms", planned).num("eta_ms", eta).num("late_min", late < 0 ? 0 : late)
                      .str("state", t.km >= s.km + 1e-9 ? "done" : (std::fabs(t.km - s.km) < 1e-6 ? "now" : "upcoming")).dbl("lat", s.pos.lat).dbl("lng", s.pos.lng).done());
    }
    geo_point p = app.bus_position(r, t.km);
    /* Tracker extras for the web panel: which bus and crew are on this run, the stop it is heading
       for, the intermediate halts ("via"), and whether a driver device has actually reported a
       position. "basis" is "gps" once the driver console has sent a fix and "schedule" before that,
       so the page can say which of the two the percentage came from (same rule as the TS app). */
    const Bus &bus = app.buses[(size_t)t.bus_idx];
    int drv = app.trip_driver(t), con = app.trip_conductor(t);
    const GpsFix *fix = nullptr;                                    /* newest fix for this trip, if any */
    long long n_fixes = 0; double fix_speed_sum = 0.0;              /* telemetry: how many fixes the driver reported and their mean speed */
    for (size_t i = app.gps_fixes.size(); i-- > 0;) if (app.gps_fixes[i].trip_id == t.id) {
        n_fixes++; fix_speed_sum += app.gps_fixes[i].speed;
        if (!fix) fix = &app.gps_fixes[i];
    }
    int next = -1;
    for (int i = 0; i < r.n_stops; i++) {
        const Stop &s = r.stops[i];                                 /* toll plazas are passed, never stopped at */
        if (s.type == ST_TOLL || s.km <= t.km + 1e-9) continue;
        if (next < 0 || s.km < r.stops[next].km) next = i;
    }
    std::string via;
    for (int i = 0; i < r.n_stops; i++) {
        const Stop &s = r.stops[i];
        if (s.type != ST_BOARDING && s.type != ST_BREAK) continue;
        if (!via.empty()) via += ", ";
        via += s.name;
    }
    const char *no_staff = "";
    const Stop *ds = (drop >= 0 && drop < r.n_stops) ? &r.stops[(size_t)drop] : nullptr;   /* drop-off details when ?drop=<idx> */
    return JObj().num("trip", t.id).str("route", app.route_name(r)).dbl("km", t.km).dbl("total_km", r.km_nominal).dbl("progress", ti.progress_pct).dbl("km_left", ti.km_left)
        .dbl("speed", ti.speed_kmh).str("scheduled", fmt_hm_plus(ti.sched_arrive, t.depart_ms)).str("estimated", fmt_hm_plus(ti.est_arrive, t.depart_ms)).num("delay", ti.delay_min)
        .num("sched_arrive_ms", ti.sched_arrive).num("est_arrive_ms", ti.est_arrive)   /* the tracker headline counts down against these */
        .str("delay_reason", t.delay_reason).boolean("on_break", ti.on_break).num("break_left", ti.break_min_left).boolean("jam", t.jam_left_km > 0).num("speed_x", t.sim_speed)
        .str("status", t.status == TRIP_SCHEDULED ? "SCHEDULED" : (t.status == TRIP_RUNNING ? "RUNNING" : "COMPLETED")).str("sim_time", fmt_datetime(ti.sim_now))
        .dbl("lat", p.lat).dbl("lng", p.lng).str("map", render_route_map(app, r, t.km, false)).str("bar", journey_bar(r, t.km, 60)).raw("stops", stops.done())
        .str("reg", bus.reg).str("operator", app.companies[(size_t)bus.company_id - 1].name).str("type", app.types[(size_t)bus.type_idx].label)
        .str("driver", drv > 0 ? app.staff[(size_t)drv - 1].name : no_staff).str("conductor", con > 0 ? app.staff[(size_t)con - 1].name : no_staff)
        /* "ON THIS COACH" call buttons on the tracker: same privacy rule as the ticket (spec 9.11) -
           the demo phone numbers only reach the page 24 h before departure for a paid booking. */
        .str("driver_phone", bk && drv > 0 && driver_phones_visible(app, *bk) ? app.staff[(size_t)drv - 1].phone : no_staff)
        .str("conductor_phone", bk && con > 0 && driver_phones_visible(app, *bk) ? app.staff[(size_t)con - 1].phone : no_staff)
        .str("via", via).num("next_type", next < 0 ? -1 : r.stops[next].type).str("next_stop", next < 0 ? no_staff : r.stops[next].name)
        .dbl("next_km", next < 0 ? 0.0 : r.stops[next].km).dbl("next_in", next < 0 ? 0.0 : r.stops[next].km - t.km)
        .str("next_time", next < 0 ? no_staff : fmt_hm_plus(app.planned_stop_time(t, next) + (int64_t)ti.delay_min * 60000, t.depart_ms))
        .str("basis", fix ? "gps" : "schedule").boolean("has_fix", fix != nullptr)
        .dbl("reported_speed", fix ? fix->speed : 0.0).dbl("heading", fix ? fix->heading : 0.0).dbl("accuracy", fix ? fix->accuracy : 0.0)
        .str("fix_at", fix ? fmt_datetime(fix->at_ms) : no_staff).dbl("fix_lat", fix ? fix->lat : 0.0).dbl("fix_lng", fix ? fix->lng : 0.0)
        .str("delay_note", t.delay_note).num("fixes", n_fixes).dbl("avg_kmh", n_fixes ? fix_speed_sum / (double)n_fixes : 0.0)
        .boolean("owner", owner)                                        /* the page only shows the simulator to the booking's owner (spec 6.9) */
        .str("drop_name", ds ? ds->name : no_staff)
        .dbl("km_to_drop", ds ? std::max(0.0, ds->km - t.km) : 0.0).num("drop_eta_ms", ds ? app.eta_at_stop(t, drop) : 0).done();
}

/* ---------- handlers ---------- */

static Resp h_state(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    sv.app.flush_outbox();
    JObj o;
    o.str("now", fmt_datetime(sv.app.clock.now())).num("now_ms", sv.app.clock.now());
    if (u) {
        const User *us = sv.app.user_by_id(u);
        o.raw("user", JObj().num("id", u).str("name", us->name).str("role", role_name(us->role))
                             .boolean("guest", us->hash[0] == '!')
                             .str("company", us->company_id ? sv.app.companies[(size_t)us->company_id - 1].name : "").done());
        o.num("bell", sv.app.unread_count(u));
    } else o.raw("user", "null").num("bell", 0);
    return ok(o.done());
}

static Resp h_cities(Server &sv, const Req &rq) {
    char out[10][64]; int ids[10];
    size_t n = sv.app.suggest_cities(rq.get("prefix").c_str(), 10, out, ids);
    JArr a;
    for (size_t i = 0; i < n; i++) a.add(JObj().num("id", ids[i]).str("name", sv.app.cities[(size_t)ids[i]].name).str("state", sv.app.cities[(size_t)ids[i]].state).done());
    return ok(a.done());
}

static Resp h_auth(Server &sv, const Req &rq, bool is_register) {
    if (is_register && sv.app.users.size() >= MAX_ACCOUNTS) return err(429, "The demo has reached its account limit. Try again later.");
    Result<int> r = is_register ? sv.app.register_passenger(rq.get("name"), rq.get("email"), rq.get("phone"), rq.get("password"))
                                : sv.app.login(rq.get("email"), rq.get("password"), rq.get("role") == "vendor" ? ROLE_VENDOR : (rq.get("role") == "driver" ? ROLE_DRIVER : (rq.get("role") == "admin" ? ROLE_ADMIN : ROLE_PASSENGER)));
    if (!r.ok) return fail_of(r);
    if (sv.sessions.size() >= MAX_SESSIONS) return err(429, "Too many open sessions. Try again later.");
    std::string tok = new_token(sv.app);
    sv.sessions.put(tok, r.value);
    if (is_register && sv.autosave) { std::string e; sv.app.save_all(&e); }
    return ok(JObj().boolean("ok", true).str("token", tok).str("name", sv.app.user_by_id(r.value)->name).done());
}

/* Booking without an account (spec 6.4): a guest passenger row whose hash is "!" can never be
   signed into; it is reachable only through the random token handed back here. */
static Resp h_guest(Server &sv, const Req &) {
    if (sv.sessions.size() >= MAX_SESSIONS) return err(429, "Too many open sessions. Try again later.");
    if (sv.app.users.size() >= MAX_ACCOUNTS || sv.app.guest_count() >= MAX_GUESTS)
        return err(429, "The demo has reached its guest limit. Try again later.");
    int id = sv.app.add_guest();
    std::string tok = new_token(sv.app);
    sv.sessions.put(tok, id);
    if (sv.autosave) { std::string e; sv.app.save_all(&e); }
    return ok(JObj().boolean("ok", true).str("token", tok).str("name", "Guest traveller").boolean("guest", true).done());
}

/* Public lookup (spec 6.4): find a trip by booking reference, or by the phone used at checkout
   comparing the LAST 10 digits (so "+91 98765 43210" equals "9876543210"). Route, time and status
   only - never names. Throttled to MAX_LOOKUPS_PER_MINUTE per minute of the engine clock. */
static std::string digits_of(const std::string &s) {
    std::string d;
    for (char c : s) if (std::isdigit((unsigned char)c)) d += c;
    return d;
}

static Resp h_lookup(Server &sv, const Req &rq) {
    int64_t minute = sv.app.clock.now() / 60000;
    if (sv.lookup_minute != minute) { sv.lookup_minute = minute; sv.lookup_count = 0; }
    if (++sv.lookup_count > MAX_LOOKUPS_PER_MINUTE) return err(429, "Too many lookups. Wait a minute and try again.");
    std::string q = rq.get("q");
    for (char &c : q) c = (char)std::toupper((unsigned char)c);
    const Booking *b = nullptr;
    if (q.size() >= 4) {                                        /* booking reference: hash map, O(1) */
        int *at = sv.app.idx_pnr.get(q);
        if (at && (size_t)*at < sv.app.bookings.size()) b = &sv.app.bookings[(size_t)*at];
    }
    if (!b && q.size() >= 6) {                                /* phone: newest booking first */
        std::string want = digits_of(q);
        if (want.size() >= 10) {
            want = want.substr(want.size() - 10);
            for (size_t i = sv.app.bookings.size(); i-- > 0 && !b;) {
                std::string have = digits_of(sv.app.bookings[i].contact);
                if (have.size() >= 10 && have.substr(have.size() - 10) == want) b = &sv.app.bookings[i];
            }
        }
    }
    if (!b) return err(404, "No booking found for that reference or phone number");
    const Trip *t = sv.app.trip_by_id(b->trip_id);
    if (!t) return err(404, "No booking found for that reference or phone number");
    /* route, time and status only - never names, and no reference either (the requester may have found
       it by phone, and a PNR must not leak that way) */
    return ok(JObj().boolean("ok", true).num("trip", t->id).str("route", sv.app.route_name(sv.app.routes[(size_t)t->route_id]))
                  .str("depart", fmt_datetime(t->depart_ms)).str("status", booking_status_name(b->status)).done());
}

static Resp h_search(Server &sv, const Req &rq) {
    App &a = sv.app;
    int from = a.find_city(rq.get("from")), to = a.find_city(rq.get("to")), y, m, d;
    if (from < 0 || to < 0) return err(400, "Choose two valid cities");
    if (from == to) return err(400, "Choose two different cities");
    if (a.find_route(from, to) < 0) return err(404, std::string("No direct bus route. ") + (a.same_network(from, to) ? "Try the journey planner." : "These cities are in different bus networks."));
    if (!parse_ist_date(rq.get("date").c_str(), &y, &m, &d)) return err(400, "Date must be YYYY-MM-DD");
    int64_t ahead = day_number(from_ist(y, m, d, 12, 0)) - day_number(a.clock.now());
    if (ahead < 0 || ahead > 90) return err(400, "Choose a date from today up to 90 days ahead");
    SearchFilters f;
    f.dep_window = rq.get("dep").empty() ? -1 : (int)rq.num("dep");
    f.dep_after = rq.get("after").empty() ? -1 : (int)rq.num("after");     /* minutes after midnight: "leaving after 7 am" */
    f.dep_before = rq.get("before").empty() ? -1 : (int)rq.num("before");
    f.max_fare = rq.num("maxfare") * 100;
    std::snprintf(f.operator_substr, sizeof f.operator_substr, "%s", rq.get("op").c_str());
    f.need_seats = rq.get("seats") == "1";
    if (!rq.get("type").empty() && rq.num("type") >= 0 && rq.num("type") < 31) f.type_mask = 1u << (unsigned)rq.num("type");
    for (const std::string &part : split_fields(rq.get("types"), ','))      /* coach-type list from the assistant ("seater") */
        if (!part.empty() && std::strtoll(part.c_str(), nullptr, 10) >= 0 && std::strtoll(part.c_str(), nullptr, 10) < 31)
            f.type_mask |= 1u << (unsigned)std::strtoll(part.c_str(), nullptr, 10);
    if (rq.get("amenity")[0]) std::snprintf(f.amenity, sizeof f.amenity, "%s", rq.get("amenity").c_str());
    Vec<SearchRow> rows;
    a.search(from, to, y * 10000 + m * 100 + d, f, (SortKey)rq.num("sort", 0), rows);
    JArr arr;
    for (size_t i = 0; i < rows.size(); i++) arr.add(row_json(a, rows[i]));
    return ok(JObj().raw("rows", arr.done()).str("route", a.route_name(a.routes[(size_t)a.find_route(from, to)]))
        .dbl("fare_cap", (double)a.route_highest_fare(a.find_route(from, to)) / 100.0).done());
}

static std::vector<std::string> seat_list(const std::string &s) {
    std::vector<std::string> v;
    for (const std::string &p : split_fields(s, ',')) if (!p.empty()) v.push_back(p);
    return v;
}

static Resp h_hold(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    std::vector<std::string> seats = seat_list(rq.get("seats"));
    std::vector<const char *> labels;
    for (const std::string &s : seats) labels.push_back(s.c_str());
    Result<Unit> r = sv.app.hold_seats(u, (int)rq.num("trip"), labels.data(), (int)labels.size());
    return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
}

static Resp h_quote(Server &sv, const Req &rq) {
    std::vector<std::string> seats = seat_list(rq.get("seats"));
    std::vector<const char *> labels;
    for (const std::string &s : seats) labels.push_back(s.c_str());
    Result<Quote> q = sv.app.quote((int)rq.num("trip"), labels.data(), (int)labels.size(), rq.get("coupon").c_str(), rq.get("insurance") == "1", user_of(sv, rq));
    if (!q.ok) return fail_of(q);
    const Quote &v = q.value;
    return ok(JObj().boolean("ok", true).num("base", v.base).num("discount", v.discount).num("tax", v.tax).num("insurance", v.insurance).num("total", v.total).num("deposit", v.deposit)
                  .num("balance", v.balance).boolean("prebook", v.prebook_eligible).str("balance_due", fmt_datetime(v.balance_due_ms)).done());
}

static Resp h_book(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    std::vector<std::string> seats = seat_list(rq.get("seats"));
    BookingRequest b;
    b.user_id = u; b.trip_id = (int)rq.num("trip"); b.n_pax = (int)std::min<size_t>(seats.size(), (size_t)MAX_PAX + 1);
    if (b.n_pax > MAX_PAX) return err(400, "Choose 1 to 6 seats");
    for (int i = 0; i < b.n_pax; i++) {
        std::string idx = std::to_string(i + 1), nm = rq.get(("name" + idx).c_str());
        for (char &c : nm) if (c == '|' || c == '~' || c == ';' || c == '\\') c = ' ';
        std::snprintf(b.pax[i].seat, sizeof b.pax[i].seat, "%s", seats[(size_t)i].c_str());
        std::snprintf(b.pax[i].name, sizeof b.pax[i].name, "%s", nm.c_str());
        b.pax[i].age = (int)rq.num(("age" + idx).c_str());
        std::string g = rq.get(("gender" + idx).c_str());
        b.pax[i].gender = g.empty() ? 'X' : (char)std::toupper((unsigned char)g[0]);
    }
    b.boarding_stop = (int)rq.num("boarding", -1); b.dropping_stop = (int)rq.num("dropping", -1);
    std::snprintf(b.contact, sizeof b.contact, "%s", rq.get("contact").c_str());
    std::snprintf(b.coupon, sizeof b.coupon, "%s", rq.get("coupon").c_str());
    b.insurance = rq.get("insurance") == "1";
    b.mode = rq.get("mode") == "deposit" ? MODE_DEPOSIT : MODE_FULL;
    Result<int> r = sv.app.create_booking(b);
    if (!r.ok) return fail_of(r);
    if (sv.autosave) { std::string e; sv.app.save_all(&e); }
    return ok(JObj().boolean("ok", true).num("booking", r.value).str("pnr", sv.app.booking_by_id(r.value)->pnr).done());
}

static Resp h_pay(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    std::string k = rq.get("kind"), o = rq.get("outcome");
    Result<Unit> r = sv.app.pay_booking((int)rq.num("booking"), u, k == "deposit" ? PAYK_DEPOSIT : (k == "balance" ? PAYK_BALANCE : PAYK_FULL), o == "declined" ? OUT_DECLINED : (o == "timeout" ? OUT_TIMEOUT : OUT_SUCCESS));
    if (sv.autosave) { std::string e; sv.app.save_all(&e); }
    return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
}

static Resp h_bookings(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    JArr a;
    for (size_t i = sv.app.bookings.size(); i-- > 0;) if (sv.app.bookings[i].user_id == u) a.add(booking_json(sv.app, sv.app.bookings[i]));
    return ok(a.done());
}

static Resp h_ticket(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    Booking *b = sv.app.booking_by_pnr(rq.get("pnr"), u);
    if (!u || !b) return err(404, "Booking not found");
    const Trip *tr = sv.app.trip_by_id(b->trip_id);
    JArr crew;                                                       // privacy rule: only 24 h before departure, paid bookings
    if (driver_phones_visible(sv.app, *b)) {
        const Bus &bus = sv.app.buses[(size_t)tr->bus_idx];
        if (bus.driver_id > 0) crew.add(JObj().str("role", "Driver").str("name", sv.app.staff[(size_t)bus.driver_id - 1].name).str("phone", sv.app.staff[(size_t)bus.driver_id - 1].phone).done());
        if (bus.conductor_id > 0) crew.add(JObj().str("role", "Conductor").str("name", sv.app.staff[(size_t)bus.conductor_id - 1].name).str("phone", sv.app.staff[(size_t)bus.conductor_id - 1].phone).done());
    }
    unsigned char modules[QR_MAX_SIZE * QR_MAX_SIZE];
    int qsize = 0;
    JArr qrows;
    if (qr_encode(sv.app.qr_payload(*b).c_str(), modules, &qsize) == 0)          // the boarding-pass QR (drawn by the page as SVG)
        for (int y = 0; y < qsize; y++) { std::string row; for (int x = 0; x < qsize; x++) row += modules[y * qsize + x] ? '1' : '0'; qrows.add(jq(row)); }
    std::string state = sv.app.boarding_state(*b);
    const char *caption = state == "VALID" ? "Valid. Show this code at the door." : (state == "BOARDED" ? "All seats boarded." : (state == "PART-BOARDED" ? "Some seats are boarded." : "This pass is cancelled."));
    return ok(JObj().raw("booking", booking_json(sv.app, *b)).raw("trip", trip_json(sv.app, *tr, u)).raw("crew", crew.done())
              .raw("qr", qrows.done()).str("qr_text", sv.app.qr_payload(*b)).str("boarding_state", state).str("boarding_caption", caption).str("share_token", sv.app.share_token_of(b->id)).str("ticket", render_ticket(sv.app, *b, false)).str("share", share_summary(sv.app, *b)).done());
}

static Resp h_cancel(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    Booking *b = sv.app.booking_by_id((int)rq.num("booking"));
    if (!b || b->user_id != u) return err(404, "Booking not found");
    if (rq.get("preview") == "1") {
        RefundPreview p = sv.app.cancel_preview(*b);
        return ok(JObj().boolean("ok", true).num("pct", p.pct).num("refund", p.refund).num("hours_left", p.hours_left).done());
    }
    Result<int64_t> r = sv.app.cancel_booking(b->id, u);
    if (sv.autosave) { std::string e; sv.app.save_all(&e); }
    return r.ok ? ok(JObj().boolean("ok", true).num("refund", r.value).done()) : fail_of(r);
}

static Resp h_track(Server &sv, const Req &rq) {
    Trip *t = sv.app.trip_by_id((int)rq.num("trip"));
    if (!t) return err(404, "Trip not found");
    int u = user_of(sv, rq);                                          /* is the caller one of this trip's passengers? */
    bool owner = false;
    const Booking *mine = nullptr;                                    /* their booking, for the crew-phone privacy rule */
    if (u) for (size_t i = 0; i < sv.app.bookings.size(); i++)
        if (sv.app.bookings[i].trip_id == t->id && sv.app.bookings[i].user_id == u) { owner = true; if (!mine) mine = &sv.app.bookings[i]; }
    return ok(track_json(sv.app, *t, (int)rq.num("drop", -1), owner, mine));
}

static Resp h_sim(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    Trip *t = sv.app.trip_by_id((int)rq.num("trip"));
    if (!u || !t) return err(u ? 404 : 401, u ? "Trip not found" : "Please log in first");
    bool owns = false;                                              /* passengers may only simulate trips they booked */
    for (size_t i = 0; i < sv.app.bookings.size(); i++) if (sv.app.bookings[i].trip_id == t->id && sv.app.bookings[i].user_id == u) owns = true;
    if (!owns && sv.app.user_by_id(u)->role == ROLE_PASSENGER) return err(404, "Trip not found");
    std::string act = rq.get("action");
    long long speed = rq.num("speed", t->sim_speed);
    if (speed == 60 || speed == 120 || speed == 300) t->sim_speed = (int)speed;
    if (act == "play") for (int i = 0; i < 30; i++) sv.app.sim_advance(*t, t->sim_speed);
    else if (act == "tick") sv.app.sim_advance(*t, t->sim_speed);
    else if (act == "km") sv.app.sim_advance_km(*t, 10);
    else if (act == "jam") sv.app.sim_jam(*t);
    else if (act == "reset") sv.app.sim_reset(*t);
    if (sv.autosave) { std::string e; sv.app.save_all(&e); }
    return ok(track_json(sv.app, *t, -1, owns));
}

static Resp h_meta(Server &sv, const Req &) {                      // coach types and the 15 forward routes (for filters and route cards)
    App &a = sv.app;
    JArr types, routes;
    for (size_t i = 0; i < a.types.size(); i++) types.add(JObj().num("idx", (long long)i).str("label", a.types[i].label).done());
    for (size_t i = 0; i < a.routes.size(); i += 2)
        routes.add(JObj().str("from", a.cities[(size_t)a.routes[i].from_city].name).str("to", a.cities[(size_t)a.routes[i].to_city].name).num("km", a.routes[i].km_nominal).str("duration", fmt_duration(a.routes[i].duration_min)).done());
    return ok(JObj().raw("types", types.done()).raw("routes", routes.done()).num("networks", (long long)a.network_count()).done());
}

static Resp h_adjacent(Server &sv, const Req &rq) {              /* group seats: the C engine (bitset run search) decides */
    Trip *t = sv.app.trip_by_id((int)rq.num("trip"));
    int n = (int)rq.num("n");
    if (!t || n < 1 || n > MAX_PAX) return err(400, "Choose a trip and 1 to 6 seats");
    long at = sv.app.find_adjacent(*t, n);
    if (at < 0) return err(404, "No " + std::to_string(n) + " adjacent free seats in one row");
    const BusType &bt = sv.app.types[(size_t)sv.app.buses[(size_t)t->bus_idx].type_idx];
    JArr a;
    for (int i = 0; i < n; i++) { char lb[6]; sv.app.seat_label(bt, (int)at + i, lb); a.add(jq(lb)); }
    return ok(JObj().raw("seats", a.done()).done());
}

static Resp h_notes(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    sv.app.flush_outbox();
    JArr a;
    for (const Notification *n : sv.app.notifications_for(u)) a.add(JObj().str("title", n->title).str("body", n->body).str("time", fmt_hm(n->created_ms)).num("kind", n->kind).boolean("read", n->read != 0).done());
    return ok(JObj().raw("items", a.done()).num("prefs", sv.app.user_by_id(u)->prefs).done());
}

static Resp h_plan(Server &sv, const Req &rq) {
    App &a = sv.app;
    int from = a.find_city(rq.get("from")), to = a.find_city(rq.get("to"));
    if (from < 0 || to < 0) return err(400, "Choose two valid cities");
    Vec<PlanLeg> legs;
    int64_t mins = 0, paise = 0;
    Result<Unit> r = a.plan_journey(from, to, (PlanMode)rq.num("mode", 0), legs, &mins, &paise);
    if (!r.ok) return fail_of(r);
    JArr arr;
    for (size_t i = 0; i < legs.size(); i++) arr.add(JObj().str("from", a.cities[(size_t)legs[i].from_city].name).str("to", a.cities[(size_t)legs[i].to_city].name).str("duration", fmt_duration((int)legs[i].minutes)).num("fare", legs[i].paise).done());
    return ok(JObj().raw("legs", arr.done()).str("total", fmt_duration((int)mins)).num("fare", paise).done());
}

static Resp h_waitlist(Server &sv, const Req &rq) {
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    Result<Unit> r = sv.app.join_waitlist(u, (int)rq.num("trip"), (int)rq.num("seats", 1));
    return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
}

static Resp h_vendor(Server &sv, const Req &rq, const std::string &what) {
    int u = user_of(sv, rq);
    const User *us = u ? sv.app.user_by_id(u) : nullptr;
    if (!us || us->role != ROLE_VENDOR) return err(401, "Vendor login required");
    App &a = sv.app;
    int co = us->company_id;
    if (what == "fleet") {
        JArr arr;
        for (size_t i = 0; i < a.buses.size(); i++) {
            const Bus &b = a.buses[i];
            if (b.company_id != co) continue;
            arr.add(JObj().num("idx", (long long)i).str("reg", b.reg).str("type", a.types[(size_t)b.type_idx].label).str("status", bus_status_name(b.status)).num("status_code", b.status)
                        .str("driver", b.driver_id > 0 ? a.staff[(size_t)b.driver_id - 1].name : "").str("conductor", b.conductor_id > 0 ? a.staff[(size_t)b.conductor_id - 1].name : "").done());
        }
        return ok(arr.done());
    }
    if (what == "staff") {
        JArr arr;
        for (size_t i = 0; i < a.staff.size(); i++) {
            const Staff &s = a.staff[i];
            if (s.company_id == co) arr.add(JObj().num("id", s.id).str("name", s.name).str("role", s.role == STAFF_DRIVER ? "Driver" : "Conductor").str("status", staff_status_name(a.staff_status(s))).str("phone", std::string(s.phone) + " (DEMO number)").done());
        }
        return ok(arr.done());
    }
    if (what == "overview") {
        int bs[3] = {0, 0, 0};
        for (size_t i = 0; i < a.buses.size(); i++) if (a.buses[i].company_id == co) bs[a.buses[i].status]++;
        return ok(JObj().str("company", a.companies[(size_t)co - 1].name).num("available", bs[0]).num("on_trip", bs[1]).num("maintenance", bs[2]).num("revenue", a.revenue_range(co, 0, 119)).done());
    }
    if (what == "assign") { Result<Unit> r = a.assign_staff(co, a.find_bus(rq.get("reg").c_str()), (int)rq.num("staff")); return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r); }
    if (what == "status") {
        int affected = 0;
        Result<Unit> r = a.set_bus_status(co, a.find_bus(rq.get("reg").c_str()), (int)rq.num("status"), rq.get("confirm") == "1", &affected);
        return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
    }
    if (what == "undo") { Result<std::string> r = a.undo_last(co); return r.ok ? ok(JObj().boolean("ok", true).str("message", r.value).done()) : fail_of(r); }
    if (what == "autoassign") {
        std::string rep;
        int n = a.auto_assign(co, date_key(a.clock.now() + MS_DAY), &rep);
        return ok(JObj().boolean("ok", true).num("assigned", n).str("report", rep).done());
    }
    if (what == "delay") { Result<Unit> r = a.report_delay(co, (int)rq.num("trip"), rq.get("reason"), (int)rq.num("minutes"), rq.get("note")); return r.ok ? ok(JObj().boolean("ok", true).done()) : fail_of(r); }
    if (what == "runs") {                                               /* today's runs with crew and last report */
        JArr arr;
        for (Trip *t : a.trips_on_date(date_key(a.clock.now()), co)) arr.add(run_json(a, *t));
        return ok(arr.done());
    }
    if (what == "crew") {
        Result<Unit> r = a.assign_trip_crew(co, (int)rq.num("trip"), (int)rq.num("driver", -1), (int)rq.num("conductor", -1));
        if (r.ok && sv.autosave) { std::string e; a.save_all(&e); }
        return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
    }
    if (what == "staff-status") {
        Result<Unit> r = a.set_staff_off_duty(co, (int)rq.num("staff"), rq.get("off") == "1");
        if (r.ok && sv.autosave) { std::string e; a.save_all(&e); }
        return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
    }
    if (what == "trip") {
        std::string act = rq.get("action");
        Result<Unit> r = act == "start" ? a.start_trip(co, (int)rq.num("trip")) : (act == "complete" ? a.complete_trip(co, (int)rq.num("trip")) : Result<Unit>::fail(Err::VALIDATION, "Action must be start or complete"));
        return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
    }
    if (what == "manifest") {                                           /* phone numbers masked unless departure is within 24 h */
        Trip *t = a.trip_by_id((int)rq.num("trip"));
        if (!t || a.buses[(size_t)t->bus_idx].company_id != co) return err(404, "Trip not found");
        bool reveal = t->depart_ms - a.clock.now() <= 24 * MS_HOUR;
        JArr rows;
        for (size_t i = 0; i < a.bookings.size(); i++) {
            const Booking &b = a.bookings[i];
            if (b.trip_id != t->id || (b.status != BK_PREBOOKED && b.status != BK_CONFIRMED)) continue;
            for (int k = 0; k < b.n_pax; k++) rows.add(JObj().str("seat", b.pax[k].seat).str("name", b.pax[k].name).str("pnr", b.pnr).str("status", booking_status_name(b.status)).str("contact", a.mask_phone(b.contact, reveal)).done());
        }
        return ok(rows.done());
    }
    return err(404, "Unknown vendor action");
}

static Resp h_clock(Server &sv, const Req &rq) {
    long long mins = rq.num("minutes");
    if (mins < 1 || mins > 60 * 24 * 90) return err(400, "Minutes must be 1 to 129600");
    sv.app.advance_clock(mins * MS_MIN);
    if (sv.autosave) { std::string e; sv.app.save_all(&e); }
    return ok(JObj().boolean("ok", true).str("now", fmt_datetime(sv.app.clock.now())).done());
}

/* ---------- driver, admin, share links, assistant ---------- */

static const User *auth_user(Server &sv, const Req &rq, std::initializer_list<int> roles) {
    int u = user_of(sv, rq);
    const User *us = u ? sv.app.user_by_id(u) : nullptr;
    if (!us) return nullptr;
    for (int r : roles) if (us->role == r) return us;
    return nullptr;
}
#define NEED(var, ...) const User *var = auth_user(sv, rq, {__VA_ARGS__}); if (!var) return err(401, "Sign in with an account that can use this screen")

/* One row describing a trip for the driver, vendor and admin consoles. */
static std::string run_json(App &app, const Trip &t) {
    const Route &r = app.routes[(size_t)t.route_id];
    const Bus &bus = app.buses[(size_t)t.bus_idx];
    TrackInfo ti = app.track_info(t);
    int d = app.trip_driver(t), c = app.trip_conductor(t);
    JObj o;
    o.num("id", t.id).str("reg", bus.reg).str("operator", app.companies[(size_t)bus.company_id - 1].name).str("type", app.types[(size_t)bus.type_idx].label)
        .str("route", app.route_name(r)).str("depart", fmt_datetime(t.depart_ms)).str("dep", fmt_hm(t.depart_ms)).str("arr", fmt_hm_plus(t.arrive_ms, t.depart_ms))
        .str("est", fmt_hm_plus(ti.est_arrive, t.depart_ms)).str("status", t.status == TRIP_SCHEDULED ? "SCHEDULED" : (t.status == TRIP_RUNNING ? "RUNNING" : "COMPLETED"))
        .dbl("km", t.km).dbl("progress", ti.progress_pct).dbl("speed", ti.speed_kmh).num("delay", ti.delay_min).str("delay_reason", t.delay_reason)
        .num("booked", (long long)t.booked.count()).num("seats", (long long)app.seat_count(t)).num("driver_id", d).num("conductor_id", c)
        .str("driver", d ? app.staff[(size_t)d - 1].name : "").str("conductor", c ? app.staff[(size_t)c - 1].name : "")
        .str("driver_status", d ? staff_status_name(app.staff_status(app.staff[(size_t)d - 1])) : "").str("conductor_status", c ? staff_status_name(app.staff_status(app.staff[(size_t)c - 1])) : "");
    return o.done();
}

static Resp h_driver(Server &sv, const Req &rq, const std::string &what) {
    NEED(us, ROLE_DRIVER, ROLE_ADMIN);
    App &a = sv.app;
    if (what == "trips") {
        JArr arr;
        for (Trip *t : a.driver_trips(*us)) arr.add(run_json(a, *t));
        return ok(arr.done());
    }
    if (what == "scan") {
        bool already = false;
        Result<int> r = a.driver_scan(*us, rq.get("code"), &already);
        if (!r.ok) return fail_of(r);
        const Booking &b = *a.booking_by_id(r.value);
        JArr seats;
        for (int i = 0; i < b.n_pax; i++) seats.add(JObj().str("seat", b.pax[i].seat).str("name", b.pax[i].name).num("age", b.pax[i].age).boolean("checked_in", (b.boarded_mask >> i) & 1).done());
        return ok(JObj().boolean("found", true).boolean("already", already).raw("manifest", JObj().str("booking_reference", b.pnr).str("status", booking_status_name(b.status)).num("trip_id", b.trip_id)
            .str("boarding_state", a.boarding_state(b)).raw("seats", seats.done()).done()).done());
    }
    Trip *t = a.trip_by_id((int)rq.num("trip"));
    if (!t || !a.driver_can_access(*us, *t)) return err(404, "Trip not found");
    if (what == "start") { Result<Unit> r = a.driver_start(*us, t->id); return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r); }
    if (what == "end") { Result<Unit> r = a.driver_end(*us, t->id); return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r); }
    if (what == "delay") { Result<Unit> r = a.driver_delay(*us, t->id, rq.get("reason"), (int)rq.num("minutes"), rq.get("note")); return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r); }
    if (what == "position" || what == "simulate-fix") {
        double lat = std::atof(rq.get("lat").c_str()), lng = std::atof(rq.get("lng").c_str()), speed = std::atof(rq.get("speed", "45").c_str()), heading = std::atof(rq.get("heading", "0").c_str()), acc = std::atof(rq.get("accuracy", "10").c_str());
        if (what == "simulate-fix") {                                   /* DEMO: the "device" reports a point 5 km further along the route */
            const Route &r = a.routes[(size_t)t->route_id];
            geo_point p = a.bus_position(r, std::min((double)r.km_nominal, t->km + 5.0));
            lat = p.lat; lng = p.lng; speed = r.avg_kmh; heading = 90; acc = 12;
        } else if (rq.get("lat").empty() || rq.get("lng").empty()) return err(400, "Enter a latitude and a longitude");
        Result<Unit> r = a.driver_position(*us, t->id, lat, lng, speed, heading, acc);
        return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).dbl("lat", lat).dbl("lng", lng).done()) : fail_of(r);
    }
    if (what == "manifest") {
        JArr rows;
        const Route &r = a.routes[(size_t)t->route_id];
        for (size_t i = 0; i < a.bookings.size(); i++) {
            const Booking &b = a.bookings[i];
            if (b.trip_id != t->id || (b.status != BK_CONFIRMED && b.status != BK_PREBOOKED && b.status != BK_COMPLETED)) continue;
            for (int k = 0; k < b.n_pax; k++)
                rows.add(JObj().str("seat", b.pax[k].seat).str("name", b.pax[k].name).num("age", b.pax[k].age).str("boarding", std::string(r.stops[b.boarding_stop].name) + " " + fmt_hm(a.planned_stop_time(*t, b.boarding_stop)))
                    .str("pnr", b.pnr).str("status", booking_status_name(b.status)).boolean("checked_in", (b.boarded_mask >> k) & 1).str("checked_at", (b.boarded_mask >> k) & 1 ? fmt_hm(b.boarded_ms) : "").done());
        }
        return ok(rows.done());
    }
    if (what == "trail") {
        JArr rows;
        int shown = 0;
        for (size_t i = a.gps_fixes.size(); i-- > 0 && shown < 20;) {
            const GpsFix &g = a.gps_fixes[i];
            if (g.trip_id != t->id) continue;
            rows.add(JObj().str("at", fmt_datetime(g.at_ms)).dbl("lat", g.lat).dbl("lng", g.lng).dbl("heading", g.heading).dbl("speed", g.speed).dbl("accuracy", g.accuracy).done());
            shown++;
        }
        return ok(rows.done());
    }
    return err(404, "Unknown driver action");
}

static Resp h_admin(Server &sv, const Req &rq, const std::string &what) {
    NEED(us, ROLE_ADMIN);
    (void)us;
    App &a = sv.app;
    int today = date_key(a.clock.now());
    if (what == "summary") {
        int bs[3] = {0, 0, 0}, active = 0, pending = 0;
        for (size_t i = 0; i < a.buses.size(); i++) bs[a.buses[i].status]++;
        int64_t money = 0;
        for (size_t i = 0; i < a.bookings.size(); i++) { const Booking &b = a.bookings[i]; active += b.status == BK_CONFIRMED || b.status == BK_PREBOOKED; pending += b.status == BK_PENDING_PAYMENT; money += b.paid - b.refunded; }
        int run = 0, total = 0;
        for (Trip *t : a.trips_on_date(today, 0)) { total++; run += t->status == TRIP_RUNNING; }
        return ok(JObj().num("buses", (long long)a.buses.size()).num("available", bs[0]).num("on_trip", bs[1]).num("maintenance", bs[2]).num("companies", (long long)a.companies.size())
            .num("trips_today", total).num("running", run).num("active_bookings", active).num("pending", pending).num("revenue", money).num("networks", (long long)a.network_count()).done());
    }
    if (what == "fleet") {                                              /* today's fleet telemetry */
        JArr arr;
        for (Trip *t : a.trips_on_date(today, 0)) arr.add(run_json(a, *t));
        return ok(arr.done());
    }
    if (what == "revenue") {
        JArr arr;
        for (const CorridorRevenue &c : a.revenue_by_corridor()) arr.add(JObj().str("route", a.route_name(a.routes[(size_t)c.route])).num("passes", c.passes).num("revenue", c.paise).done());
        return ok(arr.done());
    }
    if (what == "coupons") {
        JArr arr;
        for (size_t i = 0; i < a.coupons.size(); i++) {
            const Coupon &c = a.coupons[i];
            arr.add(JObj().str("code", c.code).str("type", c.is_percent ? "PERCENT" : "FLAT_PAISE").num("value", c.value).num("cap", c.max_discount).num("min", c.min_base).num("uses", a.coupon_use_count((int)i)).num("max_uses", c.max_uses).boolean("active", c.active != 0).done());
        }
        return ok(arr.done());
    }
    if (what == "coupon-add") {
        bool pct = rq.get("type") == "PERCENT";
        double v = std::atof(rq.get("value").c_str()), cap = std::atof(rq.get("cap").c_str()), mn = std::atof(rq.get("min").c_str());
        Result<Unit> r = a.add_coupon(rq.get("code"), pct, pct ? (int64_t)std::llround(v) : (int64_t)std::llround(v * 100), (int64_t)std::llround(cap * 100), (int64_t)std::llround(mn * 100));
        if (r.ok && sv.autosave) { std::string e; a.save_all(&e); }
        return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
    }
    if (what == "coupon-state") {
        Result<Unit> r = a.set_coupon_active(rq.get("code"), rq.get("active") == "1");
        if (r.ok && sv.autosave) { std::string e; a.save_all(&e); }
        return r.ok ? ok(JObj().boolean("ok", true).str("message", r.message).done()) : fail_of(r);
    }
    if (what == "delays") {
        JArr arr;
        for (size_t i = a.delay_log.size(); i-- > 0 && arr.done().size() < 60000;) {
            const DelayLog &d = a.delay_log[i];
            const Trip *t = a.trip_by_id(d.trip_id);
            arr.add(JObj().str("at", fmt_datetime(d.at_ms)).str("route", t ? a.route_name(a.routes[(size_t)t->route_id]) : "").num("trip", d.trip_id).str("cause", d.cause).num("minutes", d.minutes).str("source", d.source).done());
        }
        return ok(arr.done());
    }
    if (what == "scan-traffic") {
        std::string rep;
        int n = a.scan_traffic_delays(&rep);
        if (sv.autosave) { std::string e; a.save_all(&e); }
        return ok(JObj().boolean("ok", true).num("changed", n).str("report", rep).done());
    }
    return err(404, "Unknown admin action");
}

static Resp h_share(Server &sv, const Req &rq, const std::string &what) {
    App &a = sv.app;
    if (what == "view") {                                               /* public, read-only: no names, no PNR */
        std::string tok = rq.get("token");
        if (tok.size() < 8 || tok.size() > 24 || tok.find_first_not_of("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-") != std::string::npos) return err(400, "That sharing link is malformed.");
        Booking *b = a.share_lookup(tok);
        if (!b) return err(404, "That sharing link is no longer active.");
        const Trip *t = a.trip_by_id(b->trip_id);
        return ok(JObj().str("route", a.route_name(a.routes[(size_t)t->route_id])).str("operator", a.bus_label(t->bus_idx)).str("type", a.types[(size_t)a.buses[(size_t)t->bus_idx].type_idx].label)
            .str("depart", fmt_datetime(t->depart_ms)).num("trip", t->id).raw("track", track_json(a, *t, -1, true)).done());
    }
    int u = user_of(sv, rq);
    if (!u) return err(401, "Please log in first");
    int bid = (int)rq.num("booking");
    if (what == "create") { Result<std::string> r = a.share_create(u, bid, rq.get("rotate") == "1"); if (sv.autosave) { std::string e; a.save_all(&e); } return r.ok ? ok(JObj().boolean("ok", true).str("token", r.value).done()) : fail_of(r); }
    if (what == "revoke") { Result<Unit> r = a.share_revoke(u, bid); if (sv.autosave) { std::string e; a.save_all(&e); } return r.ok ? ok(JObj().boolean("ok", true).done()) : fail_of(r); }
    return err(404, "Unknown share action");
}

static Resp h_assistant(Server &sv, const Req &rq) {
    AssistantAnswer r = sv.app.assistant(rq.get("text"));
    char iso[16] = "";
    if (r.date_key) std::snprintf(iso, sizeof iso, "%04d-%02d-%02d", r.date_key / 10000, (r.date_key / 100) % 100, r.date_key % 100);
    JArr ignored, types;                                                           /* the parse, so the page replays the same search */
    for (const std::string &s : r.ignored) ignored.add(jq(s));
    for (size_t i = 0; i < sv.app.types.size(); i++) if (r.type_mask & (1u << i)) types.add(JObj().num("idx", (long long)i).str("label", sv.app.types[i].label).done());
    return ok(JObj().str("text", r.text).str("from", r.from >= 0 ? sv.app.cities[(size_t)r.from].name : "").str("to", r.to >= 0 ? sv.app.cities[(size_t)r.to].name : "").str("date", iso).boolean("open_search", r.opened_search)
        .num("sort", r.sort_mode).num("dep_window", r.dep_window).num("dep_after", r.dep_after).num("dep_before", r.dep_before)
        .str("amenity", r.amenity).str("operator", r.operator_substr).raw("types", types.done()).raw("ignored", ignored.done()).done());
}

/* ---------- routing ---------- */

static Resp serve_file(Server &sv, const std::string &name) {
    if (name != "index.html") return err(404, "Page not found");   /* the page is the only file on disk we serve */
    /* Deliver the ASSEMBLED page only: tools/page_gen.cpp inlines Leaflet (CSS + JS) into web/index.html and
       writes build/web_page.html. The authoring copy on disk keeps two <script src="#"> placeholders, so it is
       never served - that page has no map library. The usual start-up folders are tried (repo root, bin/); each
       candidate gets its own ifstream, because reopening a failed stream on the same object leaves libstdc++
       reading zero bytes. If nothing on disk can be read, the copy compiled into the binary is served, which is
       the same assembled page ("make all" builds web_page.cpp from build/web_page.html), so the server also
       works when it is started from a folder that has no web/ next to it. */
    const std::string cand[3] = { sv.web_dir + "/build/web_page.html", "build/web_page.html", "../build/web_page.html" };
    for (int i = 0; i < 3; i++) {
        std::ifstream in(cand[i].c_str(), std::ios::binary);
        if (!in) continue;
        std::ostringstream ss;
        ss << in.rdbuf();
        if (ss.str().empty()) continue;
        Resp r;
        r.type = "text/html; charset=utf-8";
        r.body = ss.str();
        return r;
    }
    Resp r;
    r.type = "text/html; charset=utf-8";
    r.body.assign(reinterpret_cast<const char *>(sr_page_data), sr_page_len);
    return r;
}

/* The offline map background (spec 8, "built into the program, served at /basemap.json"). Prefer the file the
   operator generated (web/basemap.json) so coastlines show when they were supplied; a missing, empty or
   foreign file is ignored and the same document is generated from the catalogue instead, which means a machine
   that never ran --make-basemap still gets a background when every tile server is blocked. Answered once and
   cached: the catalogue cannot change under a running server. */
static Resp h_basemap(Server &sv) {
    if (sv.basemap_cache.empty()) {
        const std::string cand[3] = { sv.web_dir + "/basemap.json", "web/basemap.json", "../web/basemap.json" };
        for (int i = 0; i < 3; i++) {
            std::ifstream in(cand[i].c_str(), std::ios::binary);      /* a fresh stream per candidate: see serve_file */
            if (!in) continue;
            std::ostringstream ss;
            ss << in.rdbuf();
            std::string text = ss.str();
            if (text.size() < 200 || text.find("smartroute-basemap") == std::string::npos) continue;
            sv.basemap_cache = text;
            break;
        }
        if (sv.basemap_cache.empty()) sv.basemap_cache = sr::basemap_generated(sv.app);
    }
    Resp r;
    r.body = sv.basemap_cache;
    return r;
}

static Resp route(Server &sv, const Req &rq) {
    const std::string &p = rq.path;
    bool post = rq.method == "POST";
    if (rq.method == "GET" && (p == "/" || p == "/index.html")) return serve_file(sv, "index.html");
    if (rq.method == "GET" && p == "/basemap.json") return h_basemap(sv);
    if (p == "/api/state") return h_state(sv, rq);
    if (p == "/api/cities") return h_cities(sv, rq);
    if (p == "/api/register" && post) return h_auth(sv, rq, true);
    if (p == "/api/login" && post) return h_auth(sv, rq, false);
    if (p == "/api/guest" && post) return h_guest(sv, rq);
    if (p == "/api/lookup") return h_lookup(sv, rq);
    if (p == "/api/logout" && post) { sv.sessions.remove(rq.token); return ok(JObj().boolean("ok", true).done()); }
    if (p == "/api/search") return h_search(sv, rq);
    if (p == "/api/trip") { Trip *t = sv.app.trip_by_id((int)rq.num("id")); return t ? ok(trip_json(sv.app, *t, user_of(sv, rq))) : err(404, "Trip not found"); }
    if (p == "/api/hold" && post) return h_hold(sv, rq);
    if (p == "/api/quote" && post) return h_quote(sv, rq);
    if (p == "/api/bookings" && post) return h_book(sv, rq);
    if (p == "/api/bookings") return h_bookings(sv, rq);
    if (p == "/api/pay" && post) return h_pay(sv, rq);
    if (p == "/api/ticket") return h_ticket(sv, rq);
    if (p == "/api/cancel" && post) return h_cancel(sv, rq);
    if (p == "/api/track") return h_track(sv, rq);
    if (p == "/api/sim" && post) return h_sim(sv, rq);
    if (p == "/api/meta") return h_meta(sv, rq);
    if (p == "/api/adjacent") return h_adjacent(sv, rq);
    if (p == "/api/notifications") return h_notes(sv, rq);
    if (p == "/api/notifications/read" && post) { int u = user_of(sv, rq); if (u) sv.app.mark_all_read(u); return ok(JObj().boolean("ok", true).done()); }
    if (p == "/api/prefs" && post) { int u = user_of(sv, rq); if (u) sv.app.set_prefs(u, (int)rq.num("mask")); return ok(JObj().boolean("ok", true).done()); }
    if (p == "/api/plan") return h_plan(sv, rq);
    if (p == "/api/waitlist" && post) return h_waitlist(sv, rq);
    if (p == "/api/clock" && post) return h_clock(sv, rq);
    if (p == "/api/assistant" && post) return h_assistant(sv, rq);
    if (p.rfind("/api/share/", 0) == 0) return h_share(sv, rq, p.substr(11));
    if (p.rfind("/api/driver/", 0) == 0) return h_driver(sv, rq, p.substr(12));
    if (p.rfind("/api/admin/", 0) == 0) return h_admin(sv, rq, p.substr(11));
    if (p.rfind("/api/vendor/", 0) == 0) return h_vendor(sv, rq, p.substr(12));
    return err(404, "Unknown endpoint");
}

/* ---------- socket plumbing: one select() loop, so no client can stall the server ---------- */

enum ParseState { NEED_MORE, COMPLETE, BAD };

/* Parses a request that may still be arriving. Browsers open spare connections and send nothing,
 * or send a request in pieces, so "not complete yet" is a normal answer. */
static ParseState parse_request(const std::string &data, Req *rq) {
    size_t header_end = data.find("\r\n\r\n");
    if (header_end == std::string::npos) return data.size() > 16384 ? BAD : NEED_MORE;
    std::istringstream hs(data.substr(0, header_end));
    std::string line, target, version;
    std::getline(hs, line);
    std::istringstream rl(line);
    rl >> rq->method >> target >> version;
    if (rq->method.empty() || target.empty() || target[0] != '/') return BAD;
    size_t content_len = 0;
    while (std::getline(hs, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        size_t colon = line.find(':');
        if (colon == std::string::npos) continue;
        std::string k = line.substr(0, colon), v = line.substr(colon + 1);
        while (!v.empty() && v[0] == ' ') v.erase(0, 1);
        for (char &ch : k) ch = (char)std::tolower((unsigned char)ch);
        if (k == "content-length") content_len = (size_t)std::strtoul(v.c_str(), nullptr, 10);
        else if (k == "authorization" && v.rfind("Bearer ", 0) == 0) rq->token = v.substr(7);
        else if (k == "origin") rq->origin = v;
    }
    if (content_len > 65536) return BAD;
    if (data.size() < header_end + 4 + content_len) return NEED_MORE;      /* body still arriving */
    rq->body = data.substr(header_end + 4, content_len);
    size_t q = target.find('?');
    rq->path = target.substr(0, q);
    if (q != std::string::npos) parse_pairs(target.substr(q + 1), &rq->params);
    if (!rq->body.empty()) parse_pairs(rq->body, &rq->params);
    return COMPLETE;
}

/* CORS: allow the page itself, a page opened from disk (Origin "null") and localhost dev servers; nothing else. */
static std::string cors_origin(const std::string &o) {
    if (o == "null" || o.rfind("http://localhost:", 0) == 0 || o.rfind("http://127.0.0.1:", 0) == 0) return o;
    return "http://localhost:5173";
}

static void send_response(sock_t c, const Resp &r, const std::string &origin = "") {
    const char *reason = r.status == 200 ? "OK" : (r.status == 404 ? "Not Found" : (r.status == 401 ? "Unauthorized" : (r.status == 409 ? "Conflict" : (r.status == 402 ? "Payment Required" : (r.status == 429 ? "Too Many Requests" : "Bad Request")))));
    std::string out = "HTTP/1.1 " + std::to_string(r.status) + " " + reason + "\r\nContent-Type: " + r.type + "\r\nContent-Length: " + std::to_string(r.body.size()) +
        "\r\nAccess-Control-Allow-Origin: " + cors_origin(origin) + "\r\nVary: Origin\r\nAccess-Control-Allow-Headers: Content-Type, Authorization\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\n"
        "Cache-Control: no-store\r\nConnection: close\r\n\r\n" + r.body;
    size_t sent = 0;
    while (sent < out.size()) {
        int n = (int)send(c, out.data() + sent, (int)(out.size() - sent), 0);
        if (n <= 0) break;                                    /* client left or send timed out */
        sent += (size_t)n;
    }
}

/* Listens on the loopback address of one family only (this is a localhost demo server). */
static sock_t open_listener(int family, int port) {
    sock_t s = socket(family, SOCK_STREAM, 0);
    if (s == BAD_SOCK) return BAD_SOCK;
    int yes = 1;
#ifdef _WIN32
    setsockopt(s, SOL_SOCKET, SO_EXCLUSIVEADDRUSE, (const char *)&yes, sizeof yes);   /* Windows: REUSEADDR would let another program share the port */
#else
    setsockopt(s, SOL_SOCKET, SO_REUSEADDR, (const char *)&yes, sizeof yes);
#endif
    int ok = 0;
    if (family == AF_INET) {
        sockaddr_in a;
        std::memset(&a, 0, sizeof a);
        a.sin_family = AF_INET; a.sin_addr.s_addr = htonl(INADDR_LOOPBACK); a.sin_port = htons((unsigned short)port);
        ok = bind(s, (sockaddr *)&a, sizeof a) == 0;
    } else {
        sockaddr_in6 a;
        std::memset(&a, 0, sizeof a);
        a.sin6_family = AF_INET6; a.sin6_addr = in6addr_loopback; a.sin6_port = htons((unsigned short)port);
        setsockopt(s, IPPROTO_IPV6, IPV6_V6ONLY, (const char *)&yes, sizeof yes);
        ok = bind(s, (sockaddr *)&a, sizeof a) == 0;
    }
    if (!ok || listen(s, 32) != 0) { close_sock(s); return BAD_SOCK; }
    return s;
}

struct Client { sock_t s; std::string buf; std::chrono::steady_clock::time_point last; };

static constexpr size_t MAX_CLIENTS = 40;                    /* stays below the 64-socket select() limit on Windows */
static constexpr int IDLE_SECONDS = 15;

static void launch_browser(int port) {
    std::string url = "http://localhost:" + std::to_string(port);
#ifdef _WIN32
    std::string cmd = "start \"\" " + url;
#elif defined(__APPLE__)
    std::string cmd = "open " + url + " >/dev/null 2>&1 &";
#else
    std::string cmd = "xdg-open " + url + " >/dev/null 2>&1 &";
#endif
    if (std::system(cmd.c_str()) != 0) std::printf("(Could not open a browser automatically; open %s yourself.)\n", url.c_str());
}

int run_server(App &app, int port, const std::string &web_dir, bool autosave, bool open_browser) {
#ifdef _WIN32
    WSADATA wsa;
    if (WSAStartup(MAKEWORD(2, 2), &wsa) != 0) { std::printf("Winsock could not start.\n"); return 1; }
#endif
    std::vector<sock_t> listeners;
    sock_t v4 = open_listener(AF_INET, port);
    if (v4 == BAD_SOCK) { std::printf("Could not listen on port %d (is it already in use?). Try: bin/smartroute --serve %d\n", port, port + 1); return 1; }
    listeners.push_back(v4);
    sock_t v6 = open_listener(AF_INET6, port);               /* so "localhost" works whichever address the browser picks */
    if (v6 != BAD_SOCK) listeners.push_back(v6);
    Server sv(app, autosave, web_dir);
    sv.virt_anchor_ms = app.clock.now();                            /* real seconds from here on map onto the virtual timeline */
    std::printf("SmartRoute web UI (DEMO data) is running.\n  Open:  http://localhost:%d   (or http://127.0.0.1:%d)\n  Stop:  Ctrl+C\n", port, port);
    std::fflush(stdout);
    if (open_browser) launch_browser(port);
    std::vector<Client> clients;
    for (;;) {
        fd_set rd;
        FD_ZERO(&rd);
        int maxfd = 0;
        for (sock_t l : listeners) { FD_SET(l, &rd); maxfd = std::max(maxfd, (int)l); }
        for (const Client &c : clients) { FD_SET(c.s, &rd); maxfd = std::max(maxfd, (int)c.s); }
        timeval tv;
        tv.tv_sec = 1; tv.tv_usec = 0;
        int ready = select(maxfd + 1, &rd, nullptr, nullptr, &tv);
        auto now = std::chrono::steady_clock::now();
        /* The virtual clock follows real time (App::sync_wall_clock): without this tick a 10-minute seat
           hold could never expire while the server ran, leaving seats blocked by visitors who left. */
        app.sync_wall_clock(sv.virt_anchor_ms + std::chrono::duration_cast<std::chrono::milliseconds>(now - sv.anchor).count());
        if (ready > 0) {
            for (sock_t l : listeners) {
                if (!FD_ISSET(l, &rd)) continue;
                sock_t c = accept(l, nullptr, nullptr);
                if (c == BAD_SOCK) continue;
                if (clients.size() >= MAX_CLIENTS) { close_sock(clients.front().s); clients.erase(clients.begin()); }   /* drop the oldest */
#ifdef _WIN32
                DWORD to = 3000;
#else
                timeval to; to.tv_sec = 3; to.tv_usec = 0;
#endif
                setsockopt(c, SOL_SOCKET, SO_SNDTIMEO, (const char *)&to, sizeof to);
                clients.push_back(Client{c, "", now});
            }
        }
        std::vector<Client> keep;
        for (Client &c : clients) {
            bool close_it = false;
            if (ready > 0 && FD_ISSET(c.s, &rd)) {
                char buf[4096];
                int n = (int)recv(c.s, buf, sizeof buf, 0);
                if (n <= 0) close_it = true;                       /* client closed (e.g. an unused pre-connect) */
                else {
                    c.buf.append(buf, (size_t)n);
                    c.last = now;
                    Req rq;
                    ParseState st = parse_request(c.buf, &rq);
                    if (st == COMPLETE) {
                        Resp r;
                        if (rq.method == "OPTIONS") r.body = "{}";
                        else r = route(sv, rq);
                        std::printf("%s %s -> %d\n", rq.method.c_str(), rq.path.c_str(), r.status);   /* one line per request (spec 7) */
                        std::fflush(stdout);
                        send_response(c.s, r, rq.origin);
                        close_it = true;
                    } else if (st == BAD) {
                        std::printf("bad request -> 400\n");
                        std::fflush(stdout);
                        send_response(c.s, err(400, "Bad request"));
                        close_it = true;
                    }
                }
            } else if (std::chrono::duration_cast<std::chrono::seconds>(now - c.last).count() > IDLE_SECONDS) close_it = true;   /* idle too long */
            if (close_it) close_sock(c.s); else keep.push_back(std::move(c));
        }
        clients.swap(keep);
    }
}

}  // namespace sr

